  // ── Слова-«фоллбэк» из старых игр (используются, пока уроки не пройдены) ──
  const LEGACY_WORDS = [
    { ko:'꽃',   ru:'цветок', emoji:'🌸' },
    { ko:'사랑', ru:'любовь', emoji:'❤️' },
    { ko:'안녕', ru:'привет', emoji:'👋' },
    { ko:'김치', ru:'кимчи',  emoji:'🥬' },
    { ko:'비',   ru:'дождь',  emoji:'🌧️' },
    { ko:'봄',   ru:'весна',  emoji:'🌷' },
    { ko:'달',   ru:'луна',   emoji:'🌙' },
    { ko:'별',   ru:'звезда', emoji:'⭐' },
    { ko:'바다', ru:'море',   emoji:'🌊' },
    { ko:'책',   ru:'книга',  emoji:'📚' },
    { ko:'산',   ru:'гора',   emoji:'⛰️' },
    { ko:'고양이', ru:'кот',  emoji:'🐱' },
    { ko:'학교', ru:'школа',  emoji:'🏫' },
    { ko:'친구', ru:'друг',   emoji:'👫' },
    { ko:'화이팅', ru:'удачи!', emoji:'💪' }
  ];
  // Уроки, доступные игроку: пройденные + текущий
  function unlockedLessons() {
    const all = getAllLessons();
    if (isAdmin()) return all; // админу открыт весь словарь
    const p = getLessonProgress();
    return all.filter(l => p.completed.includes(l.id) || l.id === p.current);
  }
  // ── Пул слов для игр: уроки по уровню + самоизучение + сохранённые слова (вкл. фразы) ──
  // Уровень ученицы → ранг сложности; модуль → ранг (m1–m2 초급, m3–m5 중급, m6/m7 고급, m8 топик).
  // ВАЖНО: у каждого модуля ДОЛЖЕН быть ранг — иначе `MODULE_RANK[mid] || 0` даёт 0,
  // и слова продвинутого модуля (m7 4급, m8 6급) утекают новичкам в пул игр.
  const LEVEL_RANK  = { beginner: 0, inter: 1, advanced: 2, topik1: 3, topik2: 4 };
  const MODULE_RANK = { m1: 0, m2: 0, m3: 1, m4: 1, m5: 1, m6: 2, m7: 2, m8: 3 };
  function userLevelRank() { const id = getMyLevelId(); return (id in LEVEL_RANK) ? LEVEL_RANK[id] : -1; }
  // ID уроков, реально открытых прогрессом в конкретном модуле (по его ключу прогресса).
  function _moduleUnlockedIds(mid) {
    const pr = UStore.get(_moduleProgressKey(mid)) || {};
    const done = Array.isArray(pr.completed) ? pr.completed : [];
    return new Set([...done, pr.current].filter(Boolean));
  }
  // ── Классификаторы слов для игр (какой контент годится для какой механики) ──
  function _koLen(ko) { return [...String(ko || '')].length; }                            // символы (вкл. пробелы/знаки)
  function _koSyl(ko) { return [...String(ko || '').replace(/[\s?!.,~·]/g, '')].length; } // только слоги
  function _wHasEmoji(w) { return !!w && !!w.emoji && w.emoji !== '🌸'; }                  // есть «настоящее» эмодзи (для «Подбери картинку»)
  function _wShort(w)   { const k = String((w && w.ko) || ''); return !/\s/.test(k) && _koSyl(k) >= 1 && _koSyl(k) <= 6; } // одно короткое слово (память)
  function _wCompact(w) { const k = String((w && w.ko) || ''); return !/\s/.test(k) && _koSyl(k) >= 2 && _koSyl(k) <= 5; } // сборка из слогов
  function _wForChoice(w) { return _koLen((w && w.ko) || '') <= 16; }                      // влезает в карточку-вариант (слово или короткая фраза)
  // Лексика из «Самостоятельного изучения», пригодная для игр: чистый KO-RU нужного уровня.
  const _SS_KO_OK = /^[가-힣\s?!.,~]+$/; // только хангыль-слоги, пробелы и базовые знаки (не правила/символы ≈ ↔ / ( ))
  // Класс бага «вариант с вшитым ответом» (отзыв ученицы): ru-поле уроков бывает
  // с подсказкой спряжения («петь → 노래해요») — в карточках/SRS это уместно, а в
  // вариантах и подсказках игр выдаёт ответ. Глосс = часть до стрелки/черты.
  // Вторая половина класса: в словарике бывают записи с НЕкорейским ko (грамматика
  // «-고자 = -기 위해(서)», пары «가다 ↔ 오다», русские запросы из ИИ-словаря) — в
  // игровой пул пускаем только чистый корейский ko; в самом словарике всё остаётся.
  function _gameGloss(ru) { return String(ru || '').split(/[→↔|]/)[0].trim(); }
  function _wGameClean(w) { return !!(w && w.ko && _SS_KO_OK.test(String(w.ko).trim()) && _gameGloss(w.ru)); }
  function ssGameWords(maxRank) {
    const out = [];
    SELFSTUDY.forEach(sec => {
      if (sec.game === false) return;               // разделы-правила (произношение, син/антонимы) в игры не идут
      if (maxRank < (sec.gameLvl || 0)) return;     // по уровню ученицы
      ssGroups(sec).forEach(g => (g.words || []).forEach(row => {
        const ko = String(row[0] || '').trim(), ru = String(row[1] || '').trim();
        if (!ko || !ru || !_SS_KO_OK.test(ko)) return;
        const ex = String(row[2] || '');
        out.push({ ko, ru, example: /[가-힣]/.test(ex) ? ex : '' }); // пример держим, только если он по-корейски
      }));
    });
    return out;
  }
  // ── Источник слов для игр (тумблер на экране «Игры») ──
  // 'auto' — уроки + самообучение + словарик (как всегда); 'mine' — ТОЛЬКО сохранённые
  // «Мои слова». При нехватке сохранённых (<4 с переводом) тихо падаем на уроки,
  // чтобы ни одна игра не осталась без материала.
  function gameSource() { return UStore.get('gameSrc', 'auto') === 'mine' ? 'mine' : 'auto'; }
  function myWordsPoolRaw() {
    try { return getMyWords().filter(w => w && w.ko && w.ru); } catch (_) { return []; }
  }
  // Сохранённые слова, реально пригодные для игр (тот же фильтр чистоты, что и в общем
  // пуле): грамматика/пары с «=»/«↔» остаются в словарике, но в игровые варианты не идут.
  // Счётчики на тумблере считают ИМЕННО этот пул — иначе чип обещал бы «6 слов»,
  // а игры молча падали бы на слова уроков.
  function myWordsGamePool() { return myWordsPoolRaw().filter(_wGameClean); }
  function gameWordPool() {
    if (gameSource() === 'mine') {
      const mine = myWordsGamePool().map(w => ({ ko: w.ko, ru: w.ru, translit: w.translit || '', emoji: w.emoji || '🌸', example: '' }));
      if (mine.length >= 4) return mine;
    }
    return _lessonsWordPool();
  }
  function _lessonsWordPool() {
    const admin = isAdmin();
    // ФАЗА D1: хардкор приравнен к admin ТОЛЬКО для широты пула — вся остальная
    // admin-логика (права, доступ к разделам и т.п.) хардкор не трогает.
    const forceAll = admin || hardcoreOn();
    const rank = userLevelRank();              // -1 = уровень не выбран
    const seen = new Set(); const out = [];
    const add = w => {
      if (!w || !w.ko || !w.ru || seen.has(w.ko)) return;
      if (!_wGameClean(w)) return; // не-корейский ko (грамматика «-고자 = …», «가다 ↔ 오다», кириллица) — не для игр
      seen.add(w.ko);
      out.push({ ko: w.ko, ru: w.ru, translit: w.translit || '', emoji: w.emoji || '🌸', example: w.example || '' });
    };
    // 1) Слова уроков: целиком из модулей ≤ выбранного уровня + реально пройденные уроки прочих модулей.
    Object.keys(LESSON_MODULES).forEach(mid => {
      const lessons = LESSON_MODULES[mid].lessons || [];
      const byLevel = forceAll || (rank >= 0 && (MODULE_RANK[mid] || 0) <= rank);
      const src = byLevel ? lessons : lessons.filter(l => _moduleUnlockedIds(mid).has(l.id));
      src.forEach(l => { if (Array.isArray(l.vocab)) l.vocab.forEach(add); });
    });
    // 2) Лексика из «Самостоятельного изучения» по уровню (приветствия, фразы, темы…).
    ssGameWords(forceAll ? 99 : rank).forEach(add);
    // 3) Сохранённые слова ученицы — слова, грамматика И фразы (длинные фразы идут в флешкарты/слух/перевод).
    getMyWords().forEach(w => { if (w && w.ru) add(w); });
    // 4) Запасной набор — пока слов мало (новичок без прогресса и без выбранного уровня).
    if (out.length < 8) LEGACY_WORDS.forEach(add);
    return out;
  }
  function setGameSource(src) {
    const v = src === 'mine' ? 'mine' : 'auto';
    UStore.set('gameSrc', v);
    updateGameSourceUI();
    if (v === 'mine') {
      const n = myWordsGamePool().length;
      toast(n >= 4 ? t('games.src.onMine', { n: n }) : t('games.src.few'), 'var(--sage)');
    }
  }
  function updateGameSourceUI() {
    const src = gameSource();
    const a = document.getElementById('game-src-auto');
    const m = document.getElementById('game-src-mine');
    if (a) a.classList.toggle('active', src === 'auto');
    if (m) m.classList.toggle('active', src === 'mine');
    const nEl = document.getElementById('game-src-mine-n');
    if (nEl) nEl.textContent = '· ' + myWordsGamePool().length;
  }
  // ── ФАЗА D1: хардкор-режим 🔥 (открывается после 3 пройденных модулей) ──
  // Тумблер один на все игры сразу (не по каждой отдельно) — влияет на пул слов
  // (см. _lessonsWordPool: hardcore приравнивается к admin-ветке — берём словарь
  // ВСЕХ модулей, а не только открытых по прогрессу) и на визуальный таймер раунда
  // в Переводе/Сборке слова/Слухе (см. gameHeader).
  function hardcoreEligible() { return isAdmin() || Object.keys(LESSON_MODULES).filter(isModuleComplete).length >= 3; }
  function hardcoreOn() { return hardcoreEligible() && UStore.get('hardcore', false) === true; }
  function setHardcore(v) {
    UStore.set('hardcore', !!v);
    renderHardcoreToggle();
    if (v) toast(t('hc.on'), 'var(--coral)'); else toast(t('hc.off'));
  }
  function renderHardcoreToggle() {
    const slot = document.getElementById('hardcore-toggle-slot');
    if (!slot) return;
    if (!hardcoreEligible()) { slot.innerHTML = ''; return; }
    const on = hardcoreOn();
    slot.innerHTML = `
      <button type="button" role="switch" aria-checked="${on}" class="wt-chip${on ? ' active' : ''}" onclick="setHardcore(${!on})" style="margin-top:8px; display:flex; align-items:center; justify-content:center; min-height:44px;">
        🔥 <span>${t('hc.chip')}</span><span class="ko" style="color:var(--coral); font-weight:500; margin-left:6px;">고급</span>
      </button>
      <div style="font-size:10px; color:var(--hush); margin-top:6px; line-height:1.45;">${t('hc.hint')}</div>
    `;
  }
  // Кол-во раундов растёт с числом пройденных уроков (+1 за урок, максимум +6)
  function scaledRounds(base) {
    return base + Math.min(getLessonProgress().completed.length, 6);
  }
  // Словарь урока в виде текста (поддерживает массив {ko,ru} и строку)
  function vocabPreviewText(v) {
    if (!v) return '';
    if (typeof v === 'string') return v;
    if (Array.isArray(v)) return v.map(w => `${w.ko} — ${w.ru}`).join(' · ');
    return '';
  }
