  // Прямой вход с экрана «Уроки»: 'real' — официальные 회차, 'mock' — пробные (모의고사/EBS).
  // Пробные сейчас живут в TOPIK II, реальные стартуем с TOPIK I (бета-модуль). Уровень можно
  // переключить вкладками внутри экрана. После рендера — плавный скролл к нужной группе.
  // Куда вернуть кнопкой «назад», если в раздел ТОПИК зашли НАПРЯМУЮ (минуя меню).
  // Сбрасывается в switchScreen('topik') при обычном входе через меню.
  let _topikReturn = null;
  function openTopikGroup(kind) {
    const k = kind === 'mock' ? 'mock' : 'real';
    _topikLevel = k === 'mock' ? '2' : '1';
    switchScreen('topik');        // обнулит _topikReturn
    _topikReturn = 'lessons';     // ставим ПОСЛЕ: прямой вход — назад ведёт на Уроки
    openTopikSection('exams');
    setTimeout(() => {
      document.getElementById('topik-grp-' + k)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, 90);
  }
  // ФАЗА T3: карточка-ссылка «TOPIK-тренажёры» на экране игр — прямой вход в
  // «Практику» TOPIK I (там же живут «Связки»/«Порядок»); назад ведёт на Игры.
  function openTopikPracticeFromGames() {
    _topikLevel = '1';
    switchScreen('topik');
    _topikReturn = 'games';
    openTopikSection('practice');
  }
  function topikHome() {
    if (_topikReturn) { const r = _topikReturn; _topikReturn = null; _topikSection = null; switchScreen(r, true); return; }
    _topikSection = null; renderTopik(); requestAnimationFrame(() => _setScroll(_topikMenuScroll));
  }
  // Контекстная кнопка «назад» экрана ТОПИК:
  // раздел → меню уровня · меню уровня → экран выбора уровня · выбор уровня → на главную
  function topikBack() {
    if (_topikReturn) { const r = _topikReturn; _topikReturn = null; _topikSection = null; switchScreen(r, true); return; }
    if (_topikSection) { topikHome(); return; }
    if (_topikLevel) { _topikLevel = null; renderTopik(); window.scrollTo(0, 0); return; }
    switchScreen('home', true);
  }

  function topikAccordionHtml(items, idPrefix) {
    // Советы/Как решать/Подсказки — содержимое РАСКРЫТО по умолчанию (класс open):
    // ученик сразу видит текст, без лишнего клика. Шапку всё равно можно свернуть.
    return items.map((r, i) => `
      <div class="topik-rule open" id="${idPrefix}-${i}">
        <button type="button" class="topik-rule-head" onclick="this.parentElement.classList.toggle('open')">
          <span class="topik-rule-ico">${r.ico || r.icon || '•'}</span>
          <span class="topik-rule-title">${r.title}</span>
          <i class="fa-solid fa-chevron-down topik-rule-chev" aria-hidden="true"></i>
        </button>
        <div class="topik-rule-body">${r.body}</div>
      </div>`).join('');
  }
  function topikVocabThemeHtml(t, idx) {
    return `<div class="topik-rule" id="topik-voc-${idx}">
      <button type="button" class="topik-rule-head" onclick="this.parentElement.classList.toggle('open')">
        <span class="topik-rule-ico">${t.ico}</span>
        <span class="topik-rule-title">${t.title}</span>
        <span class="topik-group-count">${t.words.length}</span>
        <i class="fa-solid fa-chevron-down topik-rule-chev" aria-hidden="true"></i>
      </button>
      <div class="topik-rule-body"><div class="topik-words">${t.words.map(w => `
        <div class="topik-word"><span class="topik-word-ko ko">${w[0]}</span><span class="topik-word-ru">${w[1]}</span><span class="topik-word-ex ko">${w[2]}</span>${lessonSaveHeart(w[0], w[1] || '', '', '🌸', 'topik-theme', 'topik-word-save')}</div>`).join('')}</div></div>
    </div>`;
  }
  function topikAdminMatsHtml(kind, admin) {
    const items = getTopikMaterials().filter(m => m.kind === kind);
    if (!items.length) return '';
    return `<div class="topik-group" style="margin-top:14px;">
      <div class="topik-group-head"><span class="topik-group-ico">➕</span><span class="topik-group-label">${t('topik.addedByMadie')}</span><span class="topik-group-count">${items.length}</span></div>
      <div class="topik-mats">${items.map(m => topikMatCard(m, admin)).join('')}</div></div>`;
  }
  function topikSectionWrap(title, sub, inner, admin, addKind) {
    const backLabel = _topikReturn === 'lessons' ? t('nav.lessons') : t('topik.back.sections');
    return `
      <button type="button" class="topik-back" onclick="topikHome()"><i class="fa-solid fa-chevron-left"></i> ${backLabel}</button>
      <div class="topik-sec-head"><h2 class="topik-sec-title">${title}</h2><p class="topik-sec-sub">${sub}</p>
        ${admin && addKind ? `<button type="button" class="chip chip-coral topik-sec-add" onclick="showAdminPanel('topik')"><i class="fa-solid fa-plus" style="font-size:10px;"></i> ${t('topik.add')}</button>` : ''}</div>
      ${inner}`;
  }

  // ── ФАЗА T1/T2: экран «Практика» — Блиц-10 (бесплатно) + 오답노트 (Master) + плитки типов (Master) ──
  function renderTopikPractice(slot, lvl) {
    const types = topikTypesList(lvl);
    const wrongCount = topikWrongTotalCount();
    const tiles = types.map(ty => {
      const accTxt = ty.acc && ty.acc.total ? `${Math.round(ty.acc.right / ty.acc.total * 100)}% · ${ty.acc.total}` : t('topik.practice.new');
      return `
        <div class="topik-type-tile" onclick="startTopikDrill('${ty.id}')">
          <div class="topik-type-title">${escHtml(ty.title)}</div>
          <div class="topik-type-meta"><span>${ty.count} ${t('topik.practice.qCount')}</span><span>${accTxt}</span></div>
        </div>`;
    }).join('');
    slot.innerHTML = topikSectionWrap('🎯 ' + t('topik.t.practice'), t(lvl === 2 ? 'topik.h.practice2' : 'topik.h.practice1'), `
      ${renderWeakSpotWidget(lvl)}
      <button type="button" class="topik-exam-card" onclick="startTopikBlitz()">
        <span class="topik-exam-ico">🎯</span>
        <div class="topik-exam-tx">
          <div class="topik-exam-t">${t('topik.blitz.card')}</div>
          <div class="topik-exam-s">${t('topik.blitz.card.sub')}</div>
        </div>
        <i class="fa-solid fa-chevron-right topik-exam-arrow"></i>
      </button>
      <button type="button" class="topik-exam-card" style="margin-top:10px;" onclick="startTopikReview()">
        <span class="topik-exam-ico">📓</span>
        <div class="topik-exam-tx">
          <div class="topik-exam-t">${t('topik.review.card')}</div>
          <div class="topik-exam-s">${t('topik.review.card.sub', { n: wrongCount })}</div>
        </div>
        <i class="fa-solid fa-chevron-right topik-exam-arrow"></i>
      </button>
      <div class="topik-sec-sub" style="margin-top:18px; margin-bottom:8px;">${t('topik.practice.games')}</div>
      <div class="topik-type-grid">
        <div class="topik-type-tile" onclick="startLinks()">
          <div class="topik-type-title">🔗 ${t('games.links')}</div>
          <div class="topik-type-meta"><span>${t('games.links.sub')}</span><span>›</span></div>
        </div>
        ${lvl === 1 ? `
        <div class="topik-type-tile" onclick="startWordOrder()">
          <div class="topik-type-title">🔀 ${t('games.wordorder')}</div>
          <div class="topik-type-meta"><span>${t('games.wordorder.sub')}</span><span>›</span></div>
        </div>` : ''}
      </div>
      <div class="topik-sec-sub" style="margin-top:18px; margin-bottom:8px;">${t('topik.practice.decks')}</div>
      <div class="topik-type-grid">${renderTopikDecksSection(lvl)}</div>
      <div class="topik-sec-sub" style="margin-top:18px; margin-bottom:8px;">${t('topik.practice.byType')}</div>
      <div class="topik-type-grid">${tiles || `<div class="dx-empty">${t('topik.practice.empty')}</div>`}</div>
    `, false, null);
  }
  function renderTopikDecksSection(lvl) {
    const themes = lvl === 2 ? TOPIK2_VOCAB_THEMES : TOPIK_VOCAB_THEMES;
    return themes.map((th, i) => `
      <div onclick="openTopikDeckPicker(${lvl}, ${i})" class="topik-type-tile">
        <div class="topik-type-title">${th.ico} ${escHtml(th.title)}</div>
        <div class="topik-type-meta"><span>${th.words.length} ${t('topik.practice.qCount')}</span><span>›</span></div>
      </div>`).join('');
  }

  // Уровень раздела ТОПИК: '1' (TOPIK I), '2' (TOPIK II) или null — пока уровень не выбран
  // (показываем экран-развилку выбора уровня — вход с главной).
  let _topikLevel = null;
  function setTopikLevel(lvl) { _topikLevel = lvl; _topikSection = null; renderTopik(); window.scrollTo(0, 0); }
  // Вход с главной кнопки «Подготовка к ТОПИК»: сбрасываем уровень → сначала экран выбора.
  function openTopik() { _topikLevel = null; switchScreen('topik'); }
  // Выбор уровня на экране-развилке → открыть меню подготовки этого уровня.
  function chooseTopikLevel(lvl) {
    _topikLevel = lvl; _topikSection = null; renderTopik();
    const sc = document.getElementById('screen-topik'); if (sc) sc.scrollTop = 0;
    window.scrollTo(0, 0);
  }
  // Экран-развилка: две большие карточки — TOPIK I и TOPIK II.
  function renderTopikChooser(slot) {
    slot.innerHTML = `
      <div class="topik-hero">
        <div class="topik-hero-badge">TOPIK</div>
        <div class="topik-hero-title ko">한국어능력시험</div>
        <div class="topik-hero-sub">${t('topik.chooser.sub')}</div>
      </div>
      <div class="topik-level-pick">
        <button type="button" class="topik-entry be-real" onclick="chooseTopikLevel('1')" aria-label="TOPIK I">
          <span class="topik-entry-badge">TOPIK <b>I</b></span>
          <span class="topik-entry-text">
            <span class="topik-entry-title">${t('topik.lvl1.t')}</span>
            <span class="topik-entry-sub">${t('topik.lvl1.s')}</span>
          </span>
          <i class="fa-solid fa-chevron-right topik-entry-arrow" aria-hidden="true"></i>
        </button>
        <button type="button" class="topik-entry be-mock" onclick="chooseTopikLevel('2')" aria-label="TOPIK II">
          <span class="topik-entry-badge be-badge">TOPIK <b>II</b></span>
          <span class="topik-entry-text">
            <span class="topik-entry-title">${t('topik.lvl2.t')}</span>
            <span class="topik-entry-sub">${t('topik.lvl2.s')}</span>
          </span>
          <i class="fa-solid fa-chevron-right topik-entry-arrow" aria-hidden="true"></i>
        </button>
      </div>
      <div id="marathon-card-slot"></div>
      <div onclick="startLevelTest()" style="text-align:center; margin-top:16px; font-size:12.5px; color:var(--coral); font-weight:700; cursor:pointer;">
        🧪 ${t('leveltest.entryTopik')}
      </div>`;
    try { renderMarathonCard(); } catch (_) {}
  }
  function topikLevelTabs() {
    return `
      <div class="auth-tabs" style="margin-bottom:14px;">
        <button type="button" class="auth-tab ${_topikLevel === '1' ? 'auth-tab-active' : ''}" onclick="setTopikLevel('1')">TOPIK I · 초급</button>
        <button type="button" class="auth-tab ${_topikLevel === '2' ? 'auth-tab-active' : ''}" onclick="setTopikLevel('2')">TOPIK II · 중·고급</button>
      </div>`;
  }
  function renderTopikMenu(slot) {
    if (_topikLevel === '2') return renderTopik2Menu(slot);
    slot.innerHTML = `
      ${topikLevelTabs()}
      <div class="topik-hero">
        <div class="topik-hero-badge">TOPIK <b>I</b></div>
        <div class="topik-hero-title ko">한국어능력시험</div>
        <div class="topik-hero-sub">${t('topik.heroSub1')}</div>
      </div>
      <button type="button" class="topik-exam-card" onclick="openTopikSection('exams')">
        <div class="topik-exam-ico">📝</div>
        <div class="topik-exam-tx"><div class="topik-exam-t">${t('topik.exam.card')}</div><div class="topik-exam-s">${t('topik.exam.card.sub1')}</div></div>
        <i class="fa-solid fa-chevron-right topik-exam-arrow"></i>
      </button>
      <div class="topik-menu-grid">
        ${TOPIK_SECTIONS.map(x => `
          <button type="button" class="topik-menu-card" onclick="openTopikSection('${x.k}')">
            <span class="topik-menu-ico">${x.ico}</span>
            <span class="topik-menu-t">${t(x.tk)}</span>
            <span class="topik-menu-s">${t(x.sk)}</span>
          </button>`).join('')}
      </div>`;
  }
  function renderTopik2Menu(slot) {
    slot.innerHTML = `
      ${topikLevelTabs()}
      <div class="topik-hero">
        <div class="topik-hero-badge">TOPIK <b>II</b></div>
        <div class="topik-hero-title ko">한국어능력시험</div>
        <div class="topik-hero-sub">중·고급 · уровни 3–6급 · 듣기 + 쓰기 + 읽기</div>
      </div>
      <button type="button" class="topik-exam-card" onclick="openTopikSection('exams')">
        <div class="topik-exam-ico">📝</div>
        <div class="topik-exam-tx"><div class="topik-exam-t">${t('topik.exam.card')}</div><div class="topik-exam-s">${t('topik.exam.card.sub2')}</div></div>
        <i class="fa-solid fa-chevron-right topik-exam-arrow"></i>
      </button>
      <div class="topik-menu-grid">
        ${TOPIK2_SECTIONS.map(x => `
          <button type="button" class="topik-menu-card" onclick="openTopikSection('${x.k}')">
            <span class="topik-menu-ico">${x.ico}</span>
            <span class="topik-menu-t">${t(x.tk)}</span>
            <span class="topik-menu-s">${t(x.sk)}</span>
          </button>`).join('')}
      </div>`;
  }

  function renderTopikExams(slot, admin) {
    const exams = [102, 96, 91, 83, 64, 60, 52, 47, 41];
    const cardFor = (n) => `
      <div class="topik-exam-row">
        <div class="topik-exam-no">제<b>${n}</b>회</div>
        <div class="topik-exam-parts">
          <button type="button" class="topik-part-btn topik-part-read" onclick="startTopikExam(${n},'reading')"><span class="ko">읽기</span> ${t('topik.exam.read')}</button>
          <button type="button" class="topik-part-btn topik-part-listen" onclick="startTopikExam(${n},'listening')"><span class="ko">듣기</span> ${t('topik.exam.listen')}</button>
        </div>
      </div>`;
    const group = (id, ico, label, sub, cardsHtml, count, emptyMsg) => `
      <div id="topik-grp-${id}" class="topik-group" style="margin-top:16px;">
        <div class="topik-group-head"><span class="topik-group-ico">${ico}</span><span class="topik-group-label">${label}</span>${count ? `<span class="topik-group-count">${count}</span>` : ''}</div>
        <div style="font-size:11px; color:var(--soft); margin:2px 0 8px;">${sub}</div>
        ${cardsHtml ? `<div class="topik-exams-list">${cardsHtml}</div>` : `<div class="topik-note">${emptyMsg}</div>`}
      </div>`;
    slot.innerHTML = topikSectionWrap(t('topik.exam.t1.title'), t('topik.exam.t1.sub'), `
      <div class="topik-note" style="margin:0 0 14px;">${t('topik.exam.t1.note')}</div>
      ${group('real', '🏛️', t('topik.grp.real'), t('topik.grp.real.sub1'), exams.map(cardFor).join(''), exams.length, '')}
      ${group('mock', '🧪', t('topik.grp.mock'), t('topik.grp.mock.sub1'), '', 0, t('topik.grp.mock.empty1'))}`, false, null);
  }

  // ─────────────── TOPIK II (중·고급): экзамены + 쓰기 ───────────────
  function renderTopik2Exams(slot) {
    // Банки ещё не подгрузились — показываем «загрузка» и запускаем ленивую загрузку;
    // по завершении ensureTopikExams перерисует текущий раздел (renderTopik сохраняет секцию).
    if (!topikExamsReady()) {
      ensureTopikExams();
      slot.innerHTML = topikSectionWrap(t('topik.exam.t2.title'), t('topik.exam.t2.sub'), `<div class="topik-note" style="text-align:center; padding:24px 12px;">${t('topik.loadingExams')}</div>`, false, null);
      return;
    }
    const ex2 = t2Exams();
    const nums = Object.keys(ex2).map(Number);
    const realNos = nums.filter(n => !ex2[n].mock).sort((a, b) => b - a);
    const mockNos = nums.filter(n => ex2[n].mock).sort((a, b) => a - b); // EBS(1) → моки 3급..6급 (3001..6001) по возрастанию
    const cardFor = (n) => {
      const ex = ex2[n];
      const btn = (part, cls, ko, ru, fn) => {
        const has = part === 'writing' ? (ex.writing && ex.writing.tasks && ex.writing.tasks.length)
                                       : (ex[part] && ex[part].questions && ex[part].questions.length);
        return `<button type="button" class="topik-part-btn ${cls}${has ? '' : ' topik-part-soon'}" ${has ? `onclick="${fn}"` : `disabled title="${t('topik.exam.prep')}"`}><span class="ko">${ko}</span> ${ru}${has ? '' : ' · ' + t('topik.exam.soon')}</button>`;
      };
      return `
      <div class="topik-exam-row">
        <div class="topik-exam-no">${ex.no || `제<b>${n}</b>회`}</div>
        <div class="topik-exam-parts">
          ${ex.readingOnly ? '' : btn('listening', 'topik-part-listen', '듣기', t('topik.exam.listen'), `startTopikExam(${n},'listening',2)`)}
          ${ex.readingOnly ? '' : btn('writing', 'topik-part-write', '쓰기', t('topik.exam.write'), `startTopikWriting(${n})`)}
          ${btn('reading', 'topik-part-read', '읽기', t('topik.exam.read'), `startTopikExam(${n},'reading',2)`)}
        </div>
      </div>`;
    };
    const group = (id, ico, label, sub, nosArr, emptyMsg) => `
      <div id="topik-grp-${id}" class="topik-group" style="margin-top:16px;">
        <div class="topik-group-head"><span class="topik-group-ico">${ico}</span><span class="topik-group-label">${label}</span>${nosArr.length ? `<span class="topik-group-count">${nosArr.length}</span>` : ''}</div>
        <div style="font-size:11px; color:var(--soft); margin:2px 0 8px;">${sub}</div>
        ${nosArr.length ? `<div class="topik-exams-list">${nosArr.map(cardFor).join('')}</div>` : `<div class="topik-note">${emptyMsg}</div>`}
      </div>`;
    slot.innerHTML = topikSectionWrap(t('topik.exam.t2.title'), t('topik.exam.t2.sub'), `
      <div class="topik-note" style="margin:0 0 14px;">${t('topik.exam.t2.note')}</div>
      ${group('real', '🏛️', t('topik.grp.real'), t('topik.grp.real.sub2'), realNos, t('topik.grp.real.empty2'))}
      ${group('mock', '🧪', t('topik.grp.mock'), t('topik.grp.mock.sub2'), mockNos, t('topik.grp.mock.empty2'))}`, false, null);
  }
  function renderTopik2About(slot) {
    slot.innerHTML = topikSectionWrap(t('topik.about2.title'), t('topik.about2.sub'), `
      <div class="card card-padded" style="margin-bottom:12px;">
        <div style="display:grid; gap:8px; font-size:13px; line-height:1.55;">
          <div>📋 <b>3 раздела:</b> <span class="ko">듣기</span> 50 вопросов (60 мин) · <span class="ko">쓰기</span> 4 задания (50 мин) · <span class="ko">읽기</span> 50 вопросов (70 мин).</div>
          <div>💯 <b>Баллы:</b> каждый раздел по 100 — всего 300.</div>
          <div>🎯 <b>Уровни по сумме:</b> 3급 — от 120 · 4급 — от 150 · 5급 — от 190 · 6급 — от 230.</div>
          <div>🕐 <b>Сессии:</b> сначала 듣기+쓰기 подряд (110 мин), после перерыва — 읽기.</div>
          <div>✍️ <b>쓰기:</b> №51–52 — вписать предложение в пропуск (по 10 б.), №53 — текст по графику 200–300 знаков (30 б.), №54 — эссе 600–700 знаков (50 б.).</div>
          <div>⚡ Все вопросы 듣기/읽기 — по 2 балла, сложность растёт от первого к последнему.</div>
        </div>
      </div>
      <div class="topik-note">Готовишься на 3–4급? Сосредоточься на вопросах 1–25 каждого раздела и заданиях 51–53 — этого хватает для прохода.</div>`, false, null);
  }
  function renderTopik2WritingGuide(slot) {
    slot.innerHTML = topikSectionWrap(t('topik.writing2.title'), t('topik.writing2.sub'), `
      <div style="display:grid; gap:10px;">
        <div class="card card-padded">
          <div style="font-weight:700; margin-bottom:6px;">51–52 · Вписать предложение <span class="chip" style="font-size:10px;">по 10 б.</span></div>
          <div style="font-size:12.5px; line-height:1.55; color:var(--text2);">Два пропуска ㉠ и ㉡ в коротком тексте (объявление, письмо, заметка). Смотри на <b>стиль текста</b> (формальный/неформальный), <b>связки</b> (그래서, -기 때문에…) и что логически должно стоять в пропуске. Пиши законченное предложение, согласованное по стилю с остальным текстом.</div>
        </div>
        <div class="card card-padded">
          <div style="font-weight:700; margin-bottom:6px;">53 · Текст по графику <span class="chip" style="font-size:10px;">30 б.</span></div>
          <div style="font-size:12.5px; line-height:1.55; color:var(--text2);">200–300 знаков по диаграмме/таблице. Структура: <b>① что исследовали</b> → <b>② главные цифры</b> (조사 결과… -로 나타났다) → <b>③ причины/вывод</b>. Только письменный стиль: <b>-ㄴ다/-는다</b>, никаких -아요/어요!</div>
        </div>
        <div class="card card-padded">
          <div style="font-weight:700; margin-bottom:6px;">54 · Эссе <span class="chip" style="font-size:10px;">50 б.</span></div>
          <div style="font-size:12.5px; line-height:1.55; color:var(--text2);">600–700 знаков на общественную тему (3 вопроса в задании = 3 части эссе). План: вступление (важность темы) → ответы на каждый вопрос с примерами → вывод. Стиль -ㄴ다/-는다, сложные связки (뿐만 아니라, -음에도 불구하고…).</div>
        </div>
        <div class="card card-padded">
          <div style="font-weight:700; margin-bottom:6px;">Критерии проверяющих</div>
          <div style="font-size:12.5px; line-height:1.6; color:var(--text2);">
            ① <b>Содержание</b> — раскрыта ли тема полностью;<br>
            ② <b>Структура</b> — логичные абзацы и связки;<br>
            ③ <b>Язык</b> — грамматика и лексика своего уровня без ошибок;<br>
            ④ <b>Объём</b> — меньше минимума = большой штраф. Лучше простыми предложениями, но точно и в объёме!
          </div>
        </div>
      </div>`, false, null);
  }

  // Данные TOPIK II: { reading:{50}, listening:{50}, writing:{tasks:4} } — заполняется по мере постройки
  // 쓰기 №83 и №91 — реальные задания с официальных опубликованных тестов (topik.go.kr).
  // TOPIK2_EXAMS вынесен в assets/topik/exams-data.js (ленивая загрузка ensureTopikExams)

  // ── 쓰기-режим: 4 задания, таймер 50 мин, самооценка по критериям ──
  let _w2State = null, _w2Timer = null;
  function startTopikWriting(n) {
    if (!topikExamsReady()) { toast(t('topik.loadingExams'), 'var(--berry)'); ensureTopikExams().then(() => startTopikWriting(n)); return; }
    const data = (t2Exams()[n] || {}).writing;
    if (!data || !data.tasks || !data.tasks.length) { toast(t('topik.sectionSoon'), 'var(--berry)'); return; }
    _w2State = { exam: n, label: data.label, tasks: data.tasks, answers: {}, endAt: Date.now() + (data.durationMin || 50) * 60000, finished: false };
    let ov = document.getElementById('topik-exam-overlay');
    if (!ov) { ov = document.createElement('div'); ov.id = 'topik-exam-overlay'; ov.className = 'exam-overlay'; document.body.appendChild(ov); }
    document.body.style.overflow = 'hidden';
    renderW2();
    clearInterval(_w2Timer);
    _w2Timer = setInterval(() => {
      if (!_w2State || _w2State.finished) { clearInterval(_w2Timer); return; }
      const left = _w2State.endAt - Date.now();
      const el = document.getElementById('w2-timer');
      if (el) { el.textContent = '⏱ ' + examFmtTime(left); el.classList.toggle('low', left < 5 * 60000); }
      if (left <= 0) { clearInterval(_w2Timer); finishW2(); }
    }, 1000);
  }
  function exitW2() {
    clearInterval(_w2Timer); _w2State = null;
    document.getElementById('topik-exam-overlay')?.remove();
    document.body.style.overflow = '';
  }
  function _w2Count(id) {
    const t = (document.getElementById('w2-in-' + id)?.value || '');
    return t.replace(/\s/g, '').length; // знаки без пробелов (ориентир для 원고지)
  }
  function w2Input(id) {
    if (!_w2State) return;
    const el = document.getElementById('w2-cnt-' + id);
    const task = _w2State.tasks.find(t => String(t.n) === String(id));
    if (el && task && task.min) {
      const c = _w2Count(id);
      el.textContent = c + ' зн.';
      el.style.color = c < task.min ? 'var(--bad-ink)' : c > task.max ? 'var(--gold-ink)' : 'var(--ok-ink)';
    }
  }
  function renderW2() {
    const ov = document.getElementById('topik-exam-overlay');
    if (!ov || !_w2State) return;
    const tasksHtml = _w2State.tasks.map(task => {
      const id = String(task.n);
      const long = !!task.min;
      let body;
      if (task.blanks) {
        // 51~52: один текст с двумя пропусками ㉠/㉡ — заполняем оба
        body = `<div style="display:grid; gap:10px; margin-top:2px;">` + task.blanks.map(b => `
            <div>
              <div style="font-size:13px; font-weight:800; color:var(--coral); margin-bottom:4px;">${b.slot}</div>
              <input id="w2-in-${id}-${b.slot}" class="input ko" placeholder="${t('ui.173',{slot: b.slot})}" autocomplete="off">
            </div>`).join('') + `</div>`;
      } else if (long) {
        body = `<textarea id="w2-in-${id}" class="input ko" rows="${task.n === 54 ? 10 : 6}" oninput="w2Input('${id}')" placeholder="${task.min}–${task.max} знаков · стиль -ㄴ다/-는다" style="resize:vertical; line-height:1.7;"></textarea>`;
      } else { body = ''; }
      return `
        <div class="card card-padded" style="margin-bottom:14px;">
          <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
            <div style="font-weight:800;">№${task.n} <span class="chip" style="font-size:10px; margin-left:6px;">${task.points} б.</span></div>
            ${long ? `<span id="w2-cnt-${id}" style="font-size:11px; color:var(--soft);">${t('ui.174')}</span>` : ''}
          </div>
          ${task.korInstr ? `<div class="ko" style="font-size:12.5px; font-weight:700; color:var(--berry); margin-bottom:6px;">${task.korInstr}</div>` : ''}
          ${task.instr ? `<div style="font-size:12.5px; color:var(--text2); margin-bottom:8px;">${task.instr}</div>` : ''}
          ${task.image ? `<img src="${task.image}" alt="${t('ui.175',{n: task.n})}" style="width:100%; border-radius:12px; border:1px solid var(--line); margin-bottom:10px; background:#fff;">` : ''}
          ${task.passage ? `<div class="exam-passage ko" style="margin-bottom:10px; white-space:pre-wrap;">${task.passage}</div>` : ''}
          ${body}
        </div>`;
    }).join('');
    ov.innerHTML = `
      <div class="exam-top">
        <button onclick="exitW2()" class="chat-back-btn" aria-label="${t('ui.176')}" style="width:38px; height:38px;"><i class="fa-solid fa-xmark"></i></button>
        <div style="font-weight:800; font-size:14px; flex:1;">${_w2State.label || ('쓰기 · 제' + _w2State.exam + '회 (51~54)')}</div>
        <span id="w2-timer" class="exam-timer">⏱ 50:00</span>
      </div>
      <div class="exam-results" style="overflow-y:auto; flex:1;">
        <div class="topik-note" style="margin-bottom:14px;">✍️ Пиши как на настоящем экзамене: №51–52 — впиши пропущенные предложения (㉠ и ㉡), №53 — описание данных (200–300 знаков), №54 — эссе (600–700 знаков). Автопроверки нет — в конце сравнишь с образцом (모범답안) и критериями.</div>
        ${tasksHtml}
        <button onclick="finishW2()" class="btn btn-primary btn-block" style="margin-top:4px;">Завершить 쓰기 ✓</button>
        <div style="height:30px;"></div>
      </div>`;
  }
  function finishW2() {
    if (!_w2State || _w2State.finished) return;
    _w2State.finished = true;
    clearInterval(_w2Timer);
    const ov = document.getElementById('topik-exam-overlay');
    if (!ov) return;
    const rows = _w2State.tasks.map(task => {
      const id = String(task.n);
      if (task.blanks) {
        const inner = task.blanks.map(b => {
          const my = (document.getElementById('w2-in-' + id + '-' + b.slot)?.value || '').trim();
          return `
            <div style="margin-bottom:12px;">
              <div style="font-size:12px; color:var(--soft); margin-bottom:3px;"><b style="color:var(--coral);">${b.slot}</b> · твой ответ:</div>
              <div class="ko" style="white-space:pre-wrap; font-size:13.5px; line-height:1.7; background:var(--veil); border-radius:10px; padding:9px 11px;">${escHtml(my) || '<i style="color:var(--hush)">— пусто —</i>'}</div>
              <div style="font-size:12px; color:var(--soft); margin:7px 0 3px;">모범답안 · образец:</div>
              <div class="ko" style="white-space:pre-wrap; font-size:13.5px; line-height:1.7; background:rgba(var(--accent-rgb),.08); border-radius:10px; padding:9px 11px;">${b.model}</div>
              ${b.check ? `<div style="font-size:12px; color:var(--text2); margin-top:6px; line-height:1.55;">✅ ${b.check}</div>` : ''}
            </div>`;
        }).join('');
        return `
          <div class="card card-padded" style="margin-bottom:12px;">
            <div style="margin-bottom:8px;"><b>№${task.n}</b> <span class="chip" style="font-size:10px; margin-left:4px;">${task.points} б.</span></div>
            ${inner}
          </div>`;
      }
      const my = (document.getElementById('w2-in-' + id)?.value || '').trim();
      const cnt = my.replace(/\s/g, '').length;
      const lenNote = task.min ? `<span style="font-size:11px; color:${cnt < task.min ? 'var(--bad-ink)' : 'var(--ok-ink)'};">${cnt} зн. ${cnt < task.min ? '· меньше минимума!' : '✓'}</span>` : '';
      return `
        <div class="card card-padded" style="margin-bottom:12px;">
          <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px;">
            <b>№${task.n}</b> <span class="chip" style="font-size:10px; margin-left:4px;">${task.points} б.</span>${lenNote}
          </div>
          <div style="font-size:12px; color:var(--soft); margin-bottom:4px;">${t('ui.177')}</div>
          <div class="ko" style="white-space:pre-wrap; font-size:13.5px; line-height:1.7; background:var(--veil); border-radius:10px; padding:10px 12px;">${escHtml(my) || '<i style="color:var(--hush)">— пусто —</i>'}</div>
          ${task.model ? `
            <div style="font-size:12px; color:var(--soft); margin:10px 0 4px;">모범답안 · образцовый ответ:</div>
            <div class="ko" style="white-space:pre-wrap; font-size:13.5px; line-height:1.7; background:rgba(var(--accent-rgb),.08); border-radius:10px; padding:10px 12px;">${task.model}</div>` : ''}
          ${task.check ? `<div style="font-size:12px; color:var(--text2); margin-top:10px; line-height:1.55;">✅ Проверь себя: ${task.check}</div>` : ''}
        </div>`;
    }).join('');
    ov.querySelector('.exam-results').innerHTML = `
      <div class="exam-score-card" style="margin-bottom:16px;">
        <div class="display" style="font-size:26px; color:var(--berry);">쓰기 готово ✍️</div>
        <div style="font-size:12.5px; color:var(--soft); margin-top:6px;">${t('ui.178')}</div>
      </div>
      ${rows}
      <button onclick="exitW2()" class="btn btn-primary btn-block">${t('ui.041')}</button>
      <div style="height:30px;"></div>`;
    ov.querySelector('.exam-results').scrollTop = 0;
    try { addXp(15); } catch (_) {}
  }

  function renderTopikSection(slot, k, admin) {
    if (k === 'practice' || k === 'practice2') return renderTopikPractice(slot, k === 'practice2' ? 2 : 1);
    if (k === 'exams') return _topikLevel === '2' ? renderTopik2Exams(slot) : renderTopikExams(slot, admin);
    if (k === 'about2') return renderTopik2About(slot);
    if (k === 'writing2') return renderTopik2WritingGuide(slot);
    if (k === 'words2') {
      slot.innerHTML = topikSectionWrap('📖 ' + t('topik.t.words'), t('topik.h.words2'), `
        <div class="topik-rules">${TOPIK2_VOCAB_THEMES.map((th, i) => topikVocabThemeHtml(th, i)).join('')}</div>`, false, null);
      return;
    }
    if (k === 'grammar2') {
      const groups2 = TOPIK2_GRAMMAR.map(g => `
        <div class="topik-group">
          <div class="topik-group-head"><span class="topik-group-label">${g.title}</span><span class="topik-group-count">${g.items.length}</span></div>
          <div class="topik-gram">${g.items.map(it => `
            <div class="topik-gram-row"><span class="topik-gram-k ko">${it[0]}</span><span class="topik-gram-m">${it[1]}</span><span class="topik-gram-e ko">${it[2]}</span></div>`).join('')}</div>
        </div>`).join('');
      slot.innerHTML = topikSectionWrap('🧩 ' + t('topik.t.grammar'), t('topik.h.grammar2'), groups2, false, null);
      return;
    }
    if (k === 'tips2') {
      slot.innerHTML = topikSectionWrap('💡 ' + t('topik.t.tips'), t('topik.h.tips2'), `
        <div class="topik-rules">${topikAccordionHtml(TOPIK2_TIPS, 'topik2-tip')}</div>`, false, null);
      return;
    }
    if (k === 'howto2') {
      slot.innerHTML = topikSectionWrap('🎯 ' + t('topik.t.howto'), t('topik.h.howto2'), `
        <div class="topik-rules">${topikAccordionHtml(TOPIK2_HOWTO, 'topik2-how')}</div>`, false, null);
      return;
    }
    if (k === 'hints2') {
      slot.innerHTML = topikSectionWrap('✨ ' + t('topik.t.hints'), t('topik.h.hints2'), `
        <div class="topik-rules">${topikAccordionHtml(TOPIK2_HINTS, 'topik2-hint')}</div>`, false, null);
      return;
    }
    if (k === 'words') {
      slot.innerHTML = topikSectionWrap('📖 ' + t('topik.t.words'), t('topik.h.words1'), `
        <div class="topik-rules">${TOPIK_VOCAB_THEMES.map((th, i) => topikVocabThemeHtml(th, i)).join('')}</div>
        ${topikAdminMatsHtml('vocab', admin)}`, admin, 'vocab');
      return;
    }
    if (k === 'grammar') {
      const groups = TOPIK_GRAMMAR.map(g => `
        <div class="topik-group">
          <div class="topik-group-head"><span class="topik-group-label">${g.title}</span><span class="topik-group-count">${g.items.length}</span></div>
          <div class="topik-gram">${g.items.map(it => `
            <div class="topik-gram-row"><span class="topik-gram-k ko">${it[0]}</span><span class="topik-gram-m">${it[1]}</span><span class="topik-gram-e ko">${it[2]}</span></div>`).join('')}</div>
        </div>`).join('');
      slot.innerHTML = topikSectionWrap('🧩 ' + t('topik.t.grammar'), t('topik.h.grammar1'), groups + topikAdminMatsHtml('grammar', admin), admin, 'grammar');
      return;
    }
    if (k === 'tips') {
      slot.innerHTML = topikSectionWrap('💡 ' + t('topik.t.tips'), t('topik.h.tips1'), `
        <div class="topik-rules">${topikAccordionHtml(TOPIK_TIPS, 'topik-tip')}</div>
        ${topikAdminMatsHtml('tip', admin)}`, admin, 'tip');
      return;
    }
    if (k === 'howto') {
      slot.innerHTML = topikSectionWrap('🎯 ' + t('topik.t.howto'), t('topik.h.howto1'), `
        <div class="topik-rules">${topikAccordionHtml(TOPIK_HOWTO, 'topik-how')}</div>`, false, null);
      return;
    }
    if (k === 'hints') {
      slot.innerHTML = topikSectionWrap('✨ ' + t('topik.t.hints'), t('topik.h.hints1'), `
        <div class="topik-rules">${topikAccordionHtml(TOPIK_HINTS, 'topik-hint')}</div>`, false, null);
      return;
    }
    if (k === 'mustknow') {
      const read = topikReadSet();
      const rulesHtml = TOPIK_WRITING_RULES.map(r => `
        <div class="topik-rule ${read.has(r.id) ? 'read' : ''}" id="topik-rule-${r.id}">
          <button type="button" class="topik-rule-head" onclick="toggleTopikRule('${r.id}')">
            <span class="topik-rule-ico">${r.icon}</span>
            <span class="topik-rule-title">${r.title}</span>
            <span class="topik-rule-check" aria-hidden="true">✓</span>
            <i class="fa-solid fa-chevron-down topik-rule-chev" aria-hidden="true"></i>
          </button>
          <div class="topik-rule-body">${r.body}</div>
        </div>`).join('');
      slot.innerHTML = topikSectionWrap('📌 ' + t('topik.t.mustknow'), t('topik.h.mustknow'), `
        <div class="card card-padded topik-about">
          <p>${t('topik.mk.about')}</p>
          <table class="topik-table">
            <tr><th>${t('topik.mk.col.sec')}</th><th>${t('topik.mk.col.q')}</th><th>${t('topik.mk.col.time')}</th></tr>
            <tr><td><span class="ko">듣기</span> · ${t('topik.mk.listen')}</td><td>30</td><td>40 ${t('topik.mk.min')}</td></tr>
            <tr><td><span class="ko">읽기</span> · ${t('topik.mk.read')}</td><td>40</td><td>60 ${t('topik.mk.min')}</td></tr>
          </table>
          <div class="topik-grades">${t('topik.mk.grades')}</div>
          <p class="topik-note">${t('topik.mk.note')}</p>
        </div>
        <div class="section-head" style="margin-top:18px;">
          <div class="left"><div class="rule"></div><span class="title">${t('topik.mk.basics')}</span></div>
          <span class="meta">${t('topik.mk.readCount')} <span id="topik-read-count">0/${TOPIK_WRITING_RULES.length}</span></span>
        </div>
        <div class="topik-rules">${rulesHtml}</div>
        ${topikAdminMatsHtml('file', admin)}`, admin, 'file');
      updateTopikReadCount();
      return;
    }
    renderTopikMenu(slot);
  }

  function renderTopik() {
    const slot = document.getElementById('topik-hub');
    if (!slot) return;
    const admin = isAdmin();
    if (!_topikLevel && !_topikSection) { renderTopikChooser(slot); return; }
    if (!_topikSection) { renderTopikMenu(slot); return; }
    renderTopikSection(slot, _topikSection, admin);
  }

  // ─────────────── Самостоятельное изучение (Self-study hub) ───────────────
  // Материалы из методичек, адаптированные под наш бренд (перевод на русский + примеры).
