  function tdRenderHub(slot) {
    slot.innerHTML = `
      <div class="topik-hero">
        <div class="topik-hero-badge">심화 🎯</div>
        <div class="topik-hero-title">${t('ui.184')}</div>
        <div class="topik-hero-sub">${t('ui.185')}</div>
      </div>
      <div class="topik-menu-grid">
        ${TOPIK_DEEP_SECTIONS.map(s => `
          <button type="button" class="topik-menu-card${s.ready ? '' : ' td-soon'}" onclick="tdPickSection('${s.k}')" aria-label="${skLoc(s,'t')}">
            <span class="topik-menu-ico" aria-hidden="true">${s.ico}</span>
            <span class="topik-menu-t">${skLoc(s,'t')}</span>
            <span class="topik-menu-s">${skLoc(s,'s')}</span>
            ${s.ready ? '' : '<span class="td-soon-tag">' + t('ui.186') + '</span>'}
          </button>`).join('')}
      </div>`;
  }
  function tdLevelHint(lvl) {
    return lvl === 3 ? t('td.lvl3') : lvl === 4 ? t('td.lvl4') : lvl === 5 ? t('td.lvl5') : t('td.lvl6');
  }
  function tdRenderTypes(slot) {
    const sec = TOPIK_DEEP_SECTIONS.find(s => s.k === _tdState.section);
    const lvl = _tdState.level;
    const types = (sec.types || []).filter(t => t.lvl === lvl);
    const ready = types.filter(t => t.ready);
    const done = ready.filter(t => tdIsDone(t.id)).length;
    slot.innerHTML = `
      <button type="button" class="topik-back" onclick="topikDeepBack()"><i class="fa-solid fa-chevron-left"></i> ${t('ui.180')}</button>
      <div class="topik-sec-head"><h2 class="topik-sec-title">${sec.ico} ${skLoc(sec,'t')}</h2><p class="topik-sec-sub">${t('td.pickLevel')}${ready.length ? ` · ${t('td.studied')} ${done}/${ready.length}` : ''}</p></div>
      <div class="td-levels" role="group" aria-label="${t('ui.187')}">
        ${TD_LEVELS.map(n => `<button type="button" class="td-level-btn${n === lvl ? ' active' : ''}" onclick="tdSetLevel(${n})" aria-pressed="${n === lvl}">${n}급</button>`).join('')}
      </div>
      <p class="td-levels-hint"><b>${lvl}급</b> · ${sec.k === 'writing' ? t('td.writingPart') : t('td.questionsPrefix') + tdLevelHint(lvl)}</p>
      <div class="td-types">
        ${types.map(ty => `
          <button type="button" class="td-type${ty.ready ? '' : ' td-soon'}${ty.ready && tdIsDone(ty.id) ? ' td-type-done' : ''}" onclick="tdOpenType('${ty.id}')" aria-label="${t('ui.188',{range: ty.range, title: ty.title})}">
            <span class="td-type-badge">${ty.range}</span>
            <span class="td-type-main">
              <span class="td-type-title">${ty.ico} ${ty.title}</span>
              <span class="td-type-ko ko">${ty.ko}</span>
              <span class="td-type-skill">${ty.skill}</span>
            </span>
            ${ty.ready ? (tdIsDone(ty.id) ? '<span class="td-type-check" title="' + t('ui.189') + '"><i class="fa-solid fa-circle-check"></i></span>' : '<i class="fa-solid fa-chevron-right td-type-arrow" aria-hidden="true"></i>') : '<span class="td-soon-tag">' + t('ui.186') + '</span>'}
          </button>`).join('')}
      </div>`;
  }
  // Номера вопросов типа выводятся из id: 'r5-8' → [5,6,7,8].
  function tdNums(t) {
    const m = (t.id || '').match(/^r(\d+)-(\d+)$/);
    if (!m) return [];
    const a = +m[1], b = +m[2], arr = [];
    for (let n = a; n <= b; n++) arr.push(n);
    return arr;
  }
  // Реальные задания из прошлых тестов TOPIK II (TOPIK2_EXAMS, mock:false), отобранные по номерам типа.
  function tdRealExamples(t) {
    const nums = tdNums(t);
    if (!nums.length) return [];
    const ex2 = t2Exams();
    const out = [];
    Object.keys(ex2).forEach(k => {
      const e = ex2[k];
      if (e.mock || !e.reading || !e.reading.questions) return;
      nums.forEach(n => {
        const q = e.reading.questions.find(x => x.n === n);
        if (q && q.options && q.options.length && q.answer) out.push({ round: k, n, passage: q.passage, instr: q.instr, options: q.options, answer: q.answer, explain: q.explain });
      });
    });
    return out;
  }
  function tdRealExampleHtml(ex, i) {
    const opts = ex.options.map((o, k) => `
      <button type="button" class="td-opt ko" data-opt="${k + 1}" onclick="tdPick(this, ${i}, 0, ${ex.answer})">
        <span class="td-opt-n">${k + 1}</span><span class="td-opt-t">${o}</span>
      </button>`).join('');
    return `
      <div class="td-ex">
        <div class="td-real-tag">회차 ${ex.round} · 문제 ${ex.n}</div>
        ${ex.instr ? `<div class="td-ex-ru">${ex.instr}</div>` : ''}
        ${ex.passage ? `<div class="td-passage ko">${ex.passage}</div>` : ''}
        <div class="td-q" id="td-q-${i}-0">
          <div class="td-opts">${opts}</div>
          <div class="td-explain"><div class="td-explain-txt">${ex.explain || ''}</div></div>
        </div>
      </div>`;
  }
  function tdRenderType(slot) {
    const ty = tdTypesOf().find(x => x.id === _tdState.typeId);
    if (!ty) { _tdState.typeId = null; tdRender(); return; }
    const secKo = _tdState.section === 'writing' ? '쓰기' : _tdState.section === 'listening' ? '듣기' : '읽기';
    const banks = [];
    // tp → тип записи в «Моих словах»: грамматика уходит на вкладку «Грамматика»,
    // идиомы — на «Фразеологизмы»; слова/маркеры классифицируются автоматически.
    if (ty.grammar)  banks.push({ ico:'📖', title:'Грамматика',      sub:t('ui.190'), rows:ty.grammar,  tp:'grammar' });
    if (ty.vocab)    banks.push({ ico:'📚', title:'Ключевые слова',   sub:t('ui.191'), rows:ty.vocab,    tp:'' });
    if (ty.idioms)   banks.push({ ico:'🪄', title:'Идиомы',          sub:t('ui.192'), rows:ty.idioms,   tp:'idiom' });
    if (ty.keywords) banks.push({ ico:'🔑', title:'Слова-маркеры',   sub:t('ui.193'), rows:ty.keywords, tp:'' });
    const banksHtml = banks.map(b => `
        <div class="topik-rule td-bank">
          <button type="button" class="topik-rule-head" onclick="this.parentElement.classList.toggle('open')">
            <span class="topik-rule-ico">${b.ico}</span>
            <span class="topik-rule-title">${b.title}</span>
            <span class="topik-group-count">${b.rows.length}</span>
            <i class="fa-solid fa-chevron-down topik-rule-chev" aria-hidden="true"></i>
          </button>
          <div class="topik-rule-body">
            <div class="td-bank-sub">${b.sub}</div>
            <div class="topik-words">${b.rows.map(r => `
              <div class="topik-word"><span class="topik-word-ko ko">${r[0]}</span><span class="topik-word-ru">${r[1] || ''}</span>${r[2] ? `<span class="topik-word-ex ko">${r[2]}</span>` : ''}${lessonSaveHeart(r[0], r[1] || '', '', '🌸', 'topikdeep', 'topik-word-save', b.tp)}</div>`).join('')}</div>
          </div>
        </div>`).join('');
    const real = tdRealExamples(ty);
    const useReal = real.length > 0;
    const exHtml = useReal
      ? real.map((ex, i) => tdRealExampleHtml(ex, i)).join('')
      : (ty.examples || []).map((ex, i) => tdExampleHtml(ex, i)).join('');
    const exHead = useReal
      ? `📝 ${t('td.realTasks')} <span class="td-ex-count">${real.length} / 9 회차</span>`
      : '📝 Примеры · нажми вариант для проверки';
    const isDone = tdIsDone(ty.id);
    slot.innerHTML = `
      <button type="button" class="topik-back" onclick="topikDeepBack()"><i class="fa-solid fa-chevron-left"></i> ${t('ui.194')}</button>
      <div class="topik-sec-head">
        <h2 class="topik-sec-title">${ty.ico} ${ty.title}</h2>
        <p class="topik-sec-sub">${secKo} · ${_tdState.level}급 · вопросы ${ty.range} · <span class="ko">${ty.ko}</span></p>
      </div>
      <div class="td-block">
        <div class="td-block-h">📌 ${t('ui.195')}</div>
        <ol class="td-strategy">${(ty.strategy || []).map(s => `<li>${s}</li>`).join('')}</ol>
      </div>
      ${banksHtml ? `<div class="td-banks">${banksHtml}</div>` : ''}
      <div class="td-block-h" style="margin-top:18px;">${exHead}</div>
      <div class="td-ex-list">${exHtml}</div>
      <button type="button" class="td-done-btn${isDone ? ' on' : ''}" id="td-done-chip" onclick="tdDoneClick('${ty.id}')">
        <i class="fa-solid fa-check"></i> <span>${isDone ? t('tb.learned') : t('tb.markLearned')}</span>
      </button>`;
  }
  // Один вопрос внутри блока-задания (id уникален на вопрос → парные тексты работают независимо).
  function tdQuestionHtml(q, i, j) {
    const opts = q.options.map((o, k) => `
      <button type="button" class="td-opt ko" data-opt="${k + 1}" onclick="tdPick(this, ${i}, ${j}, ${q.answer})">
        <span class="td-opt-n">${k + 1}</span><span class="td-opt-t">${o}</span>
      </button>`).join('');
    return `
      <div class="td-q" id="td-q-${i}-${j}">
        ${q.label ? `<div class="td-q-label">${q.label}</div>` : ''}
        ${q.q ? `<div class="td-ex-q ko">${q.q}</div>` : ''}
        ${q.ru ? `<div class="td-ex-ru">${q.ru}</div>` : ''}
        <div class="td-opts">${opts}</div>
        <div class="td-explain"><div class="td-explain-txt">${q.explain}</div></div>
      </div>`;
  }
  // Блок-задание: опц. passage / sentences (가나다라) / insert (<보기>) + 1+ вопросов.
  // Обратная совместимость: одиночный пример {q,ru,options,answer,explain} → блок с одним вопросом.
  function tdExampleHtml(ex, i) {
    const block = ex.questions ? ex : { passage:ex.passage, passageRu:ex.passageRu, sentences:ex.sentences, insert:ex.insert, src:ex.src,
      questions:[{ q:ex.q, ru:ex.ru, options:ex.options, answer:ex.answer, explain:ex.explain }] };
    let head = '';
    if (block.passage) head += `<div class="td-passage ko">${block.passage}</div>${block.passageRu ? `<div class="td-passage-ru">${block.passageRu}</div>` : ''}`;
    if (block.sentences) head += `<div class="td-sentences">${block.sentences.map(s => `<div class="td-sentence"><span class="ko">${s[0]}</span>${s[1] ? `<span class="td-sentence-ru">${s[1]}</span>` : ''}</div>`).join('')}</div>`;
    if (block.insert) head += `<div class="td-insert"><div class="td-insert-label">&lt;보기&gt;</div><div class="ko">${block.insert.sentence}</div>${block.insert.ru ? `<div class="td-insert-ru">${block.insert.ru}</div>` : ''}</div>`;
    const qs = block.questions.map((q, j) => tdQuestionHtml(q, i, j)).join('');
    return `<div class="td-ex">${head}${qs}${block.src ? `<div class="td-src">${block.src}</div>` : ''}</div>`;
  }
  function tdPick(btn, exIdx, qIdx, answer) {
    const box = document.getElementById(`td-q-${exIdx}-${qIdx}`);
    if (!box || box.classList.contains('answered')) return;
    box.classList.add('answered');
    box.querySelectorAll('.td-opt').forEach(b => {
      const n = parseInt(b.getAttribute('data-opt'), 10);
      if (n === answer) b.classList.add('correct');
      else if (b === btn) b.classList.add('wrong');
      b.disabled = true;
    });
    const exp = box.querySelector('.td-explain'); if (exp) exp.classList.add('show');
    tdCheckDone();
  }
  // Трекинг «изучено» (хранится в UStore, как остальной прогресс приложения).
  function tdCheckDone() {
    const list = document.querySelector('#topikdeep-hub .td-ex-list');
    if (!list || !_tdState.typeId) return;
    const all = list.querySelectorAll('.td-q').length;
    const done = list.querySelectorAll('.td-q.answered').length;
    if (all > 0 && done === all) { tdMarkDone(_tdState.typeId); tdSetDoneChip(); }
  }
  function tdSetDoneChip() {
    const b = document.getElementById('td-done-chip');
    if (b) { b.classList.add('on'); const s = b.querySelector('span'); if (s) s.textContent = t('ui.196'); }
  }
  function tdDoneClick(id) { tdMarkDone(id); tdSetDoneChip(); }
  function tdDoneMap() { try { return UStore.get('tdDone') || {}; } catch (e) { return {}; } }
  function tdIsDone(id) { return !!tdDoneMap()[id]; }
  function tdMarkDone(id) { const m = tdDoneMap(); if (!m[id]) { m[id] = true; try { UStore.set('tdDone', m); } catch (e) {} } }
  // ─────────────── TOPIK Mock Exam engine (эталон №102 읽기) ───────────────
  // Shared passages for paired questions (показываются для обоих вопросов пары)
  const _TP = {
    hc:`우리 가족은 오랫동안 외국에 살았습니다. 그곳의 미용실은 가격이 비쌌습니다. 그래서 우리 가족은 미용실에 가지 않았습니다. 남편과 아이의 머리는 제가 잘라 주었습니다. 처음에는 잘 못 (㉠) 나중에는 잘 자르게 되었습니다. 지금 우리 가족은 한국에서 살고 있지만 저는 요즘도 가족들의 머리를 잘라 줍니다.`,
    tk:`인주시에서는 매년 가을에 떡볶이 축제를 합니다. 이 축제에서는 '매운 떡볶이 먹기 대회'가 열리는데 축제에 온 사람은 누구나 이 대회에 참가할 수 있습니다. (㉠) 이 축제에서 한국의 유명한 떡볶이를 모두 먹어 볼 수 있습니다. 떡볶이 재료를 싸게 살 수도 있고 공연도 볼 수 있어서 이 축제를 찾는 사람이 많습니다.`,
    ex:`제 친구는 회사원인데 그림을 잘 그립니다. 오늘 친구가 첫 번째 전시회를 열었습니다. 저는 (㉠) 그 친구의 전시회에 갔다 왔습니다. 전시회에는 꽃 그림이 많았습니다. 저는 장미꽃 그림을 하나 샀습니다. 오늘 이 그림을 제 방에 걸었습니다.`,
    cl:`인주시에는 유명한 '옷 거리'가 있습니다. 이곳은 가게마다 다른 종류의 옷을 팔아서 구경하는 재미가 있습니다. 여러 가게 중에서 인기가 많은 가게는 예전에 유행한 옷을 파는 가게와 특별한 디자인의 청바지를 파는 가게입니다. 다른 곳에서 팔지 않는 옷이 (㉠). 그래서 자기만의 특별한 옷을 사고 싶어 하는 사람들이 많이 찾아옵니다.`,
    dy:`얼마 전에 제가 초등학교 때 쓴 일기장을 보았습니다. (㉠) 거기에는 제가 선생님께 칭찬을 듣고 기뻐하는 이야기가 써 있었습니다. (㉡) 일기를 보고 갑자기 선생님이 생각나서 학교로 전화를 해 봤습니다. (㉢) 선생님은 아직 그 초등학교에 계셨습니다. (㉣) 선생님을 만나서 초등학교 때의 이야기를 나누었습니다.`,
    dr:`저는 드라마를 만드는 사람과 함께 일을 합니다. 드라마에 잘 맞는 (㉠) 일입니다. 이번에 시작하는 드라마는 바닷가 시골 마을 사람들의 이야기입니다. 그래서 부산과 제주도의 작은 바닷가 마을들을 여기저기 다녔습니다. 한 달이 걸려서 드라마에 딱 맞는 곳을 찾을 수 있었습니다. 이번 주말에 드라마 촬영이 시작됩니다. 이 드라마가 인기가 있으면 좋겠습니다.`,
    bk:`🪧 한국아파트 게시판\n안녕하세요, 관리실입니다. 우리 아파트에서는 관리실 옆에 자전거 주차장을 하나 더 만들었습니다. 아파트 입구, 계단 등에 둔 자전거는 새 주차장으로 옮겨 주시기 바랍니다. 새 주차장은 11월 10일 월요일부터 이용하실 수 있습니다. 주민 여러분의 많은 협조 부탁드립니다.\n— 한국아파트 관리실(02-1234-5678)`,
    rb:`토끼는 혼자서 생활하는 동물입니다. 보통 산에 사는데 무서운 동물을 만날 때가 많습니다. 그럴 때 토끼가 (㉠) 방법에는 여러 가지가 있습니다. 토끼는 튼튼한 다리로 빠르고 멀리 뛸 수 있습니다. 또 먼 곳에 있는 동물도 냄새로 알 수 있습니다. 귀를 움직여서 소리가 나는 위치도 정확하게 찾습니다. 그래서 무서운 동물이 오는 것을 미리 알 수 있습니다.`,
    ro:`인주도서관에는 '독서 로봇'이 있습니다. 아이들에게 책을 읽어 주는 로봇입니다. 아이들이 책을 펴서 한 장씩 넘겨 주면 로봇이 읽어 줍니다. 모양도 귀엽고 재미있는 목소리로 책을 읽어 줘서 한글을 모르는 아이들이 좋아합니다. 도서관을 방문한 아이는 누구나 이용할 수 있고, 인터넷으로 미리 신청하면 집에 빌려 갈 수도 있습니다. 이 로봇 덕분에 인주도서관에 (㉠) 있습니다.`,
    dg:`10년 넘게 키운 강아지가 하늘나라로 떠나서 이제 만날 수 없습니다. 저는 강아지와 함께한 시간을 기억하고 싶어서 휴대폰 게임을 만들었습니다. 주인공은 강아지가 함께 (㉠) 게임입니다. 저는 주인공이 되어 강아지와 높은 산도 오르고 파도가 심한 바다도 건넙니다. 나쁜 사람을 만나면 함께 싸우기도 합니다. 여행을 마치고 집으로 돌아오면 게임이 끝납니다. 저는 강아지가 보고 싶을 때마다 이 게임을 합니다.`
  };
  const _TP96 = {
    fish:`저는 주말에 형과 바다낚시를 다녀왔습니다. 우리는 배를 타고 낚시를 했습니다. 저는 낚시가 처음이었습니다. 그래서 형이 낚시하는 방법을 가르쳐 주었습니다. 형은 물고기를 많이 (㉠) 저는 못 잡았습니다. 다음에는 저도 물고기를 잡고 싶습니다.`,
    flour:`밀가루는 보통 음식을 만들 때 씁니다. 그런데 밀가루는 빨래를 할 때도 사용할 수 있습니다. 하얀색 옷을 빨 때 밀가루를 조금 넣으면 색깔이 더 하얗게 됩니다. (㉠) 과일을 씻을 때도 밀가루를 사용하면 깨끗하게 씻을 수 있습니다.`,
    sis:`저는 언니가 한 명 있습니다. 언니는 외국에 있는 회사에 취직을 했습니다. 다음 달에 외국으로 갈 겁니다. 저는 언니에게 특별한 선물을 주고 싶었습니다. 그래서 요즘 언니에게 줄 지갑을 (㉠). 언니가 이 지갑을 볼 때마다 저를 생각하면 좋겠습니다.`,
    park:`이번 주 토요일에 인주공원에서 '느리게 걷기' 행사를 합니다. 매달 열리는 이 행사는 천천히 (㉠) 공원의 경치를 즐기는 행사입니다. 이번 달에는 인주공원의 빨갛고 노란 단풍을 볼 수 있습니다. 공원 입구에서 출발해서 공원 가운데에 있는 호수까지 걷습니다. 호수에 도착하면 모자를 기념품으로 줍니다. 신청은 행사 3일 전까지 홈페이지에서 하면 됩니다.`,
    theater:`저는 어렸을 때 성격이 조용했습니다. 사람들 앞에서 부끄러워서 말도 잘 못했습니다. (㉠) 저는 그 동아리에 들어가서 다양한 연극 공연을 했습니다. (㉡) 연극 속에서 말이 많은 사람도, 시끄러운 사람도 되어 봤습니다. (㉢) 이제 저는 성격이 많이 바뀌었습니다. (㉣) 말도 많아지고 사람들 앞에서도 부끄러워하지 않습니다.`,
    veg:`저는 채소를 사 먹지 않습니다. 부모님이 집 마당에서 채소를 키우기 때문입니다. 주말에 저는 부모님 집에 (㉠) 채소 키우는 것을 도와 드립니다. 아이들도 함께 돕습니다. 아이들은 채소가 자라는 모습을 보고 정말 즐거워합니다. 전에는 아이들이 채소를 싫어했지만 지금은 잘 먹습니다.`,
    pool:`🏊 인주수영장 공지 사항\n인주수영장 회원 여러분, 안녕하세요? 이번 주말에 수영장 청소를 합니다. 청소를 하는 날에는 수영장을 이용할 수 없습니다. 이용에 불편을 드려 죄송합니다.\n● 청소 일정: 10월 12일(토) ~ 10월 13일(일)\n※ 1층 수영복 가게는 이용할 수 있습니다.`,
    ramyeon:`인주대학교 앞에 '라면세상'이 새로 문을 열었습니다. 그곳에 들어가면 한쪽 벽에 큰 책장이 있습니다. 그 책장에는 라면이 책처럼 정리되어 있습니다. 그래서 다양한 종류의 라면을 한 번에 보고 고를 수 있습니다. 라면을 산 후에는 그곳에서 직접 요리해서 먹을 수도 있습니다. 이렇게 다양한 (㉠) 수 있어서 젊은 사람들이 이곳을 많이 찾습니다.`,
    subway:`지하철을 갈아타는 역에서는 안내 방송과 함께 음악이 나옵니다. 예전에는 음악 없이 안내 방송만 나왔습니다. 그런데 안내 방송을 못 듣는 사람들이 많았습니다. 그래서 사람들에게 (㉠) 잘 알려 주기 위해서 새소리를 함께 사용하게 되었습니다. 이후에 바이올린 음악으로 바뀌었고 지금은 한국 전통 음악을 씁니다.`,
    bike:`초등학생이 된 우리 아이는 자전거를 타고 싶어 했습니다. 그래서 저는 아이의 자전거 연습을 도와주기로 했습니다. 우리는 아파트 놀이터에서 자전거 연습을 했습니다. 거기에는 동네 사람들이 많이 있었습니다. 사람들은 아이가 넘어져서 힘들어할 때 응원을 해 주었습니다. 땀을 흘리는 아이에게 시원한 음료수를 주는 사람도 있었습니다. 얼마 뒤 아이는 드디어 혼자서 (㉠) 수 있게 되었고, 사람들이 크게 박수를 쳐 주었습니다. 아이도 기뻐하며 활짝 웃었습니다.`
  };
  const _TP91 = {
    wed:`지영 씨는 제 친한 친구라서 지난달에 결혼했습니다. 저와 제 남편은 지영 씨의 결혼식에 갔습니다. 그래서 오늘 지영 씨 부부가 저와 남편을 집으로 초대했습니다. 우리는 지영 씨의 집을 (㉠) 지영 씨 부부가 만든 음식을 맛있게 먹었습니다. 그리고 결혼식 사진도 함께 봤습니다.`,
    hanbok:`한국대학교에서는 외국인 학생들에게 한복을 빌려주는 서비스를 시작했습니다. 요즘 외국인 학생들은 명절이나 학교에서 행사가 있을 때 한복을 자주 입기 때문입니다. 한복은 1층에 있는 사무실에서 빌릴 수 있습니다. 마음에 드는 한복을 고르고 이름과 전화번호를 써서 냅니다. (㉠) 3일 동안 무료로 한복을 빌릴 수 있습니다.`,
    badm:`저는 퇴근 후에 회사 친구들과 매일 배드민턴 모임을 합니다. 우리는 오후 8시에 모여서 배드민턴을 칩니다. 일 끝나고 매일 모이는 것이 (㉠) 친구들과 같이 하니까 재미있습니다. 처음에는 다음 날 아침에 너무 피곤했지만 지금은 괜찮습니다. 몸도 더 건강해지는 것 같습니다.`,
    tea:`사람들은 여러 종류의 차를 마십니다. 그중에서 (㉠) 때 마시면 좋은 차가 있습니다. '인삼차'는 배가 아플 때 마시면 도움이 됩니다. 또 잠을 못 잘 때는 '장미차'를 마시면 좋습니다. 감기에는 '유자차'가 좋습니다. 이런 차들은 만들기 쉽고 가게에서 쉽게 사 먹을 수 있어서 편합니다.`,
    museum:`저는 태국 친구하고 인주 역사 박물관에 갔습니다. (㉠) 친구는 한국어를 잘 못합니다. (㉡) 그런데 그 박물관에는 외국어로 설명해 주는 서비스가 있었습니다. (㉢) 친구는 태국어로 설명 서비스를 신청했습니다. (㉣) 설명이 쉽고 재미있어서 친구가 정말 좋아했습니다.`,
    rest:`지난주에 새 식당이 문을 열었습니다. 이 식당에는 여러 모양의 멋있는 가구들이 있습니다. 이 가구들은 모두 사람들이 만든 것인데 손님이 살 수도 있습니다. 저는 어제 동생과 그 식당에 처음 갔습니다. 우리는 꽃 모양 테이블에 앉아서 음식을 먹었는데 분위기도 좋고 음식도 맛있어서 우리는 다음에 또 (㉠).`,
    board:`💻 행복옷장 게시판 — 제목: 청바지를 주문했어요.\n안녕하세요? 이틀 전에 이 인터넷 쇼핑몰에서 청바지를 주문했습니다. 제가 주말에 여행을 가는데 그 옷을 입으면 좋겠습니다. 주문한 옷을 언제쯤 받을 수 있을까요? 서비스 센터에 전화했는데 전화를 안 받아서 여기에 글을 씁니다. 답 부탁드립니다.`,
    event:`매월 마지막 주 수요일에 인주시청 앞에서는 '책을 읽읍시다'라는 행사를 합니다. 이 행사는 (㉠) 사람들에게 인기가 많습니다. 새로 나온 책을 구경할 수도 있고 자기가 읽은 책을 다른 사람에게 싸게 팔 수도 있습니다. 유명한 작가와 인사를 나누는 프로그램도 있어서 행사에 다녀와서 느낀 것을 홈페이지에 쓰면 선물도 받을 수 있습니다.`,
    umbr:`최근 특별한 어린이 우산이 나왔습니다. 이 우산을 펴면 위쪽에서 빛이 납니다. 그리고 손잡이의 버튼을 누르면 노랫소리가 나옵니다. 이렇게 (㉠) 아이들이 좋아합니다. 보통 우산을 쓰면 아이가 잘 안 보이는데 이 우산을 쓰면 아이가 어디에 있는지 쉽게 알 수 있습니다. 또 튼튼해서 오래 쓸 수 있습니다. 그래서 다른 우산보다 좀 비싸지만 인기가 있습니다.`,
    grandma:`우리 가족은 일 년 전에 한국에 왔습니다. 저와 아내는 회사에 다녀서 아이를 돌보는 것이 힘들었습니다. 이것을 알고 옆집에 사는 할머니가 아이를 자주 돌봐 주셨습니다. 아이는 할머니를 좋아했습니다. 그런데 할머니가 갑자기 (㉠). 아이는 많이 슬퍼했습니다. 할머니와 헤어지는 날에 아이는 "제가 생각날 때 보세요."라고 하면서 직접 그린 그림을 선물했습니다. 그 그림에는 우리 가족과 할머니가 있었습니다. 할머니는 눈물을 흘리셨습니다.`
  };
  const _TP83 = {
    kinder:`저는 유치원 선생님입니다. 저는 아이들을 좋아해서 유치원 선생님이 되었습니다. 우리 유치원에는 아이들이 많아서 일이 조금 힘듭니다. 또 집에 늦게 가는 날도 많습니다. (㉠) 아이들이 정말 귀엽고 예뻐서 저는 제 일을 좋아합니다.`,
    flower:`인주시에서는 매년 5월 '인주 꽃 축제'를 엽니다. 이 축제에서는 세계 여러 나라의 꽃을 볼 수 있습니다. 특히 올해 축제에서는 많은 사람이 모여서 꽃으로 세계 지도 만들기를 합니다. 또 매일 오전에 가면 무료로 꽃다발을 (㉠) 꽃 그림 그리기를 할 수 있습니다.`,
    cold:`저는 감기에 걸려서 오늘 학교에 못 갔습니다. 병원에 가고 싶었지만 한국어를 잘 못해서 그냥 기숙사에 있었습니다. 그때 친구가 기숙사에 와서 저를 데리고 병원에 갔습니다. 기숙사로 (㉠) 친구가 밥도 사 주었습니다. 정말 고마웠습니다.`,
    comic:`얼마 전 만화 박물관이 문을 열었습니다. 이 박물관에는 1960년부터 지금까지 나온 여러 가지 만화책이 많이 있습니다. 유명한 만화 영화도 즐길 수 있어서 특히 아이들이 좋아합니다. 그리고 이 만화 박물관에는 (㉠) 만화책을 오랜만에 다시 읽으러 오는 어른들도 많습니다.`,
    bike:`저는 요즘 자전거를 타고 학교에 갑니다. (㉠) 전에는 지하철을 타고 다녔습니다. (㉡) 그때는 학교까지 삼십 분이 걸렸지만 지금은 한 시간쯤 걸립니다. (㉢) 아침에 일찍 일어나는 것은 힘들지만 운동을 할 수 있어서 좋습니다. (㉣)`,
    travel:`저는 오랫동안 다닌 회사를 그만두었습니다. 내년부터는 다른 회사에서 일할 겁니다. 그때까지 시간이 생겨서 지금은 매일 여행을 하고 있습니다. 자유롭게 여행하고 싶어서 (㉠) 여기저기 가고 싶은 곳을 다니고 있습니다. 저에게는 지금 이 시간이 정말 소중하고 행복합니다.`,
    email:`✉️ 직원 여러분께 — 우리 회사에서 영어 수업이 다음과 같이 열립니다.\n◆ 수업 기간: 8월 1일~8월 31일 (매주 화, 목 19시~21시)\n◆ 수업료: 무료\n◆ 신청 방법: 7월 22일(금)까지 이메일로 신청`,
    choco:`초콜릿은 달아서 사람의 기분을 좋게 합니다. 그래서 사람들이 초콜릿을 자주 먹습니다. 그런데 말을 많이 할 때나 발표를 해야 할 때는 초콜릿을 먹지 않는 것이 좋습니다. 초콜릿을 먹으면 목이 마르게 되어서 목소리가 잘 안 (㉠). 그래서 가수들도 공연 전에는 초콜릿을 먹지 않습니다.`,
    spring:`봄에는 몸에 힘이 없고 자주 피곤해집니다. 그것은 낮과 밤이 (㉠) 생기는 일입니다. 봄에는 낮 기온은 높지만 밤 기온은 낮습니다. 사람의 몸은 이 온도 차이를 잘 따라가지 못해서 쉽게 피곤해집니다. 이럴 때는 햇볕을 보면서 산책을 하면 좋습니다. 물을 많이 마시는 것도 도움이 됩니다.`,
    doll:`제가 초등학생이었을 때의 일입니다. 그날은 아버지의 생일이었고 저는 아버지를 기쁘게 해 드리고 싶었습니다. 그래서 제가 아끼던 고양이 인형을 선물로 드렸습니다. 저는 아버지가 기뻐할 것 같았습니다. 그런데 (㉠) 아버지는 아무 말도 하지 않았습니다. 잠시 후 아버지는 저를 꼭 안아 주셨습니다. 시간이 흘러 저는 결혼을 하고 딸을 낳았습니다. 제 딸의 첫 번째 생일에 아버지는 예쁘게 포장한 그 고양이 인형을 제게 다시 주셨습니다.`
  };
  const _TP64 = {
    concert:`저는 음악 공연 보는 것을 좋아합니다. 하지만 요즘에는 바빠서 공연을 거의 보지 못했습니다. 오늘은 일이 빨리 끝나서 오랜만에 친구와 같이 공연을 (㉠). 공연은 정말 신나고 좋았습니다. 공연을 보고 나올 때 행복했습니다.`,
    door:`전에는 문을 열 때 항상 열쇠를 사용했습니다. 그런데 요즘은 꼭 열쇠가 필요한 것은 아닙니다. 자기가 아는 번호를 사용할 수도 있고 카드로 문을 열 수도 있습니다. (㉠) 사람마다 모두 다른 목소리나 얼굴 모양을 이용하는 방법도 있습니다. 요즘은 이렇게 다양한 방법을 씁니다.`,
    friend:`저는 초등학교 때 친하게 지낸 친구가 한 명 있었습니다. 항상 같이 다닌 좋은 친구였습니다. 그런데 초등학교를 (㉠) 그 친구는 부산으로 이사를 갔습니다. 서로 멀리 떨어져서 만나지 못했고 이제는 연락이 안 됩니다. 그 친구를 찾을 수 있으면 좋겠습니다.`,
    market:`동문시장은 작고 조용한 시장이었습니다. 이곳에는 70년이 된 작은 국수 가게가 하나 있습니다. 얼마 전 이 국수 가게가 방송에 소개되었습니다. 그 후 동문시장의 분위기는 크게 달라졌습니다. 방송에 나온 후 이 국수 가게에 (㉠) 동문시장도 함께 유명해졌기 때문입니다.`,
    piano:`저는 피아노 학원에 다닌 지 3년이 되었습니다. (㉠) 그렇지만 지금은 여러 노래들을 잘 칠 수 있게 되었습니다. (㉡) 피아노를 치면서 좋아하는 가수의 노래를 부르면 정말 즐거워집니다. (㉢) 피아노를 배우는 것이 정말 좋습니다. (㉣)`,
    sibling:`저는 조금 전에 텔레비전을 보고 깜짝 놀랐습니다. 텔레비전에 제 동생이 크게 나왔기 때문입니다. 동생은 테니스 경기장에서 경기를 보고 있었는데 박수를 치면서 웃고 있었습니다. 동생의 모습을 텔레비전에서 본 것은 처음이었습니다. 매일 보는 동생이지만 동생의 얼굴을 텔레비전에서 보니까 (㉠) 새로운 기분이 들었습니다.`,
    parking:`📋 한국아파트 게시판 — 지하 주차장 청소 안내\n우리 아파트 지하 주차장 물청소를 다음 주 월요일과 화요일에 할 예정입니다. 청소를 하는 날에는 주차를 할 수 없습니다. 아파트의 다른 주차장을 이용하시기 바랍니다.\n● 청소 일정: 301동, 302동 — 7월 29일(월) / 303동, 304동 — 7월 30일(화)\n● 청소 시간: 09:00~18:00\n2019년 7월 22일(월) · 한국아파트 관리실`,
    ice:`얼음 음료는 여름철 인기 메뉴입니다. 그런데 얼음이 녹아서 물이 되면 음료의 맛이 옅어집니다. 그래서 얼음 음료를 만들 때는 천천히 녹는 얼음을 넣으면 좋습니다. 큰 얼음은 작은 얼음보다 천천히 녹고, 오래 얼린 얼음도 짧게 얼린 얼음보다 천천히 녹습니다. 이런 얼음을 넣으면 (㉠) 처음 음료의 맛을 오래 즐길 수 있습니다.`,
    typhoon:`태풍은 보통 7월부터 9월까지 많이 생깁니다. 이런 태풍들도 이름이 있는데 그 중에는 한국어로 된 이름도 있습니다. 태풍의 이름은 태풍이 지나가는 곳에 있는 열네 개 나라에서 만들고 있습니다. 한국도 2000년부터 태풍의 이름을 (㉠). 한국어로 이름을 만들 때는 다른 나라 사람들도 발음하기 쉬운 단어를 고릅니다.`,
    puppy:`몇 달 전, 우리 집 앞에서 떨고 있는 작고 마른 강아지를 보았습니다. 저는 그 강아지가 너무 불쌍해 보였습니다. 저는 강아지를 집으로 데려와 먹을 것을 주고 잠도 재워 주었습니다. 그때부터 주인을 찾고 있는데 아직도 주인이 나타나지 않습니다. 그 강아지는 이제 (㉠) 저의 좋은 친구가 되었습니다. 강아지와 헤어지기 싫습니다.`
  };
  const _TP60 = {
    plane:`저는 작년 한국 여행 때 비행기를 처음 탔습니다. 그런데 비행기 안에서 귀가 (㉠). 귀가 계속 아파서 여행이 즐겁지 않았습니다. 그래서 이번 베트남 여행 때는 약을 먹고 비행기를 탔습니다. 이번에는 귀가 아프지 않아서 정말 좋았습니다.`,
    museum:`한국음악 박물관으로 오십시오. 한국음악 박물관에서는 한국의 옛날 악기를 보고 악기 소리를 들을 수 있습니다. (㉠) 사진을 보면서 한국음악의 역사에 대해서 알 수 있습니다. 주말에는 다양한 음악 공연을 볼 수 있습니다. 기념품을 살 수 있는 가게도 있습니다.`,
    bakery:`저는 맛있는 빵을 만드는 사람이 되고 싶습니다. 그래서 학원에서 빵 만드는 것을 배웁니다. 저녁에는 빵 가게에서 아르바이트를 합니다. 빵 가게에서 일을 하면 학원에서 배운 빵을 만들어 볼 수 있고 사람들이 좋아하는 빵을 알 수 있습니다. 제가 일하는 가게는 (㉠) 곳이라서 손님이 많이 옵니다. 일이 힘들지만 행복합니다.`,
    fishing:`이제 낚시를 하기 위해서 멀리 가지 않아도 됩니다. 도시에서 (㉠) 수 있는 '낚시 카페'가 있습니다. 이곳에서는 낚시에 필요한 물건을 빌려주고 낚시하는 방법을 가르쳐 줍니다. 물고기를 잡아서 바로 먹을 수 없지만 집으로 가지고 갈 수 있습니다.`,
    tv:`사람들은 보통 좋아하는 텔레비전 프로그램을 볼 때 조용히 봅니다. (㉠) 그러나 우리 가족은 다릅니다. (㉡) 드라마와 뉴스 이야기도 하지만 나와 아내의 회사 이야기도 하고 아이들의 학교 이야기도 합니다. (㉢) 텔레비전 소리를 못 들을 때가 있지만 가족들과 함께하는 이 시간이 정말 즐겁습니다. (㉣)`,
    present:`저는 발표를 잘합니다. 하지만 전에는 발표를 잘하지 못했습니다. 여러 사람들이 저를 보고 있어서 너무 긴장했기 때문입니다. 저는 발표를 잘하고 싶어서 (㉠) 연습을 많이 했습니다. 혼자서 연습하는 것을 휴대전화로 찍고 잘 못한 부분을 다시 연습했습니다.`,
    shoes:`✉️ 받는 사람: 「좋은 구두」 쇼핑몰 담당자\n안녕하세요? 여러 번 전화했는데 통화 중이라서 이메일을 보냅니다. 저는 지난주 수요일에 이 인터넷 쇼핑몰에서 구두를 주문했습니다. 오늘 구두를 받아서 신어 봤는데 너무 불편합니다. 사이즈를 240으로 교환할 수 있을까요? 답장 기다리겠습니다.\n김수진 드림`,
    sugar:`설탕은 단맛을 낼 때 사용합니다. 음식을 오래 먹고 싶을 때 사용하기도 합니다. 그런데 설탕은 음식을 할 때만 쓰는 것은 아닙니다. 꽃병에 물과 함께 설탕을 넣으면 꽃을 오래 볼 수 있습니다. 옷을 빨 때 설탕을 넣으면 하얀색 옷이 더 깨끗해지고 설탕과 레몬을 같이 넣으면 옷이 부드러워집니다. 요리한 후에 손을 (㉠) 컵을 닦을 때 사용할 수도 있습니다.`,
    dol:`한국에서는 아이의 첫 번째 생일을 '돌'이라고 말합니다. 돌에는 아이가 물건을 잡는 특별한 행사를 합니다. 아이가 공을 잡으면 운동선수, 마이크를 잡으면 연예인이 될 것이라고 생각합니다. 연필은 선생님, 돈은 부자를 의미합니다. 아이 앞에 놓는 물건들의 (㉠) 모두 아이의 건강과 행복을 생각하는 마음이 들어 있습니다.`,
    seasons:`저는 일 때문에 외국에서 삽니다. 여기는 언제나 여름입니다. 저와 아이들은 한국의 (㉠). 특히 예쁜 꽃이 피는 봄과 단풍을 볼 수 있는 가을이 그립습니다. 그런데 오늘 한국에 계시는 아버지에게서 소포가 왔습니다. 아버지가 그리신 고향의 사계절 그림이었습니다. 저는 고향의 사계절을 선물해 주신 아버지가 고마웠습니다.`
  };
  const _TP41 = {
    basement:`우리 회사 지하에는 운동하는 방, 책을 읽는 방, 낮잠을 자는 방, 이야기하는 방이 있습니다. 이 방들은 점심시간에만 문을 엽니다. 우리 회사 사람들은 이곳을 좋아합니다. 이 방에 가고 싶은 사람들은 (㉠) 바로 지하로 갑니다. 식사 후에 짧은 시간 동안 하고 싶은 것을 할 수 있기 때문입니다.`,
    eyes:`눈은 한 번 나빠지면 다시 좋아지기 힘듭니다. 그래서 눈이 나빠지기 전에 눈 건강을 지켜야 합니다. 눈에 좋은 음식을 (㉠) 눈 운동을 하면 눈 건강에 좋습니다. 그리고 멀리 있는 산이나 나무를 보는 것도 좋습니다. 하지만 눈이 피곤할 때는 눈을 감고 쉬는 것이 제일 좋습니다.`,
    voice:`저는 목소리가 아주 큽니다. 작게 말하려고 하지만 제 목소리는 다른 사람보다 큽니다. 그래서 많은 사람들이 제 목소리를 싫어합니다. 그러나 우리 할머니는 제 목소리를 아주 좋아하십니다. 할머니가 (㉠) 때문입니다. 그래서 저는 시간이 날 때마다 할머니 댁에 가서 책과 신문을 읽어 드립니다.`,
    laugh:`우리 동네에는 「웃음 극장」이 있습니다. 저는 힘들 때마다 이 극장에 갑니다. 이곳에 가면 재미있는 공연을 볼 수 있기 때문입니다. 그런데 이 극장은 들어갈 때 돈을 내지 않고 나갈 때 돈을 냅니다. 이 극장에는 카메라들이 있어서 사람들의 웃는 모습을 찍습니다. 크게 많이 웃으면 돈을 적게 내고, 적게 웃으면 돈을 많이 냅니다. (㉠) 사람들은 이곳에서 많이 웃으려고 합니다.`,
    walking:`걷기는 많은 사람들이 쉽게 할 수 있는 운동입니다. (㉠) 걷는 것은 건강에 도움이 많이 됩니다. (㉡) 다리만 움직이면서 걷는 것이 아니고 온몸이 움직이게 되기 때문입니다. (㉢) 그런데 걷기 운동을 할 때에는 천천히 걷기 시작해서 조금씩 빨리 걷는 것이 좋습니다. (㉣) 이렇게 하는 것이 건강에 도움이 더 많이 됩니다.`,
    kimdul:`제 이름은 김둘입니다. 할아버지께서는 제 옆에 항상 친구가 있기를 바라셨습니다. 그래서 숫자 2로 이름을 지어 주셨습니다. 이 특별한 이름 덕분에 사람들이 저를 잘 기억합니다. 그리고 다른 사람들과 쉽게 친구가 될 수 있습니다. 할아버지께서 지어 주신 이름의 의미처럼 제 옆에는 항상 친구가 있습니다. 그래서 (㉠) 행복합니다.`,
    tradition:`✉️ 제목: 학생 여러분, 안녕하십니까?\n학생 여러분, 「전통 문화 함께하기」를 신청해 주셔서 감사합니다. 「전통 문화 함께하기」는 이번 주 금요일 오전 10시부터 12시까지 합니다. 태권도를 신청한 학생은 운동화를 신고 체육관으로 오시기 바랍니다. 전통 차 만들기를 신청한 학생은 학생회관으로 오십시오. 모든 신청자는 30분 전에 와서 준비해 주시기 바랍니다. 그럼 금요일에 뵙겠습니다.\n— 한국대학교 학생회`,
    decide:`저는 (㉠) 오랫동안 생각만 하고 빨리 결정하지 못합니다. 결정하는 것이 어려워서 혼자서는 필요한 물건을 잘 고르지 못합니다. 그래서 저는 친구가 옆에 있으면 친구가 하는 것을 따라 합니다. 그렇게 하면 제가 결정하지 않아도 돼서 마음이 편합니다. 하지만 지금부터는 제가 작은 일부터 하나씩 결정해 보려고 합니다.`,
    smallwed:`사람들은 결혼할 때 보통 많은 사람들을 초대합니다. 다른 사람들에게 결혼하는 모습을 보여 주고 싶기 때문입니다. 그런데 요즘에는 가족과 가까운 친구들만 (㉠) 「작은 결혼식」을 하는 사람들이 생겼습니다. 이런 결혼식을 하는 사람들은 적은 돈으로 결혼을 준비합니다. 이렇게 하면서 가까운 사람들과 함께 결혼의 기쁨을 나눕니다.`,
    fathercook:`아버지는 요리에 관심이 없어서 거의 요리를 하지 않으셨습니다. 그런데 지난달에 어머니가 다리를 다쳐서 요리를 못 하게 되었습니다. 그때부터 아버지는 요리를 (㉠). 아버지의 요리는 맛있을 때도 있고 맛없을 때도 있었습니다. 그런데 음식의 맛과 관계없이 어머니는 항상 맛있게 드셨습니다. 그 후로 아버지는 요리하는 것을 좋아하게 되셨습니다.`
  };
  const _TP47 = {
    brother:`우리 형은 혼자 여행을 자주 갑니다. 여행하면서 아름다운 경치를 보면 (㉠). 그리고 그것을 가족이나 친구들에게 선물합니다. 형이 그린 곳은 모두 멋있습니다. 형은 오늘 저에게 예쁜 바다 그림을 주었습니다. 저도 그곳에 한번 가 보고 싶습니다.`,
    lemon:`레몬은 요리에 많이 사용됩니다. 사람들은 레몬으로 차를 만들어서 마시기도 합니다. 레몬은 하얀 옷을 (㉠) 사용할 수도 있습니다. 레몬을 쓰면 옷이 더 하얗게 됩니다. 레몬은 이렇게 우리 생활에서 다양하게 사용됩니다.`,
    baseball:`지난 주말에 친구들과 같이 야구장에 갔습니다. 집에서 텔레비전으로 야구를 본 적은 많았지만 야구장에 간 것은 처음이었습니다. 그곳에는 사람들이 정말 많았습니다. 우리는 경기를 보면서 치킨도 먹고 함께 노래도 불렀습니다. 텔레비전으로 경기를 보는 것보다 (㉠) 더 재미있었습니다.`,
    cat:`우리 집 고양이 이름은 미미입니다. 6개월 전에 제가 퇴근해서 집에 돌아올 때 길에서 만났습니다. 그때 미미는 다리를 다쳐서 힘들어 보였습니다. 그리고 배도 고픈 것 같았습니다. 저는 미미를 집으로 데려와서 밥을 주고 약도 발라 주었습니다. 처음에 미미는 저한테 가까이 오지 않았습니다. 하지만 이제는 (㉠).`,
    hangulRoom:`우리 할머니는 '한글 공부방'에 다니십니다. (㉠) '한글 공부방'은 한글을 모르는 노인들이 다니는 곳입니다. (㉡) 할머니는 이곳에서 3달 동안 한글을 배우셨습니다. (㉢) 할머니는 내일 선생님께 감사의 편지를 드리려고 합니다. (㉣) 그래서 오늘 열심히 편지를 쓰셨습니다.`,
    movie:`요즘 옛날 영화를 다시 보여 주는 극장이 많습니다. 10년 전 영화인 '첫사랑'도 다음 주부터 여러 극장에서 볼 수 있습니다. '첫사랑'은 내용이 아름다워서 많은 사람들이 잊지 못하는 영화입니다. (㉠) 영화에 나온 음악은 요즘에도 인기가 많습니다. 이번에 크고 좋은 화면으로 이 영화를 다시 볼 수 있어서 사람들이 많이 기다리고 있습니다.`,
    tteok:`✉️ 받는 사람: 한국어교육원 학생 여러분께\n학생 여러분, 안녕하세요? 이번에 한국어교육원에서 '떡 만들기' 행사를 하려고 합니다. 한국의 여러 가지 떡을 직접 만들어서 먹어 볼 수 있습니다. 다음 달 3일 오후 2시부터 4시까지 우리 교육원 1층에서 할 계획입니다. 참가비는 만 원이고 이번 주까지 신청하면 됩니다. 많은 관심 부탁 드립니다.\n— 한국어교육원`,
    lullaby:`어렸을 때 우리 어머니는 저에게 노래를 자주 불러 주셨습니다. 제가 울 때는 재미있고 신나는 노래를 불러 주셨습니다. 그리고 잘 때는 제 침대에 같이 누워서 조용한 노래를 불러 주셨습니다. 저는 어머니의 노래를 (㉠) 잠이 더 잘 왔습니다. 저는 아직도 어머니가 불러 준 노래들을 기억합니다. 그리고 지금은 그 노래들을 제 아이한테 불러 줍니다.`,
    railpark:`얼마 전 인주시에서는 사용하지 않는 기찻길 주변을 공원으로 새롭게 만들었습니다. 사람들은 공원을 산책하거나 기찻길을 따라 걸으면서 사진을 찍습니다. 기찻길 옆에는 오래된 기차를 고쳐서 만든 카페가 하나 있습니다. 그 카페 안에는 (㉠) 많이 있습니다. 그래서 그 카페에 들어가면 옛날 분위기를 느낄 수 있습니다.`,
    wedding:`다음 달에 친한 친구가 결혼을 합니다. 외국에서 결혼식을 하는데 저는 회사 일 때문에 못 갑니다. 그래서 휴대 전화로 영상을 찍어서 친구에게 (㉠). 저는 친구와 어릴 때 함께 다닌 학교와 우리의 추억이 있는 여러 장소를 찍을 겁니다. 그리고 고향 친구들이 축하 인사를 하는 것도 찍을 겁니다. 친구가 그것을 보고 기뻐하면 좋겠습니다.`
  };
  const _TP52 = {
    travel:`저는 혼자 여행하는 것을 좋아합니다. 보통 여행 기간이나 장소를 정하지 않고 여행을 떠납니다. 유명한 관광지보다는 작은 마을을 다닙니다. 저는 운전을 하면서 여행하는데 예쁜 경치가 보이면 내려서 구경합니다. 여행하는 곳이 (㉠) 오랫동안 지낼 때도 있습니다.`,
    flour:`밀가루는 음식 재료입니다. 그런데 밀가루는 다양한 곳에 사용할 수 있습니다. 포도나 딸기를 씻을 때 밀가루로 씻으면 좋습니다. (㉠) 냄새가 나는 그릇에 밀가루를 넣고 하루가 지나면 냄새가 나지 않습니다. 밀가루를 사용하면 프라이팬에 남은 기름도 쉽게 닦을 수 있습니다.`,
    soap:`우리 아이는 피부가 좀 약합니다. 가게에서 파는 비누를 쓰면 피부가 안 좋아집니다. 그래서 저는 인터넷을 보고 아이에게 맞는 비누를 (㉠). 방법이 별로 어렵지 않았습니다. 이 비누는 쌀이나 과일 같은 자연 재료로 만들어서 좋습니다. 제가 만든 비누를 사용하고 아이의 피부가 좋아졌습니다.`,
    country:`저와 아내는 시골에서 자랐습니다. 우리는 결혼한 후에 서울에서 살면서 회사에 다녔습니다. 하지만 도시 생활이 행복하지 않았습니다. 우리는 다시 시골로 (㉠). 그래서 얼마 전에 시골에 집도 사고 땅도 조금 샀습니다. 거기에서 꽃을 키울 겁니다. 내일 드디어 이사를 합니다.`,
    mountain:`우리 동네 산에는 동물들이 많이 살고 있습니다. (㉠) 그런데 겨울에는 산에 동물들이 먹을 것이 별로 없습니다. (㉡) 그래서 저와 동네 사람들은 겨울이 되면 산에 가서 먹을 것을 놓고 옵니다. (㉢) 토끼나 산새들이 다 먹은 것입니다. (㉣) 추운 겨울에 먹을 것을 가지고 산에 올라가는 것이 힘들지만 우리는 매년 기분 좋게 이 일을 합니다.`,
    airport:`요즘 공항에서 여러 가지 서비스를 즐길 수 있습니다. 공항 안에 여행으로 피곤한 사람들이 잘 수 있는 방과 샤워할 수 있는 곳이 있습니다. 그리고 여행 가방이 고장 났을 때 가방을 (㉠) 빌려주는 서비스도 있습니다. 겨울에 따뜻한 나라로 가는 사람들을 위해 겨울옷을 맡아 주는 곳도 있습니다. 여권을 안 가져온 사람들에게 여권을 만들어 주기도 합니다.`,
    festival:`🌐 인주시 문화·행사 (injulove.com)\n제6회 '인주시 꽃길 걷기 축제'가 이번 달 23일에 열립니다. 사랑하는 사람들과 함께 꽃길을 걸으면서 아름다운 추억을 만들어 보시기 바랍니다. 꽃목걸이 만들기, 엽서 쓰기 등 다양한 행사도 준비했으니 많은 관심 바랍니다.\n· 일시: 2017년 4월 23일(일) 10:00 ~ 17:00\n· 걷는 길: 인주호수공원에서 인주대학교 앞까지\n· 참가비: 5,000원`,
    piano:`몇 달 전 우리 동네에 피아노 학원이 생겼습니다. 어머니는 그 학원 앞을 지날 때마다 한참 동안 서서 피아노 소리를 들으셨습니다. 어머니가 피아노를 배우고 싶어 하시는 것 같아서 저는 (㉠). 처음에 어머니는 나이가 많아서 학원에 다니는 것을 부끄러워하셨습니다. 하지만 요즘은 즐겁게 학원에 다니시고 가끔 가족 모임에서 손녀와 함께 연주도 하십니다.`,
    market:`인주시장은 오래된 시장입니다. 그런데 요즘 사람들은 오래된 시장을 별로 좋아하지 않아서 찾는 사람이 적어졌습니다. 시장을 새롭게 바꾸기 위해서 가게 주인들은 시장에 재미있는 그림을 전시하고 가게의 이름도 예쁘게 써서 걸었습니다. 또 이 시장에서만 볼 수 있는 다양한 물건들도 팔기 시작했습니다. 시장이 바뀐 후부터 사람들이 다시 (㉠).`,
    actor:`예전에 제 꿈은 유명한 영화배우였습니다. 하지만 배우가 되는 것은 생각보다 어려웠습니다. 그래서 저는 (㉠). 아이들에게 동화책을 읽어 주는 일입니다. 배우는 아니지만 저는 책을 읽으면서 배우처럼 연기를 합니다. 아이들은 제 연기를 보고 크게 웃거나 박수를 치면서 좋아합니다. 배우가 되지는 못했지만 저는 지금 제가 하는 일이 아주 마음에 듭니다.`
  };
  // TOPIK_EXAMS вынесен в assets/topik/exams-data.js (ленивая загрузка ensureTopikExams)

  const TOPIK_CIRCLED = ['①','②','③','④'];

  // ═══════════════ ФАЗА T1: банк вопросов TOPIK · дриллы по типам · Блиц-10 ═══════════════
  // Только READING: у вопросов на слух нет покарточечных таймкодов (один mp3 на весь
  // экзамен целиком), поэтому изолированный дрилл по ОДНОМУ вопросу технически неосуществим.
  // Разбор экзамена со звуком остаётся в существующем полном раннере (startTopikExam);
  // НОВЫЕ упражнения на слух строятся в Фазе T4 с нуля на TTS, а не разбором этого банка.

  // TOPIK I 읽기 (31–70): диапазоны эмпирически сверены по всем 9 официальным 회차 —
  // текст инструкции (instr) стабилен внутри диапазона (кроме мелких синонимов
  // «слово/частица/связка/выражение» — это один и тот же тип «вставь в пропуск»).
  const TOPIK1_READING_TYPES = [
    { range:[31,33], id:'t1-31-33', title:'О чём текст (короткий)' },
    { range:[34,39], id:'t1-34-39', title:'Слово/частица в пропуск' },
    { range:[40,42], id:'t1-40-42', title:'Не совпадает' },
    { range:[43,45], id:'t1-43-45', title:'Совпадает (короткий текст)' },
    { range:[46,48], id:'t1-46-48', title:'Главная мысль' },
    { range:[49,50], id:'t1-49-50', title:'Слово в пропуск + совпадает' },
    { range:[51,52], id:'t1-51-52', title:'Связка + о чём текст' },
    { range:[53,54], id:'t1-53-54', title:'Слово в пропуск + совпадает' },
    { range:[55,56], id:'t1-55-56', title:'Выражение в пропуск + совпадает' },
    { range:[57,58], id:'t1-57-58', title:'Порядок предложений 가나다라' },
    { range:[59,60], id:'t1-59-60', title:'Куда вставить + совпадает' },
    { range:[61,62], id:'t1-61-62', title:'Выражение в пропуск + совпадает' },
    { range:[63,64], id:'t1-63-64', title:'Зачем написан + совпадает' },
    { range:[65,66], id:'t1-65-66', title:'Выражение в пропуск + совпадает' },
    { range:[67,68], id:'t1-67-68', title:'Выражение в пропуск + совпадает' },
    { range:[69,70], id:'t1-69-70', title:'Выражение в пропуск + вывод' }
  ];
  function topik1TypeForN(n) { return TOPIK1_READING_TYPES.find(t => n >= t.range[0] && n <= t.range[1]) || null; }
  // TOPIK II 읽기 (1–50): переиспользуем уже готовую таксономию TOPIK_DEEP_READING (18
  // типов, id 'r1-2'…'r48-50') — не плодим второй справочник рядом с существующим.
  function topik2TypeForN(n) {
    return TOPIK_DEEP_READING.find(t => {
      const parts = t.id.slice(1).split('-').map(Number);
      return n >= parts[0] && n <= (parts[1] || parts[0]);
    }) || null;
  }
  let _topikBankCache = null;
  function buildTopikBank() {
    if (_topikBankCache) return _topikBankCache;
    const bank = [];
    const ex1 = t1Exams();
    Object.keys(ex1).forEach(examNo => {
      const rd = ex1[examNo] && ex1[examNo].reading;
      if (!rd || !Array.isArray(rd.questions)) return;
      rd.questions.forEach(q => {
        const ty = topik1TypeForN(q.n);
        if (!ty) return;
        bank.push({ id: `1-${examNo}-${q.n}`, lvl: 1, examNo, typeId: ty.id, typeTitle: ty.title, n: q.n, instr: q.instr, passage: q.passage, image: q.image, options: q.options, answer: q.answer, explain: q.explain });
      });
    });
    const ex2 = t2Exams();
    Object.keys(ex2).forEach(examNo => {
      const rd = ex2[examNo] && ex2[examNo].reading;
      if (!rd || !Array.isArray(rd.questions)) return;
      rd.questions.forEach(q => {
        const ty = topik2TypeForN(q.n);
        if (!ty) return;
        bank.push({ id: `2-${examNo}-${q.n}`, lvl: 2, examNo, typeId: ty.id, typeTitle: ty.title, n: q.n, instr: q.instr, passage: q.passage, image: q.image, options: q.options, answer: q.answer, explain: q.explain });
      });
    });
    // Кэшируем ТОЛЬКО когда банки реально загружены — иначе пустой [] застыл бы навсегда
    if (topikExamsReady()) _topikBankCache = bank;
    return bank;
  }
  // Список типов с числом вопросов и личной точностью (для плиток экрана «Практика»).
  function topikTypesList(lvl) {
    const bank = buildTopikBank().filter(q => q.lvl === lvl);
    const counts = {};
    bank.forEach(q => { counts[q.typeId] = (counts[q.typeId] || 0) + 1; });
    const acc = topikTypeAccuracy();
    // Порядок — из исходной таблицы типов (уже отсортирована по номеру вопроса), не из bank.
    const order = lvl === 2 ? TOPIK_DEEP_READING.map(t => t.id) : TOPIK1_READING_TYPES.map(t => t.id);
    const titleOf = lvl === 2
      ? id => (TOPIK_DEEP_READING.find(t => t.id === id) || {}).title
      : id => (TOPIK1_READING_TYPES.find(t => t.id === id) || {}).title;
    return order.filter(id => counts[id] > 0).map(id => ({ id, lvl, title: titleOf(id), count: counts[id], acc: acc[id] || null }));
  }
  // Личная точность по типам — из истории попыток (UStore, отдельно от wrongsTopik).
  function topikTypeAccuracy() {
    try { return UStore.get('topikTypeAcc', {}) || {}; } catch (_) { return {}; }
  }
  function recordTopikAttempt(typeId, correct) {
    const acc = topikTypeAccuracy();
    const a = acc[typeId] || { right: 0, total: 0 };
    a.total++; if (correct) a.right++;
    acc[typeId] = a;
    try { UStore.set('topikTypeAcc', acc); } catch (_) {}
  }

  // ═══════════════ ФАЗА T5: карта слабых мест + прогноз 급 (клей) ═══════════════
  // Целиком поверх уже собранной topikTypeAcc (T1/T2) — ни одного нового счётчика,
  // только два производных представления той же истории попыток.
  function _topikAllTypeIds(lvl) { return (lvl === 2 ? TOPIK_DEEP_READING : TOPIK1_READING_TYPES).map(t => t.id); }
  // Минимум 3 попытки в типе — иначе один случайный промах красит тип «слабым».
  function weakTopikTypes(lvl, limit) {
    return topikTypesList(lvl)
      .filter(ty => ty.acc && ty.acc.total >= 3)
      .map(ty => ({ ...ty, pct: Math.round(ty.acc.right / ty.acc.total * 100) }))
      .sort((a, b) => a.pct - b.pct)
      .slice(0, limit || 3);
  }
  // Простая шкала «точность + покрытие» — не претендует на официальный прогноз,
  // честно молчит (null), пока данных меньше чем по 3 типам.
  function topikLevelForecast(lvl) {
    const acc = topikTypeAccuracy();
    const allIds = _topikAllTypeIds(lvl);
    const attempted = allIds.filter(id => acc[id] && acc[id].total > 0);
    if (attempted.length < 3) return null;
    let right = 0, total = 0;
    attempted.forEach(id => { right += acc[id].right; total += acc[id].total; });
    const pct = total > 0 ? right / total : 0;
    const coverage = attempted.length / allIds.length;
    const tiers = lvl === 2
      ? [{ min: .8, cov: .6, label: '5~6급' }, { min: .6, cov: .4, label: '4~5급' }, { min: .4, cov: 0, label: '3~4급' }, { min: 0, cov: 0, label: '3급 이하' }]
      : [{ min: .8, cov: .6, label: '3~4급' }, { min: .6, cov: .4, label: '2~3급' }, { min: .4, cov: 0, label: '1~2급' }, { min: 0, cov: 0, label: '1급' }];
    const tier = tiers.find(t => pct >= t.min && coverage >= t.cov) || tiers[tiers.length - 1];
    // Ревью 07.07: точность одна могла бы дать более высокий ярус — если прогноз
    // скромный именно из-за охвата (мало разобранных типов), а не самой точности,
    // явно подсказываем это в UI (иначе виджет выглядит произвольно строгим).
    const accOnlyTier = tiers.find(t => pct >= t.min) || tiers[tiers.length - 1];
    return { pct: Math.round(pct * 100), coverage: Math.round(coverage * 100), label: tier.label, coverageLimited: accOnlyTier.label !== tier.label };
  }
  function openWeakSpotInDeep(typeId) {
    const ty = TOPIK_DEEP_READING.find(t => t.id === typeId);
    if (!ty) return;
    // switchScreen('topikdeep') сбрасывает _tdState через tdReset() — выставлять
    // раздел/уровень/тип нужно ПОСЛЕ перехода на экран, иначе сброс их затирает.
    switchScreen('topikdeep');
    _tdState.section = 'reading';
    _tdState.level = ty.lvl;
    tdOpenType(typeId);
  }
  function renderWeakSpotWidget(lvl) {
    const weak = weakTopikTypes(lvl, 3);
    const forecast = topikLevelForecast(lvl);
    if (!weak.length && !forecast) return '';
    const rows = weak.map(ty => `
      <div class="quest-item" onclick="startTopikDrill('${ty.id}')">
        <span class="quest-item-ico">🎯</span>
        <div class="quest-item-main">
          <div class="quest-item-title">${escHtml(ty.title)}</div>
          <div class="quest-item-sub">${ty.pct}% · ${ty.acc.total} ${t('topik.practice.qCount')}</div>
        </div>
        ${lvl === 2 ? `<button type="button" onclick="event.stopPropagation(); openWeakSpotInDeep('${ty.id}')" class="chip chip-blush" style="font-size:9px; flex-shrink:0; align-self:stretch; height:auto;">${t('t5.openDeep')}</button>` : ''}
        <span class="quest-item-chev">›</span>
      </div>`).join('');
    return `
      <div class="card card-padded" style="margin-bottom:14px;">
        <div style="font-size:11px; letter-spacing:.14em; color:var(--coral); font-weight:700;">${t('t5.eyebrow')}</div>
        ${forecast ? `<div style="font-size:13px; color:var(--berry); margin-top:4px;">${t('t5.forecast', { label: forecast.label, pct: forecast.pct })}</div>` : ''}
        ${forecast && forecast.coverageLimited ? `<div style="font-size:10.5px; color:var(--soft); margin-top:2px;">${t('t5.forecast.coverageHint', { coverage: forecast.coverage })}</div>` : ''}
        ${rows ? `<div style="display:grid; gap:8px; margin-top:10px;">${rows}</div>` : ''}
      </div>`;
  }

  // ── Дрилл по типу и Блиц-10: один общий раннер, отличается только набором вопросов ──
  let _drillState = null;
  function startTopikDrill(typeId) {
    if (!requirePlan('master', t('feat.topikDrill'))) return;
    const qs = shuffleArr(buildTopikBank().filter(q => q.typeId === typeId));
    if (qs.length < 3) { toast(t('topik.drill.empty')); return; }
    _drillState = { mode: 'drill', typeId, qs, idx: 0, score: 0, answered: null };
    renderTopikDrill();
  }
  function startTopikBlitz() {
    const qs = shuffleArr(buildTopikBank()).slice(0, 10);
    if (qs.length < 5) { toast(t('topik.drill.empty')); return; }
    _drillState = { mode: 'blitz', qs, idx: 0, score: 0, answered: null };
    renderTopikDrill();
  }
  function renderTopikDrill() {
    const st = _drillState;
    if (!st) return;
    if (st.idx >= st.qs.length) { gameModal(topikDrillFinishHtml(st), { id: 'topik-drill-modal' }); return; }
    const q = st.qs[st.idx];
    const isBlitz = st.mode === 'blitz';
    const answered = st.answered;
    const title = isBlitz ? t('topik.blitz.title') : t('topik.drill.title');
    const sub = isBlitz ? `${t('topik.lvl')} ${q.lvl} · ${q.typeTitle}` : q.typeTitle;
    const passage = q.passage ? `<div class="exam-passage ko">${examPassageHtml(q.passage)}</div>` : '';
    const image = q.image ? `<img class="exam-qimg" src="${q.image}" alt="">` : '';
    const opts = q.options.map((opt, i) => {
      const n = i + 1;
      let cls = 'topik-drill-opt';
      if (answered) {
        if (n === q.answer) cls += ' correct';
        else if (n === answered) cls += ' wrong';
      }
      return `<button type="button" class="${cls}" ${answered ? 'disabled' : `onclick="answerTopikDrill(${n})"`}>${TOPIK_CIRCLED[i]} ${escHtml(opt)}</button>`;
    }).join('');
    gameModal(`
      ${gameHeader(title, sub, st.idx, st.qs.length, "closeGameModal('topik-drill-modal')")}
      ${passage}${image}
      <div style="font-size:13px; color:var(--berry); font-weight:600; margin:10px 0;">${escHtml(q.instr)}</div>
      <div style="display:grid; gap:8px;">${opts}</div>
      ${answered ? `
        <div class="topik-drill-explain">${q.explain}</div>
        <button onclick="nextTopikDrill()" class="btn btn-primary btn-block" style="margin-top:14px;">${t('common.next')}</button>
      ` : ''}
    `, { id: 'topik-drill-modal' });
  }
  function answerTopikDrill(n) {
    const st = _drillState;
    if (!st || st.answered) return;
    const q = st.qs[st.idx];
    st.answered = n;
    const correct = n === q.answer;
    if (correct) st.score++;
    recordTopikAttempt(q.typeId, correct);
    if (!correct) recordTopikWrong(q); else clearTopikWrong(q.id);
    renderTopikDrill();
  }
  function nextTopikDrill() {
    if (!_drillState) return;
    _drillState.idx++;
    _drillState.answered = null;
    renderTopikDrill();
  }
  function topikDrillFinishHtml(st) {
    const xp = st.score * (st.mode === 'blitz' ? 6 : 5);
    addXp(xp, false);
    // Квест A3 «пройди Блиц-10» — резервировался в реестре ещё до постройки T1.
    if (st.mode === 'blitz') {
      if (!Array.isArray(stats.blitzPlayedDates)) stats.blitzPlayedDates = [];
      const today = todayIsoDate();
      if (!stats.blitzPlayedDates.includes(today)) {
        stats.blitzPlayedDates.push(today);
        const bkeys = stats.blitzPlayedDates.sort();
        if (bkeys.length > 60) bkeys.slice(0, bkeys.length - 60).forEach(d => stats.blitzPlayedDates.splice(stats.blitzPlayedDates.indexOf(d), 1));
        UStore.set('stats', stats);
      }
    }
    const pct = Math.round((st.score / st.qs.length) * 100);
    _drillState = null;
    return `
      <div style="text-align:center; padding: 8px 0;">
        <div style="font-size: 56px;">${pct >= 80 ? '🌟' : pct >= 50 ? '🌸' : '🌷'}</div>
        <div class="display" style="font-size: 24px; color: var(--berry); margin-top: 6px;">${t('common.done')}</div>
        <div style="font-size:13px; color: var(--coral); margin-top:2px;">${st.score}/${st.qs.length}</div>
        <div style="display:grid; grid-template-columns: repeat(2,1fr); gap:8px; margin-top:18px;">
          <div class="card card-padded" style="text-align:center; padding:12px 6px;"><div class="display" style="font-size:18px; color:var(--berry);">${st.score}/${st.qs.length}</div><div style="font-size:10px; color:var(--soft);">${t('ui.493')}</div></div>
          <div class="card card-padded" style="text-align:center; padding:12px 6px;"><div class="display" style="font-size:18px; color:var(--gold-ink);">+${xp}</div><div style="font-size:10px; color:var(--soft);">XP</div></div>
        </div>
        <button onclick="closeGameModal('topik-drill-modal')" class="btn btn-primary btn-block" style="margin-top:18px;">${t('common.done')}</button>
      </div>`;
  }

  // ═══════════════ ФАЗА T2: тетрадь ошибок 오답노트 · «Вопрос дня» ═══════════════
  // Отдельный ключ UStore (как bestScores), не внутри stats — низкая критичность данных
  // (тетрадь-помощник, не награда), поэтому мерж по умолчанию («последний снапшот
  // побеждает»), без специальной union-защиты как у stickers/frozenDates.
  const TOPIK_WRONG_INTERVALS_DAYS = [1, 3, 7];
  function getWrongsTopik() { try { return UStore.get('wrongsTopik', {}) || {}; } catch (_) { return {}; } }
  function setWrongsTopik(w) { try { UStore.set('wrongsTopik', w); } catch (_) {} }
  function recordTopikWrong(q) {
    const w = getWrongsTopik();
    const prev = w[q.id];
    w[q.id] = { examNo: q.examNo, n: q.n, lvl: q.lvl, typeId: q.typeId, box: prev ? prev.box : 0, correctStreak: 0, due: Date.now(), addedAt: (prev && prev.addedAt) || Date.now() };
    setWrongsTopik(w);
  }
  function clearTopikWrong(qid) {
    const w = getWrongsTopik();
    if (w[qid]) { delete w[qid]; setWrongsTopik(w); }
  }
  function topikWrongDueList() {
    const w = getWrongsTopik();
    const now = Date.now();
    const bank = buildTopikBank();
    const out = [];
    Object.keys(w).forEach(qid => {
      if ((w[qid].due || 0) > now) return;
      const q = bank.find(x => x.id === qid);
      if (q) out.push(q);
    });
    return out;
  }
  function topikWrongTotalCount() { return Object.keys(getWrongsTopik()).length; }

  let _reviewState = null;
  function startTopikReview() {
    if (!requirePlan('master', t('feat.topikWrongs'))) return;
    const qs = shuffleArr(topikWrongDueList());
    if (!qs.length) { toast(t('topik.review.empty'), 'var(--sage)'); return; }
    _reviewState = { qs, idx: 0, answered: null };
    renderTopikReview();
  }
  function renderTopikReview() {
    const st = _reviewState;
    if (!st) return;
    if (st.idx >= st.qs.length) { gameModal(topikReviewFinishHtml(), { id: 'topik-drill-modal' }); return; }
    const q = st.qs[st.idx];
    const answered = st.answered;
    const passage = q.passage ? `<div class="exam-passage ko">${examPassageHtml(q.passage)}</div>` : '';
    const image = q.image ? `<img class="exam-qimg" src="${q.image}" alt="">` : '';
    const opts = q.options.map((opt, i) => {
      const n = i + 1;
      let cls = 'topik-drill-opt';
      if (answered) { if (n === q.answer) cls += ' correct'; else if (n === answered) cls += ' wrong'; }
      return `<button type="button" class="${cls}" ${answered ? 'disabled' : `onclick="answerTopikReview(${n})"`}>${TOPIK_CIRCLED[i]} ${escHtml(opt)}</button>`;
    }).join('');
    gameModal(`
      ${gameHeader(t('topik.review.title'), q.typeTitle, st.idx, st.qs.length, "closeGameModal('topik-drill-modal')")}
      ${passage}${image}
      <div style="font-size:13px; color:var(--berry); font-weight:600; margin:10px 0;">${escHtml(q.instr)}</div>
      <div style="display:grid; gap:8px;">${opts}</div>
      ${answered ? `
        <div class="topik-drill-explain">${q.explain}</div>
        <button onclick="nextTopikReview()" class="btn btn-primary btn-block" style="margin-top:14px;">${t('common.next')}</button>
      ` : ''}
    `, { id: 'topik-drill-modal' });
  }
  function answerTopikReview(n) {
    const st = _reviewState;
    if (!st || st.answered) return;
    const q = st.qs[st.idx];
    st.answered = n;
    const correct = n === q.answer;
    const w = getWrongsTopik();
    const e = w[q.id];
    if (e) {
      if (correct) {
        e.correctStreak = (e.correctStreak || 0) + 1;
        if (e.correctStreak >= 2) delete w[q.id];
        else { e.box = Math.min(e.box + 1, TOPIK_WRONG_INTERVALS_DAYS.length - 1); e.due = Date.now() + TOPIK_WRONG_INTERVALS_DAYS[e.box] * 86400000; }
      } else {
        e.correctStreak = 0;
        e.due = Date.now() + TOPIK_WRONG_INTERVALS_DAYS[Math.min(e.box, TOPIK_WRONG_INTERVALS_DAYS.length - 1)] * 86400000;
      }
      setWrongsTopik(w);
    }
    renderTopikReview();
  }
  function nextTopikReview() {
    if (!_reviewState) return;
    _reviewState.idx++;
    _reviewState.answered = null;
    renderTopikReview();
  }
  function topikReviewFinishHtml() {
    _reviewState = null;
    return `
      <div style="text-align:center; padding: 8px 0;">
        <div style="font-size: 56px;">🌸</div>
        <div class="display" style="font-size: 24px; color: var(--berry); margin-top: 6px;">${t('topik.review.done')}</div>
        <div style="font-size:13px; color: var(--soft); margin-top:8px; line-height:1.5;">${t('topik.review.doneSub')}</div>
        <button onclick="closeGameModal('topik-drill-modal')" class="btn btn-primary btn-block" style="margin-top:18px;">${t('common.done')}</button>
      </div>`;
  }

  // ── «Вопрос дня» на Главной: общий для всех (как todayGameKey), но реже показывается
  // без цели TOPIK в onboardProfile (не заслоняет бытовые советы Комдори каждый день).
  function todayTopikQuestion() {
    const bank = buildTopikBank();
    if (!bank.length) return null;
    // Не подсовываем новичкам TOPIK II (слишком сложно — отзыв 09.07). TOPIK II
    // крутим только тем, кто реально на уровне TOPIK 2 (LEVEL_RANK ≥ 4); остальным —
    // лишь вопросы TOPIK I. Fallback на весь банк, если TOPIK I вдруг пуст.
    const allowTopik2 = (typeof userLevelRank === 'function' && userLevelRank() >= 4);
    const pool = allowTopik2 ? bank : bank.filter(q => q.lvl !== 2);
    const use = pool.length ? pool : bank;
    const days = Math.floor(new Date(todayIsoDate() + 'T00:00:00Z').getTime() / 86400000);
    return use[((days % use.length) + use.length) % use.length];
  }
  function shouldShowTopikQuestion() {
    const prof = Store.get('onboardProfile') || {};
    if (Array.isArray(prof.goals) && prof.goals.includes('topik')) return true;
    const days = Math.floor(new Date(todayIsoDate() + 'T00:00:00Z').getTime() / 86400000);
    return days % 3 === 0; // без цели TOPIK — раз в три дня
  }
  function renderTopikQuestionCard() {
    const slot = document.getElementById('topik-question-widget');
    if (!slot) return;
    if (!shouldShowTopikQuestion()) { slot.innerHTML = ''; return; }
    const q = todayTopikQuestion();
    if (!q) {
      slot.innerHTML = '';
      // «Вопрос дня» берёт задание из банка TOPIK. Банк грузится лениво и ОТЛОЖЕННО
      // (в простое, после интерактива) — карточка появится через пару секунд, но
      // холодный старт при этом не тормозится 2.6-мегабайтным банком.
      if (!topikExamsReady()) scheduleTopikExamsIdle(() => { if (_curScreen === 'home') renderTopikQuestionCard(); });
      return;
    }
    const today = todayIsoDate();
    const state = Store.get('tqState', {});
    const answered = state.day === today ? state.answered : null;
    const opts = q.options.map((opt, i) => {
      const n = i + 1;
      let cls = 'tq-opt';
      if (answered) { if (n === q.answer) cls += ' correct'; else if (n === answered) cls += ' wrong'; }
      return `<button type="button" class="${cls}" ${answered ? 'disabled' : `onclick="answerTopikQuestionOfDay(${n})"`}>${TOPIK_CIRCLED[i]} ${escHtml(opt)}</button>`;
    }).join('');
    slot.innerHTML = `
      <div class="card card-padded tq-card">
        <div style="display:flex; justify-content:space-between; align-items:center;">
          <span class="page-eyebrow" style="color:var(--coral);">${t('topik.qod.eyebrow')}</span>
          <span class="chip chip-blush" style="font-size:9.5px;">TOPIK ${q.lvl === 2 ? 'II' : 'I'}</span>
        </div>
        ${q.passage ? `<div class="ko" style="font-size:12.5px; color:var(--soft); margin-top:8px; line-height:1.6;">${examPassageHtml(q.passage)}</div>` : ''}
        <div style="font-size:13px; font-weight:600; color:var(--berry); margin-top:8px;">${escHtml(q.instr)}</div>
        <div style="display:grid; gap:6px; margin-top:10px;">${opts}</div>
        ${answered ? `<div class="topik-drill-explain" style="margin-top:10px;">${q.explain}</div><div onclick="switchScreen('topik')" class="tq-more">${t('topik.qod.more')} ›</div>` : ''}
      </div>`;
  }
  function answerTopikQuestionOfDay(n) {
    const q = todayTopikQuestion();
    if (!q) return;
    Store.set('tqState', { day: todayIsoDate(), answered: n });
    renderTopikQuestionCard();
  }

  // ═══════════════ ФАЗА B2: тест уровня — лид-магнит 🧪 ═══════════════
  // Упрощение объёма (осознанное): прогрессия по сложности вместо настоящей адаптивности
  // (ветвление усложнило бы вдвое, а фиксированный прогрессивный набор даёт тот же эффект
  // «не спугнуть новичка» и «не занизить продвинутую»). Вопросы: 8 лексика (из
  // gameWordPool — как в играх), 8 TOPIK I читение текстом, 4 TOPIK I «на слух» —
  // те же вопросы банка T1, но passage/instr озвучиваются TTS вместо показа текстом
  // (обходит ограничение банка «нет покарточечных таймкодов у настоящих аудио 회차»).
  function buildLevelTestQuestions() {
    const qs = [];
    const words = shuffleArr(gameWordPool().filter(w => w.ko && w.ru));
    const vocabWords = words.slice(0, 8);
    // В словах уроков перевод часто содержит подсказку спряжения: «петь → 노래해요».
    // В карточках это уместно, но в вариантах теста хвост «→ корейский» выдаёт правильный
    // ответ и выглядит чужеродно. Берём чистый глосс — часть до «→»/«|».
    const cleanGloss = (s) => String(s || '').split(/→|\|/)[0].trim();
    vocabWords.forEach(w => {
      const answer = cleanGloss(w.ru);
      if (!answer) return;
      // Дистракторы — чистые глоссы других слов; дедуп по значению, чтобы среди
      // четырёх вариантов не оказалось двух одинаковых после очистки.
      const seen = new Set([answer]);
      const wrongs = [];
      for (const x of shuffleArr(words)) {
        const g = cleanGloss(x.ru);
        if (!g || seen.has(g)) continue;
        seen.add(g); wrongs.push(g);
        if (wrongs.length === 3) break;
      }
      if (wrongs.length < 3) return; // словаря маловато — пропускаем вопрос, не подставляем дубли
      const options = shuffleArr([answer, ...wrongs]);
      qs.push({ skill: 'vocab', ko: w.ko, instr: t('leveltest.q.vocab'), options, answer: options.indexOf(answer) + 1, mode: 'text' });
    });
    const bank1 = shuffleArr(buildTopikBank().filter(q => q.lvl === 1 && q.options && q.options.length === 4));
    bank1.slice(0, 8).forEach((q, i) => {
      qs.push({ skill: i < 4 ? 'grammar' : 'reading', passage: q.passage, image: q.image, instr: q.instr, options: q.options, answer: q.answer, mode: 'text' });
    });
    bank1.filter(q => q.passage && q.passage.length < 90).slice(8, 12).forEach(q => {
      qs.push({ skill: 'listening', passage: q.passage, instr: q.instr, options: q.options, answer: q.answer, mode: 'listen' });
    });
    return qs;
  }
  let _ltState = null;
  function startLevelTest() {
    if (!topikExamsReady()) { toast(t('topik.loadingExams'), 'var(--berry)'); ensureTopikExams().then(() => startLevelTest()); return; }
    const qs = buildLevelTestQuestions();
    if (qs.length < 10) { toast(t('leveltest.notEnoughContent')); return; }
    _ltState = { qs, idx: 0, answered: null, skillScores: { vocab: {r:0,t:0}, grammar: {r:0,t:0}, reading: {r:0,t:0}, listening: {r:0,t:0} } };
    renderLevelTest();
  }
  function renderLevelTest() {
    const st = _ltState;
    if (!st) return;
    if (st.idx >= st.qs.length) { gameModal(levelTestResultHtml(), { id: 'leveltest-modal' }); return; }
    const q = st.qs[st.idx];
    const answered = st.answered;
    let bodyHtml;
    const passageHtml = q.passage ? `<div class="exam-passage ko">${examPassageHtml(q.passage)}</div>` : '';
    if (q.mode === 'listen') {
      // Озвучка ненадёжна (у части учениц звук молчит: айфон на «бесшумном», нет
      // корейского голоса устройства, прокси заблокирован). Поэтому ПОКАЗЫВАЕМ текст —
      // вопрос решается всегда; кнопка «Прослушать» — необязательная озвучка сверху.
      bodyHtml = `
        <div style="text-align:center; margin-bottom:10px;">
          <button type="button" class="btn btn-rose" onclick="playSyllable(${JSON.stringify(q.passage)})"><i class="fa-solid fa-volume-up"></i> ${t('leveltest.listenBtn')}</button>
        </div>
        ${passageHtml}`;
    } else {
      bodyHtml = (q.ko ? `<div class="ko" style="font-size:28px; font-weight:700; color:var(--berry); text-align:center; margin:10px 0;">${escHtml(q.ko)}</div>` : '')
        + passageHtml
        + (q.image ? `<img class="exam-qimg" src="${q.image}" alt="">` : '');
    }
    const opts = q.options.map((opt, i) => {
      const n = i + 1;
      let cls = 'topik-drill-opt';
      if (answered) { if (n === q.answer) cls += ' correct'; else if (n === answered) cls += ' wrong'; }
      return `<button type="button" class="${cls}" ${answered ? 'disabled' : `onclick="answerLevelTest(${n})"`}>${TOPIK_CIRCLED[i]} ${escHtml(opt)}</button>`;
    }).join('');
    gameModal(`
      ${gameHeader(t('leveltest.title'), t('leveltest.sub'), st.idx, st.qs.length, "closeLevelTest()")}
      ${bodyHtml}
      <div style="font-size:13px; color:var(--berry); font-weight:600; margin:10px 0;">${escHtml(q.instr)}</div>
      <div style="display:grid; gap:8px;">${opts}</div>
      ${answered ? `<button onclick="nextLevelTest()" class="btn btn-primary btn-block" style="margin-top:14px;">${t('common.next')}</button>` : ''}
    `, { id: 'leveltest-modal' });
  }
  function answerLevelTest(n) {
    const st = _ltState;
    if (!st || st.answered) return;
    const q = st.qs[st.idx];
    st.answered = n;
    const sc = st.skillScores[q.skill];
    sc.t++; if (n === q.answer) sc.r++;
    renderLevelTest();
  }
  function nextLevelTest() {
    if (!_ltState) return;
    _ltState.idx++;
    _ltState.answered = null;
    renderLevelTest();
  }
  function closeLevelTest() {
    stopSpeech();
    _ltState = null;
    closeGameModal('leveltest-modal');
  }
  function levelTestVerdict(pct) {
    if (pct >= 0.85) return 'topik1';
    if (pct >= 0.6)  return 'basic';
    if (pct >= 0.35) return 'hangul';
    return 'zero';
  }
  const LEVELTEST_VERDICT_META = {
    zero:   { label: '시작 · Начало',      moduleId: 'm1', emoji: '🌱' },
    hangul: { label: '한글 · Хангыль',      moduleId: 'm1', emoji: '🌿' },
    basic:  { label: '초급 · Базовый',      moduleId: 'm3', emoji: '🌸' },
    topik1: { label: 'TOPIK I · Уверенно', moduleId: null, emoji: '🌟' }
  };
  function levelTestResultHtml() {
    const st = _ltState;
    const totalR = Object.values(st.skillScores).reduce((s, x) => s + x.r, 0);
    const totalT = Object.values(st.skillScores).reduce((s, x) => s + x.t, 0);
    const pct = totalT ? totalR / totalT : 0;
    const verdict = levelTestVerdict(pct);
    const meta = LEVELTEST_VERDICT_META[verdict];
    // Автопростановка уровня. Два РАЗНЫХ масштаба в приложении: onboardProfile.level
    // (zero/hangul/basic — язык подбора модуля урока) и user.level (STUDY_LEVELS:
    // beginner/inter/advanced/topik1/topik2 — чип в профиле). verdict уже в первом
    // масштабе (переиспользует термины обнбординга) — для аккаунта переводим во второй.
    const u = Store.get('user');
    if (u && !u.guest) {
      const studyLevelMap = { zero: 'beginner', hangul: 'beginner', basic: 'inter', topik1: 'topik1' };
      try { setMyLevel(studyLevelMap[verdict] || 'beginner'); } catch (_) {}
    } else {
      const prof = Store.get('onboardProfile') || {};
      prof.level = verdict;
      Store.set('onboardProfile', prof);
    }
    Store.set('levelTestLastAt', Date.now());
    Store.set('levelTestResult', { verdict, pct: Math.round(pct * 100), at: Date.now() });
    const skillRows = ['vocab','grammar','reading','listening'].map(k => {
      const s = st.skillScores[k];
      if (!s.t) return '';
      const p = Math.round(s.r / s.t * 100);
      return `<div class="topik-type-tile"><div class="topik-type-title">${t('leveltest.skill.' + k)}</div><div class="topik-type-meta"><span>${s.r}/${s.t}</span><span>${p}%</span></div></div>`;
    }).join('');
    _ltState = null;
    return `
      <div style="text-align:center; padding: 8px 0;">
        <div style="font-size: 56px;">${meta.emoji}</div>
        <div class="page-eyebrow" style="color:var(--coral); margin-top:8px;">${t('leveltest.result.eyebrow')}</div>
        <div class="display" style="font-size:24px; color:var(--berry); margin-top:4px;">${meta.label}</div>
        <div style="font-size:13px; color:var(--soft); margin-top:6px;">${t('leveltest.result.score', { pct: Math.round(pct * 100) })}</div>
        <div class="topik-type-grid" style="margin-top:16px; text-align:left;">${skillRows}</div>
        <button onclick="shareLevelTestCard()" class="btn btn-rose btn-block" style="margin-top:18px;">${t('leveltest.share')}</button>
        ${meta.moduleId ? `<button onclick="closeLevelTest(); setActiveModule('${meta.moduleId}'); switchScreen('lessons');" class="btn btn-primary btn-block" style="margin-top:8px;">${t('leveltest.startModule')}</button>` : `<button onclick="closeLevelTest(); switchScreen('topik');" class="btn btn-primary btn-block" style="margin-top:8px;">${t('leveltest.goTopik')}</button>`}
        <button onclick="closeLevelTest()" class="btn btn-ghost btn-block" style="margin-top:8px;">${t('common.done')}</button>
      </div>`;
  }
  async function shareLevelTestCard() {
    const res = Store.get('levelTestResult');
    if (!res) return;
    const meta = LEVELTEST_VERDICT_META[res.verdict];
    try {
      const png = await generateShareCardPNG({
        eyebrow: 'KOREAN WITH MADIE',
        title: t('leveltest.share.title', { level: meta.label }),
        lines: [{ label: t('leveltest.share.scoreLabel'), value: res.pct + '%' }],
        footer: 'koreanmadie.study 🌸'
      });
      await shareCanvasImage(png, t('leveltest.share.title', { level: meta.label }));
    } catch (e) { console.warn('[leveltest-share]', e); }
  }
  // Раз в 2 недели — проактивно предлагаем тест ТОЛЬКО тем, у кого его ещё не было
  // или прошло достаточно времени; ручной вход (профиль/TOPIK) доступен всегда.
  function shouldSuggestLevelTest() {
    const last = Store.get('levelTestLastAt', 0);
    return !last || (Date.now() - last) > 14 * 86400000;
  }
  // Вход по ссылке ?test=1 (соцсети Мади) — доступно и гостю, без ожидания загрузки профиля
  (function autoLevelTestFromUrl() {
    try {
      if (new URLSearchParams(location.search).get('test') === '1') {
        setTimeout(() => { try { startLevelTest(); } catch (_) {} }, 1200);
      }
    } catch (_) {}
  })();

  let _examState = null;
  let _examTimer = null;

  function startTopikExam(n, mode, lvl) {
    if (!requirePlan('master', t('feat.topikExam'))) return;
    // Критический путь: экзамен не должен открыться пустым, если банк ещё грузится —
    // ждём загрузку и запускаемся заново (для master requirePlan повторно проходит).
    if (!topikExamsReady()) { toast(t('topik.loadingExams'), 'var(--berry)'); ensureTopikExams().then(() => startTopikExam(n, mode, lvl)); return; }
    const src = lvl === 2 ? t2Exams() : t1Exams();
    const data = (src[n] || {})[mode];
    if (!data || !data.questions || !data.questions.length) {
      toast(t('topik.testSoon'), 'var(--berry)'); return;
    }
    _examState = {
      exam: n, mode, lvl: lvl === 2 ? 2 : 1, label: data.label, questions: data.questions,
      durationMin: data.durationMin, total: data.total, audio: data.audio || '',
      answers: {}, idx: 0, endAt: Date.now() + data.durationMin * 60000, finished: false
    };
    let ov = document.getElementById('topik-exam-overlay');
    if (!ov) { ov = document.createElement('div'); ov.id = 'topik-exam-overlay'; ov.className = 'exam-overlay'; document.body.appendChild(ov); }
    document.body.style.overflow = 'hidden';
    renderExamRunner();
    startExamTimer();
  }
  function examFmtTime(ms) {
    if (ms < 0) ms = 0;
    const s = Math.floor(ms / 1000), m = Math.floor(s / 60);
    return `${String(m).padStart(2,'0')}:${String(s % 60).padStart(2,'0')}`;
  }
  function startExamTimer() {
    stopExamTimer();
    _examTimer = setInterval(() => {
      if (!_examState || _examState.finished) { stopExamTimer(); return; }
      const left = _examState.endAt - Date.now();
      const el = document.getElementById('exam-timer');
      if (el) {
        el.textContent = '⏱ ' + examFmtTime(left);
        el.classList.toggle('low', left < 5 * 60000);
      }
      if (left <= 0) { stopExamTimer(); finishExam(true); }
    }, 1000);
  }
  function stopExamTimer() { if (_examTimer) { clearInterval(_examTimer); _examTimer = null; } }

  function renderExamRunner() {
    // Строит каркас ОДИН раз. Аудио-плеер в .exam-stick не пересоздаётся при листании.
    const ov = document.getElementById('topik-exam-overlay');
    if (!ov || !_examState) return;
    const st = _examState;
    const audioHtml = (st.mode === 'listening' && st.audio) ? `
      <div class="exam-audio">
        <audio id="exam-audio-el" preload="metadata" src="${st.audio}"></audio>
        <div class="aplayer">
          <div class="aplayer-ctrls">
            <button type="button" class="aplayer-skip" onclick="examAudioSeek(-10)" aria-label="${t('ui.197')}"><i class="fa-solid fa-rotate-left"></i><span>10</span></button>
            <button type="button" class="aplayer-play" id="aplayer-play" onclick="examAudioToggle()" aria-label="${t('ui.198')}"><i class="fa-solid fa-play"></i></button>
            <button type="button" class="aplayer-skip" onclick="examAudioSeek(10)" aria-label="${t('ui.199')}"><i class="fa-solid fa-rotate-right"></i><span>10</span></button>
          </div>
          <input type="range" class="aplayer-bar" id="aplayer-bar" min="0" max="1000" value="0" step="1" oninput="examAudioScrub(this.value)" aria-label="${t('ui.200')}">
          <div class="aplayer-time" id="aplayer-time">0:00 / 0:00</div>
        </div>
      </div>` : '';
    const palette = st.questions.map((qq, i) => `<button type="button" class="exam-pal-cell ${st.answers[qq.n] ? 'done' : ''}" onclick="examGoto(${i})">${i + 1}</button>`).join('');
    ov.innerHTML = `
      <div class="exam-stick">
        <div class="exam-top">
          <button type="button" class="exam-close" onclick="closeExam()" aria-label="${t('ui.176')}"><i class="fa-solid fa-xmark"></i></button>
          <div class="exam-title">${st.label}</div>
          <div id="exam-timer" class="exam-timer">⏱ ${examFmtTime(st.endAt - Date.now())}</div>
          <button type="button" class="exam-finish-top" onclick="confirmFinishExam()" aria-label="${t('ui.202')}"><i class="fa-solid fa-flag-checkered"></i> ${t('ui.201')}</button>
        </div>
        ${audioHtml}
      </div>
      <div class="exam-progress"><span id="exam-answered">${Object.keys(st.answers).length}</span>/${st.questions.length} ${t('exam.answered')}</div>
      <div class="exam-body" id="exam-body"></div>
      <details class="exam-pal-wrap"><summary>${t('ui.203')} (<span id="exam-pal-count">${Object.keys(st.answers).length}</span>/${st.questions.length})</summary><div class="exam-palette" id="exam-palette">${palette}</div></details>
      <div class="exam-foot" id="exam-foot"></div>`;
    paintExam();
    if (st.mode === 'listening' && st.audio) setupExamAudio();
  }
  function examFmtSec(s) {
    if (!isFinite(s) || s < 0) s = 0;
    s = Math.floor(s);
    return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0');
  }
  function examAudioToggle() {
    const a = document.getElementById('exam-audio-el'); if (!a) return;
    if (a.paused) a.play(); else a.pause();
  }
  function examAudioSeek(d) {
    const a = document.getElementById('exam-audio-el'); if (!a || !isFinite(a.duration)) return;
    a.currentTime = Math.min(Math.max(0, a.currentTime + d), a.duration);
  }
  function examAudioScrub(v) {
    const a = document.getElementById('exam-audio-el'); if (!a || !isFinite(a.duration)) return;
    a.currentTime = (v / 1000) * a.duration;
  }
  function updateExamAudioUI() {
    const a = document.getElementById('exam-audio-el'); if (!a) return;
    const bar = document.getElementById('aplayer-bar');
    const t = document.getElementById('aplayer-time');
    const dur = a.duration;
    if (bar && isFinite(dur) && dur > 0 && document.activeElement !== bar) bar.value = Math.round(a.currentTime / dur * 1000);
    if (t) t.textContent = examFmtSec(a.currentTime) + ' / ' + examFmtSec(dur);
  }
  function setupExamAudio() {
    const a = document.getElementById('exam-audio-el'); if (!a) return;
    const pb = document.getElementById('aplayer-play');
    const setIcon = () => { if (pb) pb.innerHTML = a.paused ? '<i class="fa-solid fa-play"></i>' : '<i class="fa-solid fa-pause"></i>'; };
    a.addEventListener('loadedmetadata', updateExamAudioUI);
    a.addEventListener('timeupdate', updateExamAudioUI);
    a.addEventListener('play', setIcon);
    a.addEventListener('pause', setIcon);
    a.addEventListener('ended', setIcon);
    setIcon();
    updateExamAudioUI();
  }
  // ── Озвучка транскрипта 듣기 через Web Speech (ko-KR) — для экзаменов без аудиофайла (напр. EBS) ──
  let _examSpeakLines = null, _examSpeakIdx = 0, _examSpeakBtn = null;
  function stopExamScript() {
    _koGen++;
    try { speechSynthesis.cancel(); } catch (_) {}
    stopAudioPlayback();
    _examSpeakLines = null; _examSpeakIdx = 0;
    if (_examSpeakBtn && _examSpeakBtn.dataset.idle) { _examSpeakBtn.classList.remove('playing'); _examSpeakBtn.innerHTML = _examSpeakBtn.dataset.idle; }
    _examSpeakBtn = null;
  }
  function speakExamScript(btn) {
    if (!ttsProxyEnabled() && !('speechSynthesis' in window)) { toast(t('ui.000')); return; }
    const st = _examState; if (!st) return;
    const q = st.questions[st.idx];
    if (!q || !q.script) return;
    if (btn && btn === _examSpeakBtn && _examSpeakLines) { stopExamScript(); return; } // toggle
    stopExamScript();
    _examSpeakBtn = btn || null;
    if (btn) { if (!btn.dataset.idle) btn.dataset.idle = btn.innerHTML; btn.classList.add('playing'); btn.innerHTML = '<i class="fa-solid fa-stop"></i> ' + t('listendrill.stop'); }
    const slow = (typeof getSettings === 'function' && getSettings().slowVoice);
    _examSpeakLines = q.script.split('\n').map(s => s.trim()).filter(Boolean);
    _examSpeakIdx = 0;
    const next = () => {
      if (!_examSpeakLines || _examSpeakIdx >= _examSpeakLines.length) { stopExamScript(); return; }
      let line = _examSpeakLines[_examSpeakIdx++];
      let pitch = 1.05, text = line, voice = TTS_VOICE_F;
      const m = line.match(/^(남자|여자|남|여)\s*[:：]\s*(.*)$/); // снять метку говорящего, развести голоса
      if (m) { text = m[2]; const male = /남/.test(m[1]); pitch = male ? 0.8 : 1.25; voice = male ? TTS_VOICE_M : TTS_VOICE_F; }
      _koSpeakOne(text, { slow: slow, rate: slow ? 0.6 : 0.92, pitch: pitch, voice: voice }, next);
    };
    next();
  }
  // Вопросы-배열: метки (가)(나)(다)(라) выводим столбцом (каждая с новой строки),
  // иначе предложения сливаются в строку и ученики путаются. Применяется ко всем экзаменам.
  function examPassageHtml(p) {
    let s = String(p).replace(/\s*(\((?:가|나|다|라|마|바|사)\))\s*/g, '\n$1 ').replace(/^\n+/, '');
    return s.replace(/\n/g, '<br>');
  }
  function paintExam() {
    stopExamScript();
    const st = _examState; if (!st) return;
    const ov = document.getElementById('topik-exam-overlay'); if (!ov) return;
    const q = st.questions[st.idx];
    const chosen = st.answers[q.n];
    const passage = q.passage ? `<div class="exam-passage ko">${examPassageHtml(q.passage)}</div>` : '';
    const image = q.image ? `<img class="exam-qimg" src="${q.image}" alt="${t('ui.204')}">` : '';
    const listenBtn = q.script ? `<button type="button" class="exam-listen-btn" onclick="speakExamScript(this)"><i class="fa-solid fa-headphones"></i> ${t('ui.205')}</button>` : '';
    const opts = q.options.map((o, i) => {
      const num = i + 1;
      const inner = q.image
        ? `<span class="exam-opt-num">${TOPIK_CIRCLED[i]}</span>`
        : `<span class="exam-opt-num">${TOPIK_CIRCLED[i]}</span><span class="exam-opt-tx ko">${o}</span>`;
      return `<button type="button" class="exam-opt ${q.image ? 'pic' : ''} ${chosen === num ? 'sel' : ''}" onclick="selectExamOption(${num})">${inner}</button>`;
    }).join('');
    const body = document.getElementById('exam-body');
    body.innerHTML = `
      <div class="exam-qno">${t('exam.qno')} ${st.idx + 1} ${q.n !== st.idx + 1 ? `<span class="exam-q-orig">№${q.n}</span>` : ''} <span class="exam-pts">${q.points} ${t('exam.pts')}</span></div>
      <div class="exam-instr">${q.instr || ''}</div>
      ${listenBtn}
      ${image}${passage}
      <div class="exam-opts ${q.image ? 'exam-opts-pic' : ''}">${opts}</div>`;
    document.getElementById('exam-foot').innerHTML = `
      <button type="button" class="exam-navbtn" onclick="examNav(-1)" ${st.idx === 0 ? 'disabled' : ''}><i class="fa-solid fa-chevron-left"></i></button>
      ${st.idx < st.questions.length - 1
        ? `<button type="button" class="exam-navbtn exam-next" onclick="examNav(1)">${t('ui.206')} <i class="fa-solid fa-chevron-right"></i></button>`
        : `<button type="button" class="exam-navbtn exam-finish" onclick="confirmFinishExam()">${t('ui.207')} ✓</button>`}`;
    ov.querySelectorAll('.exam-pal-cell').forEach((c, i) => c.classList.toggle('cur', i === st.idx));
    body.scrollTop = 0;
    ov.scrollTo({ top: 0 });
  }
  function selectExamOption(num) {
    if (!_examState) return;
    const st = _examState;
    const q = st.questions[st.idx];
    st.answers[q.n] = num;
    const ov = document.getElementById('topik-exam-overlay');
    ov.querySelectorAll('.exam-opt').forEach((b, i) => b.classList.toggle('sel', i + 1 === num));
    const ans = Object.keys(st.answers).length;
    const a1 = document.getElementById('exam-answered'); if (a1) a1.textContent = ans;
    const pc = document.getElementById('exam-pal-count'); if (pc) pc.textContent = ans;
    const cell = ov.querySelectorAll('.exam-pal-cell')[st.idx]; if (cell) cell.classList.add('done');
  }
  function examNav(d) {
    if (!_examState) return;
    const ni = _examState.idx + d;
    if (ni < 0 || ni >= _examState.questions.length) return;
    _examState.idx = ni; paintExam();
  }
  function examGoto(i) {
    if (!_examState) return;
    _examState.idx = i; paintExam();
  }
  function confirmFinishExam() {
    const st = _examState; if (!st) return;
    const left = st.questions.length - Object.keys(st.answers).length;
    const msg = left > 0 ? t('exam.noAnswer', { n: left }) : t('exam.finishQ');
    if (confirm(msg)) finishExam(false);
  }
  function finishExam(byTime) {
    if (!_examState || _examState.finished) return;
    _examState.finished = true;
    stopExamTimer();
    stopExamScript();
    // ФАЗА C2: марафон — секция 읽기 сегодняшнего расписания, ровно в окне (первая суббота месяца)
    try {
      const m = activeMarathon();
      if (m && _examState.mode === 'reading' && _examState.exam === m.examNo && _examState.lvl === m.lvl) {
        let score = 0;
        _examState.questions.forEach(q => { if (_examState.answers[q.n] === q.answer) score += q.points; });
        submitMarathonResult(m, score);
      }
    } catch (_) {}
    renderExamResults(byTime);
  }
  function renderExamResults(byTime) {
    const ov = document.getElementById('topik-exam-overlay');
    const st = _examState; if (!ov || !st) return;
    let score = 0, correct = 0;
    st.questions.forEach(q => { if (st.answers[q.n] === q.answer) { score += q.points; correct++; } });
    const pct = Math.round(score / st.total * 100);
    const reading2 = st.total === 100; // reading section is /100
    const review = st.questions.map((q, i) => {
      const mine = st.answers[q.n];
      const ok = mine === q.answer;
      const mineTx = mine ? `${TOPIK_CIRCLED[mine-1]} ${q.options[mine-1]}` : '—';
      // Краткий заголовок-идентификатор: для 읽기 — начало текста; для 듣기 (passage пустой) — диалог script,
      // иначе инструкция. Убираем HTML/SVG и переносы, многоточие — только если реально обрезали.
      const revRaw = (q.passage || q.script || q.instr || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
      const revLabel = revRaw.slice(0, 42) + (revRaw.length > 42 ? '…' : '');
      return `<div class="exam-rev ${ok ? 'ok' : 'no'}">
        <div class="exam-rev-head"><span class="exam-rev-no">${i + 1}</span><span class="exam-rev-mark">${ok ? '✓' : '✕'}</span>
          <span class="exam-rev-q ko">${revLabel}</span></div>
        ${ok ? '' : `<div class="exam-rev-mine">${t('ui.177')} <b class="ko">${mineTx}</b></div>`}
        <div class="exam-rev-correct">${t('ui.208')} <b class="ko">${TOPIK_CIRCLED[q.answer-1]} ${q.options[q.answer-1]}</b></div>
        <div class="exam-rev-ex">${q.explain}</div>
      </div>`;
    }).join('');
    ov.innerHTML = `
      <div class="exam-top">
        <button type="button" class="exam-close" onclick="closeExam()" aria-label="${t('ui.023')}"><i class="fa-solid fa-xmark"></i></button>
        <div class="exam-title">${t('exam.result')} · ${st.label}</div>
      </div>
      <div class="exam-results">
        <div class="exam-score-card">
          <div class="exam-score-big">${score}<span>/${st.total}</span></div>
          <div class="exam-score-sub">${t('exam.correctOf', { c: correct, n: st.questions.length })} · ${pct}%</div>
          <div class="exam-score-note">${score >= 70 ? t('exam.noteGreat') : score >= 50 ? t('exam.noteGood') : t('exam.noteTry')}</div>
          ${byTime ? '<div class="exam-score-time">' + t('ui.209') + '</div>' : ''}
        </div>
        <div class="exam-review-head">${t('exam.reviewHead')}</div>
        <div class="exam-review">${review}</div>
        <div class="exam-tbl-head">${t('exam.yourAnswers')}</div>
        <div class="exam-ansgrid">${st.questions.map((q, i) => {
          const mine = st.answers[q.n];
          const ok = mine === q.answer;
          const cls = mine ? (ok ? 'ok' : 'no') : 'na';
          const pick = mine ? TOPIK_CIRCLED[mine - 1] : '—';
          const right = !ok ? `<span class="exam-ans-right">✓${TOPIK_CIRCLED[q.answer - 1]}</span>` : '';
          return `<div class="exam-ans ${cls}"><span class="exam-ans-n">${i + 1}</span><span class="exam-ans-pick">${pick}</span>${right}</div>`;
        }).join('')}</div>
        <div class="exam-tbl-legend"><span><span class="dot" style="background:rgba(122,158,118,.5)"></span>${t('exam.correct')}</span><span><span class="dot" style="background:rgba(201,89,89,.45)"></span>${t('exam.incorrect')}</span></div>
        <button type="button" class="btn btn-rose btn-block" style="margin-top:18px;" onclick="shareExamCard()"><i class="fa-solid fa-share-nodes"></i> ${t('exam.shareRes')}</button>
        <button type="button" class="btn btn-primary btn-block" style="margin-top:10px;" onclick="closeExam()">${t('exam.ready')}</button>
      </div>`;
    st.lastResult = { score, correct, pct };
    ov.scrollTop = 0;
    if (typeof spawnConfetti === 'function' && correct >= st.questions.length * 0.6) { try { spawnConfetti(); } catch(e){} }
  }

  // ── Шер-карточка результата: красивая картинка для Stories/Telegram ──
  function _loadImg(src) {
    return new Promise(res => {
      const im = new Image();
      im.onload = () => res(im);
      im.onerror = () => res(null);
      im.src = src;
    });
  }
  async function shareExamCard() {
    const st = _examState;
    if (!st || !st.lastResult) { toast(t('share.finishFirst')); return;}
    const { score, correct, pct } = st.lastResult;
    const W = 1080, H = 1350;
    const c = document.createElement('canvas');
    c.width = W; c.height = H;
    const x = c.getContext('2d');
    // фон: кремовый градиент
    const bg = x.createLinearGradient(0, 0, 0, H);
    bg.addColorStop(0, '#FFFAF6'); bg.addColorStop(.55, '#FCF0EC'); bg.addColorStop(1, '#F9E3E6');
    x.fillStyle = bg; x.fillRect(0, 0, W, H);
    // лепестки
    x.globalAlpha = .5;
    x.font = '44px serif'; x.textAlign = 'center';
    [[90,140],[990,110],[160,1190],[930,1230],[70,640],[1010,700],[540,90],[250,330],[840,380]].forEach(([px,py],i) => {
      x.save(); x.translate(px,py); x.rotate((i*47)%360*Math.PI/180);
      x.font = `${30+(i%3)*16}px serif`; x.fillText('🌸',0,0); x.restore();
    });
    x.globalAlpha = 1;
    // логотип
    const logo = await _loadImg('assets/logo-horizontal.png');
    if (logo) {
      const lw = 460, lh = lw * (logo.height / logo.width);
      x.drawImage(logo, (W - lw) / 2, 70, lw, lh);
    }
    // белая карточка
    const cardY = 320, cardH = 660, cardX = 90, cardW = W - 180, r = 48;
    x.save();
    x.shadowColor = 'rgba(92,42,51,.18)'; x.shadowBlur = 60; x.shadowOffsetY = 24;
    x.fillStyle = '#fff';
    x.beginPath(); x.roundRect(cardX, cardY, cardW, cardH, r); x.fill();
    x.restore();
    // содержимое карточки
    x.textAlign = 'center';
    x.fillStyle = '#E07686';
    x.font = '600 34px Inter, sans-serif';
    x.fillText(t('share.examHeader'), W / 2, cardY + 92);
    x.fillStyle = '#5C2A33';
    x.font = '700 56px "Noto Sans KR", sans-serif';
    x.fillText(st.label, W / 2, cardY + 180);
    x.font = '800 215px Fraunces, Georgia, serif';
    x.fillStyle = '#5C2A33';
    x.fillText(String(score), W / 2 - 80, cardY + 420);
    x.font = '700 80px Fraunces, Georgia, serif';
    x.fillStyle = '#C9A55C';
    x.fillText('/' + st.total, W / 2 + 175, cardY + 415);
    x.fillStyle = 'rgba(92,42,51,.6)';
    x.font = '500 44px Inter, sans-serif';
    x.fillText(t('share.correctOf', { c: correct, n: st.questions.length, pct: pct }), W / 2, cardY + 510);
    x.font = '52px serif';
    x.fillText(score >= 70 ? t('share.resGreat') : score >= 50 ? t('share.resGood') : t('share.resStart'), W / 2, cardY + 600);
    // мишка
    const bear = await _loadImg('assets/bear2.png');
    if (bear) {
      const bh = 330, bw = bh * (bear.width / bear.height);
      x.drawImage(bear, W - bw - 100, H - bh - 130, bw, bh);
    }
    // подпись
    x.textAlign = 'left';
    x.fillStyle = '#5C2A33';
    x.font = '700 46px Inter, sans-serif';
    x.fillText(t('share.learnWith'), 100, H - 200);
    x.fillStyle = 'rgba(92,42,51,.55)';
    x.font = '500 36px Inter, sans-serif';
    x.fillText(t('share.tagline'), 100, H - 140);
    // поделиться / скачать
    c.toBlob(async blob => {
      if (!blob) { toast(t('share.imgFail')); return; }
      const file = new File([blob], 'madie-topik-result.png', { type: 'image/png' });
      if (navigator.canShare && navigator.canShare({ files: [file] })) {
        try {
          await navigator.share({ files: [file], title: t('share.shareTitle'), text: t('share.shareText') });
          return;
        } catch (e) { if (e && e.name === 'AbortError') return; }
      }
      // фолбэк: скачать
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = 'madie-topik-result.png';
      a.click();
      setTimeout(() => URL.revokeObjectURL(a.href), 4000);
      toast(t('share.saved'), 'var(--sage)');
    }, 'image/png');
  }
  function closeExam() {
    stopExamTimer();
    stopExamScript();
    const finished = _examState && _examState.finished;
    if (_examState && !finished) {
      if (!confirm(t('exam.leaveConfirm'))) { startExamTimer(); return; }
    }
    _examState = null;
    document.body.style.overflow = '';
    const ov = document.getElementById('topik-exam-overlay');
    if (ov) ov.remove();
  }

  // Admin: TOPIK materials editor
  function renderAdminTopik() {
    const list = (() => { const a = Store.get('topikMaterials', []); return Array.isArray(a) ? a : []; })();
    const kinds = [
      { v:'vocab',   l:'📖 Лексика' },
      { v:'grammar', l:'🧩 Грамматика' },
      { v:'tip',     l:'💡 Совет' },
      { v:'file',    l:'📎 Файл/ссылка' }
    ];
    return `
      <div class="admin-form" style="display:grid; gap:10px;">
        <select id="atm-kind" class="input" style="font-family:inherit;">
          ${kinds.map(k => `<option value="${k.v}">${k.l}</option>`).join('')}
        </select>
        <input id="atm-title" class="input" placeholder="Заголовок (초급 · Еда / Частица ―을/를)">
        <textarea id="atm-body" class="input" rows="3" placeholder="${t('ui.210')}" style="resize:vertical;"></textarea>
        <input id="atm-url" class="input" placeholder="${t('ui.211')}">
        <button onclick="adminAddTopikMaterial()" class="btn btn-primary btn-block">${t('ui.212')}</button>
        <div style="font-size:10.5px; color:var(--soft); text-align:center; line-height:1.5;">Появится в разделе ТОПИК → Материалы у всех учеников</div>
      </div>
      <div class="section-head" style="margin-top:18px;"><div class="left"><div class="rule"></div><span class="title">Материалы ТОПИК (${list.length})</span></div></div>
      ${list.length ? `<div style="display:grid; gap:8px;">${list.map((m, i) => `
        <div class="card card-padded" style="display:flex; align-items:center; gap:10px;">
          <div style="flex:1; min-width:0;">
            <div style="font-weight:600; color:var(--berry); font-size:12.5px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${(TOPIK_MAT_META[m.kind]||TOPIK_MAT_META.tip).icon} ${escHtml(m.title || '(без заголовка)')}</div>
            <div style="font-size:10.5px; color:var(--soft); overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${escHtml((m.body || m.url || '').slice(0, 60))}</div>
          </div>
          <button onclick="deleteTopikMaterialByIndex(${i})" class="btn btn-ghost" style="padding:6px 10px; font-size:11px; color:var(--bad-ink); border-color:rgba(179,58,74,.25); flex-shrink:0;">${t('ui.018')}</button>
        </div>`).join('')}</div>`
        : `<div style="text-align:center; color:var(--soft); font-size:12px; padding:14px; font-style:italic;">${t('ui.213')}</div>`}
    `;
  }
  function adminAddTopikMaterial() {
    const kind = document.getElementById('atm-kind').value;
    const title = (document.getElementById('atm-title').value || '').trim();
    const body = (document.getElementById('atm-body').value || '').trim();
    const url = (document.getElementById('atm-url').value || '').trim();
    if (!title) { toast(t('ui.214')); return; }
    if (kind === 'file' && !url) { toast(t('ui.215')); return; }
    const all = Store.get('topikMaterials', []);
    const arr = Array.isArray(all) ? all : [];
    arr.push({ id: `tm_${Date.now()}_${Math.random().toString(36).slice(2,7)}`, kind, title, body, url, ts: Date.now() });
    Store.set('topikMaterials', arr);
    toast('Материал добавлен 🌸', 'var(--sage)');
    if (document.getElementById('screen-topik')?.classList.contains('active')) renderTopik();
    showAdminPanel('topik');
  }
  function deleteTopikMaterialByIndex(i) {
    if (!confirm(t('ui.216'))) return;
    const all = Store.get('topikMaterials', []);
    const arr = Array.isArray(all) ? all : [];
    arr.splice(i, 1);
    Store.set('topikMaterials', arr);
    if (document.getElementById('screen-topik')?.classList.contains('active')) renderTopik();
    showAdminPanel('topik');
  }
  function deleteTopikMaterial(id) {
    if (!confirm(t('ui.216'))) return;
    const all = Store.get('topikMaterials', []);
    Store.set('topikMaterials', (Array.isArray(all) ? all : []).filter(m => m.id !== id));
    renderTopik();
  }

  function getCurrentLesson() {
    const all = getAllLessons();
    // Админ может открыть любой урок — приоритет у выбранного вручную
    if (lessonViewId) {
      const v = all.find(l => l.id === lessonViewId);
      if (v) return v;
    }
    const p = getLessonProgress();
    return all.find(l => l.id === p.current) || all[0];
  }
  function completeCurrentLesson() {
    const p = getLessonProgress();
    if (p.current && !p.completed.includes(p.current)) p.completed.push(p.current);
    if (p.stages && p.current) delete p.stages[p.current]; // finished → no resume point
    const all = getAllLessons();
    const next = all.find(l => !p.completed.includes(l.id));
    p.current = next ? next.id : null;
    setLessonProgress(p);
    stats.lessons = totalLessonsCompleted();
    _bumpMonthly('lessons', 1);
    UStore.set('stats', stats);
  }

  // ── Lesson path positions (winding S-curve, supports any number of lessons) ──
  function lessonPositions(n) {
    const out = [];
    const baseY = 20;
    const stepY = 140;
    for (let i = 0; i < n; i++) {
      const isRight = i % 2 === 1;
      const x = isRight ? 222 : 78;
      out.push({ x, y: baseY + i * stepY });
    }
    return out;
  }
  function renderLessonPath() {
    const slot = document.getElementById('lesson-path');
    if (!slot) return;
    const all = getAllLessons();
    const p = getLessonProgress();
    const pos = lessonPositions(all.length);
    const W = 300;
    const H = (pos[pos.length - 1]?.y || 0) + 130;

    // L-shaped dashed rose paths with rounded corners
    let paths = '';
    for (let i = 0; i < pos.length - 1; i++) {
      const a = pos[i], b = pos[i + 1];
      const dir = b.x > a.x ? 1 : -1;
      const startX = a.x + 46 * dir;
      const startY = a.y + 46;
      const cornerX = b.x;
      const cornerY = a.y + 46;
      const endY = b.y;
      const r = 16;
      const preX = cornerX - r * dir;
      const postY = cornerY + r;
      paths += `<path d="M ${startX} ${startY} L ${preX} ${cornerY} Q ${cornerX} ${cornerY} ${cornerX} ${postY} L ${cornerX} ${endY}" fill="none" stroke="#F2A6AE" stroke-width="4.5" stroke-dasharray="11 9" stroke-linecap="round"/>`;
    }

    // Tiles
    const admin = isAdmin();
    const tiles = all.map((l, i) => {
      const completed = p.completed.includes(l.id);
      const current   = p.current === l.id;
      const status    = completed ? 'done' : current ? 'current' : admin ? 'open' : 'locked';

      let body;
      if (completed) {
        body = `<div class="tile-main"><i class="fa-solid fa-check" aria-hidden="true"></i></div>`;
      } else if (current || admin) {
        const ko = (l.ko || '').trim().replace(/[?!.,]+$/, '');
        const koLen = [...ko].length;
        let koHtml, koSize;
        if (koLen === 0) {
          koHtml = String(l.num);
          koSize = 28;
        } else if (koLen <= 3) {
          koHtml = ko;
          koSize = koLen <= 2 ? 30 : 24;
        } else {
          // 4+ chars: split into 2 lines, prefer at space/middot
          const m = ko.match(/^(.+?)[\s·]+(.+)$/);
          let line1, line2;
          if (m) { line1 = m[1]; line2 = m[2]; }
          else {
            const chars = [...ko];
            const mid = Math.floor(chars.length / 2);
            line1 = chars.slice(0, mid).join('');
            line2 = chars.slice(mid).join('');
          }
          koHtml = `${line1}<br>${line2}`;
          const longest = Math.max([...line1].length, [...line2].length);
          koSize = longest <= 2 ? 24 : longest <= 3 ? 20 : 17;
        }
        body = `
          <div class="tile-eyebrow">${t('lesson.tileNum',{n:l.num})}</div>
          <div class="tile-main ko" style="font-size:${koSize}px; line-height:1.05;">${koHtml}</div>
        `;
      } else {
        body = `<div class="tile-main"><i class="fa-solid fa-lock" style="font-size:20px;" aria-hidden="true"></i></div>`;
      }

      const interactive = completed || current || admin;
      const onclick   = interactive ? `onclick="openLessonPreview('${l.id}')"` : '';
      const cursor    = interactive ? 'pointer' : 'default';
      const titleColor = current || completed ? 'var(--berry)' : 'var(--soft)';
      const BEAR_BY_NUM = { 5: 'bear1', 10: 'bear2', 15: 'bear3' };
      const bearName = BEAR_BY_NUM[l.num];
      const bearHtml = bearName
        ? `<img src="assets/${bearName}.png" alt="" class="lesson-bear" />`
        : '';

      // Интерактивная плитка — настоящая <button>: фокус с клавиатуры,
      // Enter/Space, видимый focus-ring и понятная подпись для скринридера.
      const tag = interactive ? 'button' : 'div';
      const typeAttr = interactive ? 'type="button"' : '';
      const safeTitle = String(lessonTitle(l) || '').replace(/"/g, '&quot;');
      const ariaStatus = completed ? t('a11y.lessonDone') : current ? t('a11y.lessonCurrent') : admin ? t('a11y.lessonOpen') : t('a11y.lessonLocked');
      const aria = `aria-label="${t('lesson.lesson')} ${l.num} — ${safeTitle} (${ariaStatus})"`;
      return `<${tag} ${typeAttr} ${onclick} ${aria} style="position:absolute; left:${pos[i].x - 46}px; top:${pos[i].y}px; cursor:${cursor}; text-align:center; width:92px; background:none; border:none; padding:0; color:inherit; font-family:inherit; ${!interactive ? 'opacity:.75;' : ''}">
        ${bearHtml}
        <div class="lesson-tile ${status}">${body}</div>
        <div style="font-size:11.5px; font-weight:${current ? 700 : 500}; color:${titleColor}; margin-top:8px; line-height:1.2;">${lessonTitle(l)}</div>
        ${current ? (() => {
          const slidesN = Array.isArray(l.slides) ? l.slides.length : 0;
          const savedStage = (p.stages && Number(p.stages[l.id])) || 0;
          const lpct = slidesN > 0 ? Math.min(100, Math.round(savedStage / slidesN * 100)) : 0;
          return `${savedStage > 0 ? `<div class="tile-progress"><span style="width:${lpct}%"></span></div>` : ''}<span class="chip chip-berry" style="margin-top:6px;">${savedStage > 0 ? t('home.continue') : t('common.start')} →</span>`;
        })() : ''}
      </${tag}>`;
    }).join('');

    // Decorations: sakuras + sparkles scattered on the OUTER (empty) side of each row
    const sakuraEmojis = ['🌸','🌺','💮'];
    const seed = (i, salt) => ((i * 9301 + salt * 49297 + 7) % 233280) / 233280;
    let deco = '';
    for (let i = 0; i < pos.length; i++) {
      const isRight = i % 2 === 1;
      const sideCx = isRight ? 36 : 264;
      const tileY = pos[i].y;
      const sak = sakuraEmojis[i % sakuraEmojis.length];
      deco += `<div class="path-deco sakura" style="left:${sideCx + seed(i,1)*24 - 12}px; top:${tileY + 6}px; animation-delay:${(i*0.3).toFixed(2)}s;">${sak}</div>`;
      deco += `<div class="path-deco sakura sm" style="left:${sideCx + seed(i,6)*36 - 8}px; top:${tileY + 84}px; animation-delay:${(i*0.4+0.6).toFixed(2)}s;">${sakuraEmojis[(i+1) % sakuraEmojis.length]}</div>`;
      deco += `<div class="path-deco sparkle" style="left:${sideCx + seed(i,2)*30 + 14}px; top:${tileY + 44 + seed(i,3)*20}px; animation-delay:${(i*0.4).toFixed(2)}s;">✦</div>`;
      deco += `<div class="path-deco sparkle sm" style="left:${sideCx + seed(i,4)*32 - 6}px; top:${tileY + 52 + seed(i,5)*16}px; animation-delay:${(i*0.4+1.1).toFixed(2)}s;">✧</div>`;
    }

    slot.style.position = 'relative';
    slot.style.width = W + 'px';
    slot.style.height = H + 'px';
    slot.style.margin = '14px auto 8px';
    slot.innerHTML = `
      <svg width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" style="position:absolute; inset:0; pointer-events:none;">${paths}</svg>
      ${deco}
      ${tiles}
    `;
    // Update module header counter
    const modHdr = document.getElementById('module-header-count');
    if (modHdr) modHdr.textContent = `✓ ${p.completed.length}/${all.length}`;
    const subhdr = document.getElementById('module-subheader');
    if (subhdr) subhdr.textContent = t('lessons.count', { done: p.completed.length, total: all.length });
    const pct = Math.round((p.completed.length / all.length) * 100);
    const progressBar = document.getElementById('module-progress-bar');
    if (progressBar) progressBar.style.width = pct + '%';
    const pctChip = document.getElementById('module-pct-chip');
    if (pctChip) pctChip.textContent = '🌸 ' + pct + '%';
  }
  function openLessonPreview(lessonId) {
    const all = getAllLessons();
    const l = all.find(x => x.id === lessonId);
    if (!l) return;
    const p = getLessonProgress();
    const completed = p.completed.includes(lessonId);
    const current   = p.current === lessonId;
    // Админу открыты все уроки — сразу запускаем урок целиком
    if (isAdmin()) { startLessonFlow(lessonId); return; }
    if (!completed && !current) { toast(t('ui.217')); return; }
    if (current) { startLessonFlow(lessonId); return; }
    // Show review modal for completed
    const m = document.createElement('div');
    m.className = 'modal-bg modal-center';
    m.onclick = e => { if (e.target === m) m.remove(); };
    m.innerHTML = `
      <div class="modal-card" style="max-width:380px;">
        <div style="display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:14px;">
          <div>
            <div class="page-eyebrow">${t('lesson.eyebrowReview', { n: l.num })}</div>
            <div class="display" style="font-size: 22px; color: var(--berry); margin-top: 4px; line-height:1.2;">${lessonTitle(l)}</div>
          </div>
          <div onclick="this.closest('.modal-bg').remove()" style="font-size:24px; color:var(--soft); cursor:pointer;">×</div>
        </div>
        <div class="hangul-display" style="padding:24px 16px;">
          <div class="ko" style="font-size:36px; font-weight:700; color:var(--berry); line-height:1.1;">${l.ko}</div>
          ${l.ru ? `<div style="color:var(--coral); margin-top:8px; font-size:14px;">«${l.ru}»</div>` : ''}
          ${l.ko ? `
            <div style="display:flex; gap:8px; justify-content:center; margin-top:14px; flex-wrap:wrap;">
              <button onclick="playSyllable('${l.ko.replace(/'/g, "\\'")}', this)" class="btn-mic" style="background:var(--card); border-color:var(--line-strong);"><i class="fa-solid fa-volume-up"></i> ${t('ui.028')}</button>
              <button onclick="pronounceCheck('${l.ko.replace(/'/g, "\\'")}', this)" class="btn-mic"><i class="fa-solid fa-microphone"></i> ${t('ui.029')}</button>
            </div>` : ''}
        </div>
        ${l.vocab ? `<div class="ko-quote" style="margin-top:16px;"><div style="font-size:11px; letter-spacing:.16em; color:var(--coral); font-weight:600; margin-bottom:6px;">${t('ui.218')}</div><div style="font-size:13px; color:var(--berry); line-height:1.6;">${vocabPreviewText(l.vocab)}</div></div>` : ''}
        <div style="display:flex; gap:8px; margin-top:16px;">
          <button onclick="this.closest('.modal-bg').remove()" class="btn btn-ghost" style="flex:1;">${t('ui.023')}</button>
          <button onclick="this.closest('.modal-bg').remove(); startLessonFlow('${l.id}', true);" class="btn btn-primary" style="flex:1.5;">${t('ui.219')}</button>
        </div>
      </div>
    `;
    document.body.appendChild(m);
  }

  // ── Hero lesson on home ──
  function renderHeroLesson() {
    const slot = document.getElementById('hero-lesson');
    if (!slot) return;
    const cur = getCurrentLesson();
    const p = getLessonProgress();
    const all = getAllLessons();
    if (!cur) {
      slot.innerHTML = `
        <div class="hero" style="text-align:center;">
          <div style="font-size:42px;">🎉</div>
          <div class="display" style="font-size:22px; color:var(--berry); margin-top:8px;">${t('hero.allDone')}</div>
          <div style="font-size:12.5px; color:var(--text2); margin-top:6px;">${t('hero.allDone.sub')}</div>
        </div>
      `;
      return;
    }
    const segs = Array.from({length: all.length}, (_,i) => {
      const id = all[i].id;
      const cls = p.completed.includes(id) ? 'done' : (id === p.current ? 'current' : '');
      return `<span class="${cls}"></span>`;
    }).join('');
    const pct = Math.round((p.completed.length / all.length) * 100);
    slot.innerHTML = `
      <div onclick="startLessonFlow('${cur.id}')" class="hero" style="position:relative;">
        <img src="assets/bear2.png" alt="" class="duo-mascot duo-mascot-hero" onerror="this.style.display='none'">
        <div style="display:flex; justify-content:space-between; gap: 14px; position: relative; padding-right: 96px;">
          <div style="flex:1; min-width:0;">
            <div class="page-eyebrow" style="color:var(--text2);">${t('hero.eyebrow', { num: cur.num })}</div>
            <div class="display" style="font-size:26px; line-height:1.05; color:var(--berry); margin-top: 6px;">${lessonTitle(cur)}</div>
            <div style="font-size:13px; color:var(--text2); margin-top: 6px;">
              ${cur.ko ? `<span class="ko" style="font-weight:600;">${cur.ko}</span>` : ''}
              ${cur.ru ? ` · <em>${cur.ru}</em>` : ''}
            </div>
          </div>
        </div>
        <div style="margin-top:20px;">
          <div style="display:flex; justify-content:space-between; font-size:11px; margin-bottom:6px;">
            <span style="font-weight:700; color:var(--berry); text-transform:uppercase; letter-spacing:.06em;">${t('hero.counter', { num: cur.num, total: all.length })}</span>
            <span style="color:var(--soft); font-weight:800;">${pct}%</span>
          </div>
          <div class="progress-segments">${segs}</div>
        </div>
        <div style="margin-top:18px; display:flex; justify-content:flex-end; padding-right:104px;">
          <button class="btn btn-primary">${p.completed.length === 0 ? t('hero.start') : t('home.continue')} <i class="fa-solid fa-arrow-right" style="font-size:11px;"></i></button>
        </div>
      </div>
    `;
  }

  // ── Пагинация ленты и видео на главной ──
  let feedPage = 0,  feedShowAll = false;
  let videoPage = 0, videoShowAll = false;
  const FEED_PER_PAGE = 10, VIDEOS_PER_PAGE = 6;
  // Ряд кнопок-номеров страниц
  function pageNavHtml(current, totalPages, fnName) {
    if (totalPages <= 1) return '';
    let nums = '';
    for (let i = 0; i < totalPages; i++) {
      nums += `<button onclick="${fnName}(${i})" class="btn ${i === current ? 'btn-primary' : 'btn-ghost'}" style="min-width:36px; padding:7px 9px; font-size:12.5px;">${i + 1}</button>`;
    }
    return `<div style="display:flex; gap:6px; flex-wrap:wrap; justify-content:center;">${nums}</div>`;
  }
  function showAllFeed()    { feedShowAll = true;  feedPage = 0; renderCustomFeedPosts(); }
  function collapseFeed()   { feedShowAll = false; feedPage = 0; renderCustomFeedPosts(); document.getElementById('custom-feed-posts')?.scrollIntoView({ behavior:'smooth', block:'start' }); }
  function gotoFeedPage(p)  { feedPage = p; renderCustomFeedPosts(); document.getElementById('custom-feed-posts')?.scrollIntoView({ behavior:'smooth', block:'start' }); }
  function showAllVideos()  { videoShowAll = true;  videoPage = 0; renderCustomVideos(); }
  function collapseVideos() { videoShowAll = false; videoPage = 0; renderCustomVideos(); document.getElementById('custom-videos')?.scrollIntoView({ behavior:'smooth', block:'start' }); }
  function gotoVideoPage(p) { videoPage = p; renderCustomVideos(); document.getElementById('custom-videos')?.scrollIntoView({ behavior:'smooth', block:'start' }); }

  function feedImageHtml(image, pid) {
    // Пропускаем только безопасные картиночные ссылки (иначе через '"><img onerror=…>
    // исполнялся бы чужой код в ленте) и экранируем для атрибута src.
    const url = safeImgUrl(image);
    if (!url) return '';
    return `
      <div class="feed-media-wrap" ondblclick="doubleTapLike('${pid}', this, event)" ontouchend="handleMediaTouchTap('${pid}', this, event)">
        <div style="border-radius:14px; overflow:hidden; aspect-ratio:16/9; background:var(--paper); cursor:pointer;">
          <img src="${escHtml(url)}" alt="" style="width:100%; height:100%; object-fit:contain; user-select:none;" draggable="false" onerror="this.closest('.feed-media-wrap').style.display='none'">
        </div>
        <button class="feed-media-expand-btn" onclick="event.stopPropagation(); openMediaLightbox('image', '${jsStr(url)}')" aria-label="${t('ui.252')}" title="${t('ui.252')}">
          <i class="fa-solid fa-up-right-and-down-left-from-center"></i>
        </button>
      </div>`;
  }
  function feedVoiceWave() {
    let bars = '';
    for (let i = 0; i < 34; i++) {
      const h = 4 + Math.round(Math.abs(Math.sin(i * 0.7) + Math.sin(i * 0.31)) * 9);
      bars += `<span style="height:${h}px;"></span>`;
    }
    return `<div class="feed-voice-wave" aria-hidden="true">${bars}</div>`;
  }
  // Type-specific body for a feed post (voice note / word of week / k-pop / plain).
  function feedPostBody(p, pid) {
    const image = normalizeMediaUrl(p.image);
    const media = feedImageHtml(image, pid) + (p.video ? renderFeedPostVideo(p.video) : '');
    if (p.type === 'voice') {
      const phrase = p.koPhrase || p.title || p.body || '';
      return `
        ${media}
        ${p.title ? `<div style="font-weight:600; color:var(--berry); font-size:15px;">${escHtml(p.title)}</div>` : ''}
        ${p.body ? `<div style="font-size:12.5px; color:var(--text2); margin-top:4px; line-height:1.5; white-space:pre-wrap;">${escHtml(p.body)}</div>` : ''}
        ${p.koPhrase ? `<div class="ko" style="font-weight:600; color:var(--berry); margin-top:8px; font-size:15px;">${escHtml(p.koPhrase)}</div>` : ''}
        ${feedVoiceWave()}
        <button onclick="playSyllable('${jsStr(phrase)}', this)" class="btn btn-rose btn-block" style="margin-top:10px;"><i class="fa-solid fa-play" style="font-size:11px;"></i> ${t('ui.220')}</button>
      `;
    }
    if (p.type === 'word') {
      return `
        <div style="display:flex; gap:14px; align-items:center;">
          <div style="width:64px; height:64px; flex-shrink:0; background:var(--card); border:1px solid var(--line); border-radius:16px; display:flex; align-items:center; justify-content:center;">
            <span class="ko" style="font-size:34px; font-weight:800; color:var(--berry); line-height:1;">${escHtml(p.ko || '🌸')}</span>
          </div>
          <div style="flex:1; min-width:0;">
            ${p.title ? `<div style="font-weight:700; color:var(--berry); font-size:15px;">${escHtml(p.title)}</div>` : ''}
            ${(p.translit || p.ru) ? `<div style="font-size:12px; color:var(--text2); margin-top:2px;">${p.translit ? `[${escHtml(p.translit)}] ` : ''}${escHtml(p.ru || '')}</div>` : ''}
            ${p.body ? `<div style="font-size:12px; color:var(--text2); margin-top:4px; line-height:1.45;">${escHtml(p.body)}</div>` : ''}
          </div>
          ${p.ko ? `<button onclick="playSyllable('${jsStr(p.ko)}', this)" class="btn btn-ghost" style="width:40px; height:40px; padding:0; border-radius:50%; flex-shrink:0;"><i class="fa-solid fa-play" style="font-size:12px; color:var(--coral);"></i></button>` : ''}
        </div>
      `;
    }
    if (p.type === 'kpop') {
      const audio = p.koLine || p.title || '';
      return `
        ${media}
        ${p.title ? `<div style="font-weight:700; color:var(--berry); font-size:14px;">${escHtml(p.title)}</div>` : ''}
        ${p.koLine ? `<div class="ko" style="font-weight:600; color:var(--berry); font-size:16px; margin-top:4px; line-height:1.4;">${escHtml(p.koLine)}</div>` : ''}
        ${p.translation ? `<div style="font-style:italic; font-size:13px; color:var(--coral); margin-top:2px;">${escHtml(p.translation)}</div>` : ''}
        ${p.grammar ? `<div style="background:rgba(201,165,92,.12); border-radius:12px; padding:10px 12px; margin-top:10px; line-height:1.5;"><span style="color:var(--gold-ink); font-weight:700; letter-spacing:.14em; font-size:9px;">${t('ui.221')}</span><div style="font-size:12px; color:var(--text2); margin-top:3px;">${escHtml(p.grammar)}</div></div>` : ''}
        ${p.body ? `<div style="font-size:12px; color:var(--text2); margin-top:8px; line-height:1.45; white-space:pre-wrap;">${escHtml(p.body)}</div>` : ''}
        ${audio ? `<button onclick="playSyllable('${jsStr(audio)}', this)" class="btn btn-ghost btn-block" style="margin-top:10px;"><i class="fa-solid fa-volume-up"></i> ${t('ui.222')}</button>` : ''}
      `;
    }
    // announcement / culture / news
    return `
      ${media}
      ${p.title ? `<div style="font-weight:600; color:var(--berry); font-size:15px; line-height:1.3;">${escHtml(p.title)}</div>` : ''}
      ${p.body ? `<div style="font-size:12.5px; color:var(--text2); margin-top:6px; line-height:1.5; white-space:pre-wrap;">${escHtml(p.body)}</div>` : ''}
    `;
  }
  function feedPostCardHtml(p) {
    const typeStyle = {
      announcement: { chip:'chip-coral', label:t('ui.223'),     bg:'feed-card-rose' },
      culture:      { chip:'chip-gold',  label:t('ui.224'),     bg:'feed-card-rose' },
      news:         { chip:'chip-blush', label:t('ui.225'),      bg:'' },
      voice:        { chip:'chip-coral', label:t('ui.226'),    bg:'' },
      word:         { chip:'chip-gold',  label:t('ui.227'), bg:'feed-card-rose' },
      kpop:         { chip:'chip-gold',  label:'🎵 K-POP',        bg:'' }
    };
    const ts = typeStyle[p.type] || typeStyle.announcement;
    const dateStr = p.date ? new Date(p.date).toLocaleDateString('ru-RU', { day:'numeric', month:'long' }) : '';
    const pid = p.id;
    return `
      <div class="feed-card ${ts.bg}" data-post-id="${pid}">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px;">
          <span class="chip ${ts.chip}">${ts.label}</span>
          <span style="font-size:11px; color: var(--soft);">${dateStr}</span>
        </div>
        ${feedPostBody(p, pid)}
        ${feedSocialEnabled() ? renderFeedSocialBar(pid) + renderFeedCommentsBlock(pid) : ''}
      </div>
    `;
  }
  // Friendly built-in feed shown to students before any admin posts exist.
  function welcomeFeedHtml() {
    return `
      <div class="feed-card feed-card-rose">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px;">
          <span class="chip chip-coral">${t('wf.welcome')}</span>
        </div>
        <div style="font-weight:700; color:var(--berry); font-size:16px;">${t('wf.hi')}</div>
        <div style="font-size:13px; color:var(--soft); margin-top:6px; line-height:1.5;">${t('wf.intro')}</div>
        <button type="button" onclick="switchScreen('lessons')" class="btn btn-primary btn-block" style="margin-top:12px;">${t('wf.start')}</button>
      </div>
      <div class="feed-card">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px;">
          <span class="chip chip-gold">${t('wf.wod')}</span>
        </div>
        <div class="ko" style="font-size:30px; font-weight:700; color:var(--berry); line-height:1.1;">안녕하세요</div>
        <div style="font-size:12px; color:var(--soft); margin-top:4px;">${t('wf.wodGloss')}</div>
        <div class="ko-quote" style="margin-top:12px;">${t('wf.wodNote')}</div>
      </div>
      <div class="feed-card">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px;">
          <span class="chip chip-berry">${t('wf.tip')}</span>
        </div>
        <div style="font-weight:700; color:var(--berry); font-size:15px;">${t('wf.tipTitle')}</div>
        <div style="font-size:13px; color:var(--soft); margin-top:6px; line-height:1.5;">${t('wf.tipBody')}</div>
      </div>`;
  }
  function renderCustomFeedPosts() {
    const slot = document.getElementById('custom-feed-posts');
    if (!slot) return;
    let posts = Store.get('customFeedPosts', []);
    if (!Array.isArray(posts)) posts = (posts && typeof posts === 'object') ? Object.values(posts) : [];
    // Migration: every post must have a stable id so likes/comments can reference it
    let migrated = false;
    posts.forEach((p, i) => {
      if (!p.id) {
        p.id = `p_${p.date || Date.now()}_${i}_${Math.random().toString(36).slice(2,7)}`;
        migrated = true;
      }
    });
    if (migrated) {
      // Don't trigger cloud sync overwrite from non-admin clients
      const u = Store.get('user');
      if (u && u.isAdmin) Store.set('customFeedPosts', posts);
      else _origStoreSet && _origStoreSet('customFeedPosts', posts);
    }
    // Соц-лента (посты учеников, композер, лайки/комменты) — только платным тарифам.
    // Бесплатным показываем лишь объявления Мади: соц-слушатели у них не подключены,
    // трафик нулевой. Платному — лениво поднимаем подписку тут (на случай апгрейда).
    const social = feedSocialEnabled();
    const composerSlot = document.getElementById('feed-composer-slot');
    if (social) {
      renderFeedComposer();
      attachFeedListeners();
    } else if (composerSlot) {
      composerSlot.innerHTML = '';
    }
    // Посты учеников из RTDB (shared/userFeedPosts) — публичная лента в стиле Instagram.
    // Сливаем с постами Мади и сортируем по времени (новые сверху).
    const studentPosts = social ? (_userFeedPosts || []).map(p => ({ ...p, date: p.ts || 0, _student: true })) : [];
    const merged = posts.slice().concat(studentPosts).sort((a, b) => (b.date || 0) - (a.date || 0));
    if (merged.length === 0) {
      // Admin sees how to add posts; students get friendly built-in welcome cards
      // (local only — no DB writes, no like/comment bars) so the feed is never empty.
      if (social) syncFeedPidListeners([]);
      slot.innerHTML = isAdmin()
        ? `<div class="card card-padded" style="text-align:center; color:var(--soft); font-size:12.5px; line-height:1.6;">${t('ui.228')}<br>${t('ui.229')} <b style="color:var(--coral);">${t('ui.229')}</b>.</div>`
        : welcomeFeedHtml();
      return;
    }
    const total = merged.length;
    let shown, footer = '';
    if (!feedShowAll) {
      shown = merged.slice(0, 5);
      if (total > 5) footer = `<div><button onclick="showAllFeed()" class="btn btn-ghost btn-block">${t('feed.all', { n: total })}</button></div>`;
    } else {
      const pages = Math.ceil(total / FEED_PER_PAGE);
      if (feedPage > pages - 1) feedPage = pages - 1;
      if (feedPage < 0) feedPage = 0;
      const start = feedPage * FEED_PER_PAGE;
      shown = merged.slice(start, start + FEED_PER_PAGE);
      footer = `<div style="display:grid; gap:8px;">${pageNavHtml(feedPage, pages, 'gotoFeedPage')}<button onclick="collapseFeed()" class="btn btn-ghost btn-block">${t('ui.230')}</button></div>`;
    }
    // Живые лайки/комменты — только для постов, реально показанных на экране сейчас
    // (не для всей истории ленты). Меняется страница/лента — слушатели переезжают.
    syncFeedPidListeners(social ? shown.map(p => p.id) : []);
    slot.innerHTML = shown.map(p => p._student ? studentPostCardHtml(p) : feedPostCardHtml(p)).join('') + footer;
  }

  // ───────────────────────────────────────────────────────────────────────────
  // Публичная лента учеников (Instagram-стиль): фото + подпись + комментарии.
  // Хранение: RTDB shared/userFeedPosts/{id} = {uid,name,avatar,image(base64),caption,ts}.
  // Лайки/комменты переиспользуют общую систему shared/feedLikes|feedComments по pid.
  // ───────────────────────────────────────────────────────────────────────────
  let _userFeedPosts = [];   // [{id, uid, name, avatar, image, caption, ts}]
  let _composerPhoto = null; // base64 выбранного фото в композере

  // Простой фильтр нецензурщины (RU+EN основы). Проверяем по токенам, чтобы
  // не ловить ложные срабатывания на стыках слов.
  const _PROFANITY = ['бляд','блят','сука','сучка','хуй','хуе','хуя','пизд','ебал','ебан','ебат','ебуч','ебу','наху','похуй','залуп','гандон','гондон','мудак','мудил','долбоеб','пидор','пидар','выеб','уебок','уебищ','шлюх','говн','дерьм','залупа','fuck','shit','bitch','asshole','cunt','dick','pussy','faggot','nigger'];
  function containsProfanity(text) {
    if (!text) return false;
    const tokens = String(text).toLowerCase().replace(/ё/g, 'е').split(/[^a-zа-я]+/).filter(Boolean);
    return tokens.some(tok => _PROFANITY.some(w => tok.includes(w)));
  }

  // Композер «поделись фото» над лентой (отдельный слот, зависит от входа)
  function renderFeedComposer() {
    const slot = document.getElementById('feed-composer-slot');
    if (!slot) return;
    const u = Store.get('user');
    const guest = !u || u.guest;
    if (guest) {
      slot.innerHTML = `
        <button type="button" onclick="switchScreen('profile')" class="feed-composer feed-composer-guest">
          <div class="feed-composer-av feed-composer-av-initial"><i class="fa-solid fa-user"></i></div>
          <span class="feed-composer-text">${t('ui.231')}</span>
          <i class="fa-solid fa-arrow-right" style="margin-left:auto; opacity:.6;"></i>
        </button>`;
      return;
    }
    const av = (typeof UStore !== 'undefined') ? UStore.get('avatar') : null;
    slot.innerHTML = `
      <button type="button" onclick="openFeedComposer()" class="feed-composer">
        ${safeImgUrl(av) ? `<img class="feed-composer-av" src="${escHtml(safeImgUrl(av))}" alt="">` : `<div class="feed-composer-av feed-composer-av-initial">${escHtml((socialUserName() || '?').charAt(0).toUpperCase())}</div>`}
        <span class="feed-composer-text">${t('ui.232')}</span>
        <span class="feed-composer-cam"><i class="fa-solid fa-camera"></i></span>
      </button>`;
  }

  // Карточка поста ученика (шапка автора → фото → подпись → лайки/комменты)
  function studentPostCardHtml(p) {
    const pid = p.id;
    const isAuthor = p.uid === socialUserId();
    const canDelete = isAuthor || isAdmin();
    const av = authorAvatar(p);
    const when = p.ts ? relativeTime(p.ts) : '';
    const head = `
      <div class="feed-student-head">
        ${safeImgUrl(av) ? `<img class="feed-student-av" src="${escHtml(safeImgUrl(av))}" alt="">` : `<div class="feed-student-av feed-student-av-initial">${escHtml((p.name || '?').charAt(0).toUpperCase())}</div>`}
        <div style="flex:1; min-width:0;">
          <div class="feed-student-name">${escHtml(p.name || t('feed.studentName'))}${isAuthor ? ` <span class="feed-student-you">${t('feed.you')}</span>` : ''}</div>
          <div class="feed-student-time">${t('feed.studentTag')} · ${escHtml(when)}</div>
        </div>
        ${canDelete
          ? `<button class="feed-student-act" onclick="deleteUserPost('${pid}')" aria-label="${t('ui.233')}" title="${t('ui.018')}"><i class="fa-solid fa-trash-can"></i></button>`
          : `<button class="feed-student-act" onclick="reportUserPost('${pid}')" aria-label="${t('ui.234')}" title="${t('ui.234')}"><i class="fa-regular fa-flag"></i></button>`}
      </div>`;
    return `
      <div class="feed-card feed-card-student" data-post-id="${pid}">
        ${head}
        ${p.image ? feedImageHtml(p.image, pid) : ''}
        ${p.caption ? `<div class="feed-student-caption">${escHtml(p.caption)}</div>` : ''}
        ${renderFeedSocialBar(pid)}
        ${renderFeedCommentsBlock(pid)}
      </div>`;
  }

  function openFeedComposer() {
    const u = Store.get('user');
    if (!u || u.guest) { toast(t('feed.guestPhotoGate'), 'var(--coral)'); switchScreen('profile'); return; }
    _composerPhoto = null;
    const m = document.createElement('div');
    m.className = 'modal-bg modal-center';
    m.id = 'feed-composer-modal';
    m.onclick = e => { if (e.target === m) m.remove(); };
    m.innerHTML = `
      <div class="modal-card" style="max-width:420px;">
        <div style="display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:14px;">
          <div>
            <div class="page-eyebrow">${t('ui.235')}</div>
            <div class="display" style="font-size:20px; color:var(--berry); margin-top:2px;">${t('ui.236')}</div>
          </div>
          <div onclick="this.closest('.modal-bg').remove()" style="font-size:24px; line-height:1; color:var(--soft); cursor:pointer; padding:4px;">×</div>
        </div>
        <input type="file" accept="image/*" capture="environment" id="composer-file" style="display:none;" onchange="onComposerPhotoPick(event)">
        <div id="composer-preview" onclick="document.getElementById('composer-file').click()" class="composer-drop">
          <div style="font-size:40px;">📷</div>
          <div style="font-size:13px; color:var(--soft); margin-top:6px;">${t('ui.237')}</div>
        </div>
        <textarea id="composer-caption" class="input" rows="3" maxlength="600" placeholder="${t('ui.238')}" style="resize:vertical; margin-top:12px;"></textarea>
        <button onclick="publishUserPost()" class="btn btn-primary btn-block" style="margin-top:12px;"><i class="fa-solid fa-paper-plane" style="font-size:12px;"></i> ${t('ui.239')}</button>
        <div style="font-size:10.5px; color:var(--soft); text-align:center; margin-top:10px; line-height:1.5;">${t('ui.240')}</div>
      </div>`;
    document.body.appendChild(m);
  }

  async function onComposerPhotoPick(ev) {
    const file = ev.target.files && ev.target.files[0];
    ev.target.value = '';
    if (!file) return;
    if (!/^image\//.test(file.type)) { toast(t('ui.241')); return; }
    const prev = document.getElementById('composer-preview');
    if (prev) prev.innerHTML = '<div style="font-size:13px; color:var(--soft);">' + t('ui.242') + '</div>';
    try {
      _composerPhoto = await compressImageFile(file, 1000, 0.72);
      if (prev) { prev.classList.add('has-photo'); prev.innerHTML = `<img src="${_composerPhoto}" alt="">`; }
    } catch (_) {
      _composerPhoto = null;
      if (prev) prev.innerHTML = '<div style="font-size:40px;">📷</div><div style="font-size:13px; color:var(--coral); margin-top:6px;">' + t('ui.044') + '</div>';
      toast(t('ui.044'));
    }
  }

  async function publishUserPost() {
    if (typeof _db === 'undefined') { toast(t('ui.243')); return; }
    const u = Store.get('user');
    if (!u || u.guest) { toast(t('ui.244')); return; }
    if (!_composerPhoto) { toast(t('ui.245')); return; }
    const capEl = document.getElementById('composer-caption');
    const caption = capEl ? (capEl.value || '').trim().slice(0, 600) : '';
    if (containsProfanity(caption)) { toast(t('ui.246')); return; }
    const btn = document.querySelector('#feed-composer-modal .btn-primary');
    if (btn) { btn.disabled = true; btn.textContent = t('ui.247'); }
    // Фото поста — в Storage: последние 40 постов скачивает КАЖДЫЙ клиент при
    // каждом запуске, base64 внутри узла умножал этот трафик в сотни раз.
    let image = _composerPhoto;
    if (isDataUrl(image) && typeof _storage !== 'undefined') {
      try { image = await uploadDataUrlToStorage(image, `feed/user/${socialUserId()}_${Date.now()}.jpg`); } catch (_) {}
    }
    const myAv = ((typeof UStore !== 'undefined') ? UStore.get('avatar') : null) || null;
    const post = {
      uid: socialUserId(),
      name: socialUserName(),
      avatar: isDataUrl(myAv) ? null : myAv, // base64-аватар в общий узел не пускаем — покажется инициал
      image,
      caption,
      ts: Date.now()
    };
    try {
      await _db.ref('shared/userFeedPosts').push(post);
      _composerPhoto = null;
      document.getElementById('feed-composer-modal')?.remove();
      toast(t('feed.published'), 'var(--sage)');
      if (typeof addXp === 'function') addXp(5);
      if (typeof spawnConfetti === 'function') spawnConfetti();
    } catch (e) {
      console.warn('publishUserPost failed', e);
      if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fa-solid fa-paper-plane" style="font-size:12px;"></i> ' + t('ui.239'); }
      toast(t('ui.248'));
    }
  }

  async function deleteUserPost(pid) {
    if (typeof _db === 'undefined') return;
    const post = (_userFeedPosts || []).find(p => p.id === pid);
    if (!post) return;
    const mine = post.uid === socialUserId();
    if (!mine && !isAdmin()) { toast(t('ui.249')); return; }
    if (!confirm(t('ui.250'))) return;
    try {
      await _db.ref('shared/userFeedPosts/' + pid).remove();
      if (post.image && /^https?:/.test(post.image) && typeof _storage !== 'undefined') {
        try { _storage.refFromURL(post.image).delete().catch(() => {}); } catch (_) {}
      }
      _db.ref('shared/feedLikes/' + pid).remove().catch(() => {});
      _db.ref('shared/feedComments/' + pid).remove().catch(() => {});
      _db.ref('shared/feedReports/' + pid).remove().catch(() => {});
      toast(t('feed.postDeleted'), 'var(--sage)');
    } catch (e) { console.warn('deleteUserPost failed', e); toast(t('ui.126')); }
  }

  async function reportUserPost(pid) {
    if (typeof _db === 'undefined') { toast(t('ui.243')); return; }
    const uid = socialUserId();
    try {
      await _db.ref(`shared/feedReports/${pid}/${uid}`).set({ ts: Date.now(), name: socialUserName() });
      toast(t('feed.reported'), 'var(--sage)');
    } catch (e) { toast(t('ui.251')); }
  }

  // Build the inline video player markup for a feed post — handles YouTube / GDrive / direct file
  function renderFeedPostVideo(url) {
    if (!url) return '';
    url = normalizeMediaUrl(url);
    const yid = ytIdFromUrl(url);
    const gid = !yid ? gdriveIdFromUrl(url) : null;
    const isFile = !yid && !gid && isDirectVideoUrl(url);
    let inner = '';
    let lightboxAttr = '';
    if (yid) {
      const thumb = `https://img.youtube.com/vi/${yid}/hqdefault.jpg`;
      inner = `
        <div class="video-player-slot" style="position:relative; aspect-ratio:16/9; background:#000; border-radius:14px; overflow:hidden; cursor:pointer;" onclick="playCustomVideo('youtube','${yid}', this)">
          <img src="${thumb}" style="width:100%; height:100%; object-fit:cover;" alt="">
          <div style="position:absolute; inset:0; background:linear-gradient(180deg, transparent 50%, rgba(0,0,0,.55)); display:flex; align-items:center; justify-content:center;">
            <div style="width:54px; height:54px; border-radius:50%; background:var(--grad-coral); color:white; display:flex; align-items:center; justify-content:center; box-shadow: var(--shadow-lg); font-size:18px;"><i class="fa-solid fa-play"></i></div>
          </div>
        </div>`;
      lightboxAttr = `onclick="event.stopPropagation(); openMediaLightbox('youtube', '${yid}')"`;
    } else if (gid) {
      inner = `
        <div class="video-player-slot" style="position:relative; aspect-ratio:16/9; background:#000; border-radius:14px; overflow:hidden; cursor:pointer;" onclick="playCustomVideo('gdrive','${gid}', this)">
          <div style="position:absolute; inset:0; background:linear-gradient(140deg, var(--berry), var(--coral)); display:flex; align-items:center; justify-content:center;">
            <div style="width:54px; height:54px; border-radius:50%; background:var(--card); color:var(--coral); display:flex; align-items:center; justify-content:center; box-shadow: var(--shadow-lg); font-size:18px;"><i class="fa-solid fa-play"></i></div>
          </div>
          <div style="position:absolute; bottom:8px; left:10px; font-size:10px; color:rgba(255,255,255,.7);">Google Drive</div>
        </div>`;
      lightboxAttr = `onclick="event.stopPropagation(); openMediaLightbox('gdrive', '${gid}')"`;
    } else if (isFile) {
      const safeUrl = String(url).replace(/['"]/g, '');
      inner = `<div style="aspect-ratio:16/9; background:#000; border-radius:14px; overflow:hidden;">
        <video src="${url}" controls preload="metadata" playsinline style="width:100%; height:100%; object-fit:contain; background:#000; display:block;"></video>
      </div>`;
      lightboxAttr = `onclick="event.stopPropagation(); openMediaLightbox('video', '${safeUrl}')"`;
    } else {
      return '';
    }
    return `
      <div class="feed-media-wrap">
        ${inner}
        <button class="feed-media-expand-btn" ${lightboxAttr} aria-label="${t('ui.252')}" title="${t('ui.252')}">
          <i class="fa-solid fa-up-right-and-down-left-from-center"></i>
        </button>
      </div>`;
  }

  // ── Double-tap to like (Instagram-style) ──
  // Touch devices fire 'click' on each tap, but native 'dblclick' is unreliable on mobile —
  // so we listen to both: ondblclick for desktop, and a manual touch-timing handler for mobile.
  // After a touch-handled double-tap, mobile browsers still synthesize a dblclick from the two
  // clicks — we suppress that duplicate via a short-lived timestamp.
  const _mediaTapTimes = {};
  let _touchDoubleTapAt = 0;
  function _tapClientPoint(ev) {
    if (!ev) return null;
    if (ev.changedTouches && ev.changedTouches.length) {
      const t = ev.changedTouches[0];
      return { x: t.clientX, y: t.clientY };
    }
    if (typeof ev.clientX === 'number' && typeof ev.clientY === 'number') {
      return { x: ev.clientX, y: ev.clientY };
    }
    return null;
  }

  function handleMediaTouchTap(pid, wrap, ev) {
    // Skip if the touch was on the expand button (it stops propagation already, but double-check)
    if (ev && ev.target && ev.target.closest && ev.target.closest('.feed-media-expand-btn')) return;
    const now = Date.now();
    const last = _mediaTapTimes[pid] || 0;
    if (now - last < 320 && last > 0) {
      _mediaTapTimes[pid] = 0;
      _touchDoubleTapAt = now;
      if (ev && ev.preventDefault) ev.preventDefault();
      doubleTapLike(pid, wrap, ev);
    } else {
      _mediaTapTimes[pid] = now;
    }
  }

  function doubleTapLike(pid, wrap, ev) {
    // Suppress dblclick that mobile browsers synthesize right after we already handled
    // the double-tap from touchend — otherwise we'd spawn two hearts.
    if (ev && ev.type === 'dblclick' && Date.now() - _touchDoubleTapAt < 700) return;
    // Like the post if it isn't already liked (Instagram never unlikes on double-tap)
    const uid = socialUserId();
    const isLiked = !!(_feedLikes[pid] && _feedLikes[pid][uid]);
    if (!isLiked) {
      const btn = document.querySelector(`.feed-like-btn[data-post-id="${pid}"]`);
      toggleFeedLike(pid, btn || undefined);
    }

    // Compute local coordinates inside wrap (if event available)
    let x = null, y = null;
    const pt = _tapClientPoint(ev);
    if (pt && wrap && wrap.getBoundingClientRect) {
      const r = wrap.getBoundingClientRect();
      x = pt.x - r.left;
      y = pt.y - r.top;
    }
    showDoubleTapHeart(wrap, x, y);
  }

  // Color palette: choose random color each time, avoid repeating the same color twice
  const _heartColors = ['#FF4D6D', '#FFD166', '#84C474', '#62B6CB', '#A06CD5', '#F2A6AE', '#E07686', '#FF8FAB'];
  let _lastHeartColorIdx = -1;
  function showDoubleTapHeart(wrap, x, y) {
    if (!wrap) return;
    let idx = Math.floor(Math.random() * _heartColors.length);
    if (_heartColors.length > 1 && idx === _lastHeartColorIdx) {
      idx = (idx + 1) % _heartColors.length;
    }
    _lastHeartColorIdx = idx;
    const color = _heartColors[idx];
    const heart = document.createElement('div');
    heart.className = 'media-double-tap-heart';
    heart.style.color = color;
    // Tint the soft glow to match the heart so the whole pop feels cohesive
    heart.style.textShadow = `0 4px 16px rgba(0,0,0,.4), 0 0 14px ${color}88`;
    heart.innerHTML = '<i class="fa-solid fa-heart"></i>';
    // If coordinates provided, position the heart there (CSS keeps translate(-50%,-50%) for centering)
    if (typeof x === 'number' && typeof y === 'number') {
      heart.style.left = x + 'px';
      heart.style.top = y + 'px';
    }
    wrap.appendChild(heart);
    // Spawn sakura burst from the same point (fallback: center)
    spawnSakuraBurst(wrap, x, y);
    setTimeout(() => heart.remove(), 1000);
  }

  // Spawn a small burst of sakura emoji particles. Positions are absolute inside `wrap`.
  function spawnSakuraBurst(wrap, x, y) {
    if (!wrap) return;
    const hasPt = (typeof x === 'number' && typeof y === 'number');
    const symbols = ['🌸', '🌸', '🌸', '🌺', '✿'];
    const count = 7 + Math.floor(Math.random() * 4); // 7-10
    const r = wrap.getBoundingClientRect();
    for (let i = 0; i < count; i++) {
      const p = document.createElement('div');
      p.className = 'media-sakura-particle';
      p.textContent = symbols[Math.floor(Math.random() * symbols.length)];
      p.style.position = 'absolute';
      p.style.pointerEvents = 'none';
      p.style.opacity = '1';
      p.style.fontSize = (12 + Math.random() * 10) + 'px';
      // origin point
      const ox = hasPt ? x : r.width / 2;
      const oy = hasPt ? y : r.height / 2;
      p.style.left = ox + 'px';
      p.style.top = oy + 'px';
      p.style.transform = 'translate(-50%, -50%) scale(1)';
      // append first so transitions apply
      wrap.appendChild(p);

      // compute target offset
      const angle = (Math.PI * 2) * (i / count) + (Math.random() - 0.5) * 0.6;
      const dist = 36 + Math.random() * 48;
      const dx = Math.cos(angle) * dist;
      const dy = Math.sin(angle) * dist - (10 + Math.random() * 10);
      const rot = (Math.random() - 0.5) * 90;
      const dur = 700 + Math.floor(Math.random() * 500);
      // animate via transition
      p.style.transition = `transform ${dur}ms cubic-bezier(.22,1,.36,1), opacity ${dur}ms ease-out`;
      // delay slightly per particle
      p.style.transitionDelay = (Math.random() * 80) + 'ms';
      requestAnimationFrame(() => {
        p.style.transform = `translate(calc(-50% + ${dx.toFixed(1)}px), calc(-50% + ${dy.toFixed(1)}px)) rotate(${rot}deg) scale(.85)`;
        p.style.opacity = '0';
      });
      setTimeout(() => { try { p.remove(); } catch (_) {} }, dur + 220);
    }
  }

  // Lightbox: shows image/video at full size in a fullscreen-ish overlay
  // Global tap-to-enlarge for any element with .photo-zoom
  // Extracts URL from: data-photo-src → inline backgroundImage → inner <img>.
  // Capture phase + stopPropagation so clicking an avatar inside a friend card
  // opens the lightbox instead of the chat.
  document.addEventListener('click', e => {
    const el = e.target.closest('.photo-zoom');
    if (!el) return;
    let src = el.dataset.photoSrc || '';
    if (!src) {
      const bg = el.style.backgroundImage || '';
      const mm = bg.match(/url\(["']?(.+?)["']?\)/);
      if (mm) src = mm[1];
    }
    if (!src) {
      const img = el.querySelector('img');
      if (img && img.src) src = img.src;
    }
    if (!src) return;
    e.stopPropagation();
    e.preventDefault();
    openMediaLightbox('image', src);
  }, true);

  function openMediaLightbox(kind, src) {
    const m = document.createElement('div');
    m.className = 'modal-bg modal-center';
    m.style.background = 'rgba(0,0,0,.92)';
    m.style.zIndex = '900';
    m.style.padding = '20px';
    m.onclick = e => { if (e.target === m) m.remove(); };
    let content = '';
    if (kind === 'image') {
      const url = safeImgUrl(src);
      if (!url) return; // небезопасная ссылка — не открываем (защита в глубину к фиксу ленты)
      content = `<img src="${escHtml(url)}" alt="" style="max-width:96vw; max-height:88vh; object-fit:contain; border-radius:12px; display:block; box-shadow: 0 20px 60px rgba(0,0,0,.4);">`;
    } else if (kind === 'youtube') {
      content = `<iframe src="https://www.youtube.com/embed/${src}?autoplay=1" style="width:min(960px,96vw); aspect-ratio:16/9; border:0; border-radius:12px;" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen></iframe>`;
    } else if (kind === 'gdrive') {
      content = `<iframe src="https://drive.google.com/file/d/${src}/preview" style="width:min(960px,96vw); aspect-ratio:16/9; border:0; border-radius:12px;" allow="autoplay" allowfullscreen></iframe>`;
    } else if (kind === 'video') {
      content = `<video src="${escHtml(String(src || ''))}" controls autoplay playsinline style="max-width:96vw; max-height:88vh; border-radius:12px; background:#000;"></video>`;
    }
    m.innerHTML = `
      <div style="position:relative; display:flex; align-items:center; justify-content:center;">
        ${content}
        <button onclick="this.closest('.modal-bg').remove()" aria-label="${t('ui.023')}" style="position:absolute; top:10px; right:10px; background:rgba(0,0,0,.55); backdrop-filter:blur(8px); -webkit-backdrop-filter:blur(8px); border:1px solid rgba(255,255,255,.22); color:white; width:34px; height:34px; border-radius:10px; cursor:pointer; font-size:18px; display:flex; align-items:center; justify-content:center; line-height:1; z-index:10;">×</button>
      </div>
    `;
    document.body.appendChild(m);
  }

  // ── Feed: likes + comments (synced via Firebase) ──
  let _feedLikes = {};      // { postId: { uid: true } }
  let _feedComments = {};   // { postId: [{id, uid, name, text, ts, avatar?}] sorted asc by ts }
  let _feedListenersAttached = false;
  // pid → отписка от shared/feedLikes|feedComments для этого поста. Слушаем ТОЧЕЧНО
  // только показанные сейчас посты (макс. FEED_PER_PAGE), а не весь узел целиком —
  // иначе трафик растёт вместе с ОБЩИМ числом лайков/комментов по всем постам за всю
  // историю ленты, а не с тем, что реально на экране (см. rtdb-download-blowup, 07.2026).
  const _feedPidOffs = {};
  function watchFeedPost(pid) {
    if (!pid || _feedPidOffs[pid] || typeof _db === 'undefined') return;
    const likesRef = _db.ref('shared/feedLikes/' + pid);
    const likesHandler = snap => { _feedLikes[pid] = snap.val() || {}; refreshFeedSocial(); };
    likesRef.on('value', likesHandler);
    const commentsRef = _db.ref('shared/feedComments/' + pid);
    const commentsHandler = snap => {
      const obj = snap.val() || {};
      _feedComments[pid] = Object.entries(obj)
        .map(([id, c]) => ({ id, ...c }))
        .sort((a, b) => (a.ts || 0) - (b.ts || 0));
      watchAvatarsForComments();
      refreshFeedSocial();
    };
    commentsRef.on('value', commentsHandler);
    _feedPidOffs[pid] = () => {
      try { likesRef.off('value', likesHandler); } catch (_) {}
      try { commentsRef.off('value', commentsHandler); } catch (_) {}
    };
  }
  function unwatchFeedPost(pid) {
    const off = _feedPidOffs[pid];
    if (!off) return;
    off();
    delete _feedPidOffs[pid];
    delete _feedLikes[pid];
    delete _feedComments[pid];
  }
  // Вызывается при каждом рендере ленты с массивом id постов, видимых прямо сейчас —
  // подписывает новые, отписывает те, что пропали с экрана (сменилась страница/лента).
  function syncFeedPidListeners(pids) {
    const wanted = new Set(pids || []);
    Object.keys(_feedPidOffs).forEach(pid => { if (!wanted.has(pid)) unwatchFeedPost(pid); });
    wanted.forEach(pid => watchFeedPost(pid));
  }

  function fbKey(s) { return String(s).replace(/[.#$\[\]\/]/g, '_'); }

  // Stable identity for likes/comments. Logged-in users share an id across devices;
  // guests get a per-browser id so their own likes/comments stay attributed to them.
  function socialUserId() {
    const u = Store.get('user');
    if (u && !u.guest) {
      if (u.isAdmin) return fbKey(`admin_${(u.email || u.name).toLowerCase()}`);
      if (u.email)   return fbKey(`user_${u.email.toLowerCase()}`);
      return fbKey(`user_${(u.name || 'anon').toLowerCase()}`);
    }
    let gid = null;
    try { gid = localStorage.getItem('madie_socialGuestId'); } catch (_) {}
    if (!gid) {
      gid = 'g_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 9);
      try { localStorage.setItem('madie_socialGuestId', gid); } catch (_) {}
    }
    return gid;
  }
  function socialUserName() {
    const u = Store.get('user');
    if (u && u.name) return u.name;
    return gw(t('auth.guestF'), t('auth.guest'));
  }

  // Live cache of user avatars by social uid. Comments only store the avatar
  // at the moment of posting; this cache lets us show the *current* avatar of
  // each author across all their past comments/replies.
  const _userAvatars = {};
  const _watchedAvatars = new Set();
  const _avatarOffs = {};                       // uid → функция отписки от avatar-слушателя
  function watchUserAvatar(uid) {
    if (!uid || _watchedAvatars.has(uid)) return;
    // Skip guest/local-only ids — they don't live under users/{uid}
    if (uid.startsWith('g_')) return;
    if (typeof _db === 'undefined') return;
    _watchedAvatars.add(uid);
    const ref = _db.ref(`users/${uid}/avatar`);
    const handler = snap => {
      const v = snap.val() || null;
      if (v !== _userAvatars[uid]) {
        _userAvatars[uid] = v;
        // Avatar changes don't affect structure hash, so the surgical patch path
        // would skip the re-render. Invalidate the cache so the avatar refreshes.
        Object.keys(_structureHashCache).forEach(k => delete _structureHashCache[k]);
        refreshFeedSocial();
      }
    };
    ref.on('value', handler);
    _avatarOffs[uid] = () => { try { ref.off('value', handler); } catch (_) {} };
  }
  // Отписаться от всех avatar-слушателей и сбросить кэш — при logout/смене пользователя,
  // иначе слушатели прежней личности продолжают дёргать refreshFeedSocial (утечка).
  function detachAvatarWatchers() {
    Object.values(_avatarOffs).forEach(off => { try { off(); } catch (_) {} });
    Object.keys(_avatarOffs).forEach(k => delete _avatarOffs[k]);
    _watchedAvatars.clear();
    Object.keys(_userAvatars).forEach(k => delete _userAvatars[k]);
  }
  function watchAvatarsForComments() {
    Object.values(_feedComments).forEach(list => {
      list.forEach(c => {
        if (c.uid) watchUserAvatar(c.uid);
        if (c.replies) Object.values(c.replies).forEach(r => { if (r && r.uid) watchUserAvatar(r.uid); });
      });
    });
  }
  // Returns the freshest avatar for a comment/reply author (live cache > stored > null)
  function authorAvatar(item) {
    if (!item) return null;
    if (item.uid && _userAvatars[item.uid]) return _userAvatars[item.uid];
    return item.avatar || null;
  }

  function attachFeedListeners() {
    if (typeof _db === 'undefined' || _feedListenersAttached) return;
    // Гость/«Базовый» соц-слой не грузят вообще — 0 трафика. Флаг НЕ ставим, чтобы
    // при апгрейде до платного (renderCustomFeedPosts вызовет снова) подписка встала.
    if (!feedSocialEnabled()) return;
    _feedListenersAttached = true;
    // Лайки/комменты — точечно per-pid, см. syncFeedPidListeners (вызывается из renderCustomFeedPosts).
    // Публичные посты учеников (последние 40, новые внизу узла — сортируем в рендере)
    _db.ref('shared/userFeedPosts').orderByChild('ts').limitToLast(40).on('value', snap => {
      const data = snap.val() || {};
      _userFeedPosts = Object.entries(data).map(([id, p]) => ({ id, ...p }));
      renderCustomFeedPosts();
    });
  }

  function renderFeedSocialBar(pid) {
    const me = socialUserId();
    const likes = _feedLikes[pid] || {};
    const likeCount = Object.keys(likes).length;
    const liked = !!likes[me];
    const cmCount = totalCommentsCount(pid);
    return `
      <div class="feed-social">
        <button class="feed-social-btn feed-like-btn ${liked ? 'liked' : ''}" data-post-id="${pid}" onclick="toggleFeedLike('${pid}', this)" aria-label="${t('ui.253')}">
          <span class="heart-fx"><i class="${liked ? 'fa-solid' : 'fa-regular'} fa-heart"></i></span>
          <span class="like-count">${likeCount}</span>
        </button>
        <button class="feed-social-btn" onclick="focusFeedInput('${pid}')" aria-label="${t('ui.254')}">
          <i class="fa-regular fa-comment"></i>
          <span class="feed-comment-count" data-post-id="${pid}">${cmCount}</span>
        </button>
      </div>
    `;
  }

  // Click on the comment-count chip jumps focus to the input below
  function focusFeedInput(pid) {
    const card = document.querySelector(`.feed-card[data-post-id="${pid}"]`);
    if (!card) return;
    const inp = card.querySelector('.feed-comment-input');
    if (!inp) return;
    try { inp.focus({ preventScroll: false }); } catch (_) { inp.focus(); }
    inp.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }

  // Always-visible comments block: scrollable list (empty hint when no comments) + input
  function renderFeedCommentsBlock(pid) {
    return `
      <div class="feed-comments-block" data-post-id="${pid}">
        <div class="feed-comments-list" data-post-id="${pid}">${renderCommentsList(pid)}</div>
        <div class="feed-comment-form">
          <input class="feed-comment-input" placeholder="${t('ui.255')}" maxlength="500" data-post-id="${pid}" onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();submitFeedComment('${pid}', this);}">
          <button class="feed-comment-send" onclick="submitFeedComment('${pid}', this)" aria-label="${t('ui.111')}"><i class="fa-solid fa-paper-plane"></i></button>
        </div>
      </div>
    `;
  }

  // ── Comment counting / sorting helpers ──
  function commentLikeCount(c) { return c && c.likes ? Object.keys(c.likes).length : 0; }
  function repliesArray(c) {
    if (!c || !c.replies) return [];
    return Object.entries(c.replies)
      .map(([rid, r]) => ({ rid, ...r }))
      .sort((a, b) => (a.ts || 0) - (b.ts || 0));
  }
  function totalCommentsCount(pid) {
    const list = _feedComments[pid] || [];
    let total = list.length;
    list.forEach(c => { total += repliesArray(c).length; });
    return total;
  }
  // Which comment IDs have their replies block currently expanded (preserved across re-renders)
  const _expandedReplies = new Set();
  function pluralReplies(n) {
    if (APP_LANG === 'uz') return 'javob';
    if (APP_LANG === 'en') return n === 1 ? 'reply' : 'replies';
    const m100 = n % 100, m10 = n % 10;
    if (m100 >= 11 && m100 <= 14) return 'ответов';
    if (m10 === 1) return 'ответ';
    if (m10 >= 2 && m10 <= 4) return 'ответа';
    return 'ответов';
  }

  // ── Comment item ──
  function renderCommentItem(pid, c) {
    const me = socialUserId();
    const initial = (c.name || '?').charAt(0).toUpperCase();
    const avUrl = authorAvatar(c);
    // Strip any quote chars from the URL so it can sit safely inside a single-quoted url('...')
    const avSafe = avUrl ? String(avUrl).replace(/['"]/g, '') : '';
    const avStyle = avUrl ? `background-image:url('${avSafe}');` : '';
    const avContent = avUrl ? '' : initial;
    const avClass = avUrl ? 'feed-comment-avatar photo-zoom' : 'feed-comment-avatar';
    const own = c.uid === me;
    const delBtn = own ? `<button class="feed-comment-delete" onclick="deleteFeedComment('${pid}', '${c.id}')" title="${t('ui.018')}">×</button>` : '';
    const likes = c.likes || {};
    const likeN = Object.keys(likes).length;
    const iLiked = !!likes[me];
    const replies = repliesArray(c);
    const repliesOpen = _expandedReplies.has(c.id);
    const repToggleLabel = repliesOpen ? `${t('feed.hide')} ${pluralReplies(replies.length)}` : `${t('feed.show')} ${replies.length} ${pluralReplies(replies.length)}`;
    return `
      <div class="feed-comment-item" data-cid="${c.id}">
        <div class="${avClass}" style="${avStyle}">${avContent}</div>
        <div class="feed-comment-bubble">
          <div class="feed-comment-head">
            <span class="feed-comment-name">${escAttrSafe(c.name || t('feed.noName'))}</span>
            <span class="feed-comment-time">${relativeTime(c.ts)}</span>
            ${delBtn}
          </div>
          <div class="feed-comment-text">${escAttrSafe(c.text)}</div>
          <div class="comment-actions">
            <button class="comment-action comment-like-btn ${iLiked ? 'liked' : ''}" data-pid="${pid}" data-cid="${c.id}" aria-label="${t('feed.like')}" onclick="toggleCommentLike('${pid}', '${c.id}', this)">
              <i class="${iLiked ? 'fa-solid' : 'fa-regular'} fa-heart"></i>
              <span class="comment-like-count">${likeN || ''}</span>
            </button>
            <button class="comment-action" onclick="toggleReplyForm('${pid}', '${c.id}', this)">
              <i class="fa-regular fa-comment"></i>
              <span>${t('ui.122')}</span>
            </button>
          </div>
          ${replies.length ? `
            <button class="comment-replies-toggle ${repliesOpen ? 'open' : ''}" onclick="toggleCommentReplies('${c.id}', this)">
              <span class="rep-label">${repToggleLabel}</span>
              <i class="fa-solid fa-chevron-down chev"></i>
            </button>
            <div class="comment-replies ${repliesOpen ? 'open' : ''}" data-cid="${c.id}">${replies.map(r => renderReplyItem(pid, c.id, r)).join('')}</div>
          ` : ''}
          <div class="reply-form-wrap" data-cid="${c.id}">
            <input class="reply-input" maxlength="500" placeholder="${t('feed.replyTo', { name: escAttrSafe(c.name || '') })}" onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();submitReply('${pid}', '${c.id}', this);}">
            <button class="reply-send" onclick="submitReply('${pid}', '${c.id}', this)" aria-label="${t('ui.111')}"><i class="fa-solid fa-paper-plane"></i></button>
          </div>
        </div>
      </div>
    `;
  }

  function toggleCommentReplies(cid, btn) {
    const item = btn.closest('.feed-comment-item');
    if (!item) return;
    const block = item.querySelector(`.comment-replies[data-cid="${cid}"]`);
    if (!block) return;
    const willOpen = !block.classList.contains('open');
    block.classList.toggle('open', willOpen);
    btn.classList.toggle('open', willOpen);
    if (willOpen) _expandedReplies.add(cid);
    else _expandedReplies.delete(cid);
    const n = block.querySelectorAll('.reply-item').length;
    const label = btn.querySelector('.rep-label');
    if (label) label.textContent = willOpen ? `Скрыть ${pluralReplies(n)}` : `Посмотреть ${n} ${pluralReplies(n)}`;
  }

  function renderReplyItem(pid, cid, r) {
    const me = socialUserId();
    const initial = (r.name || '?').charAt(0).toUpperCase();
    const avUrl = authorAvatar(r);
    const avSafe = avUrl ? String(avUrl).replace(/['"]/g, '') : '';
    const avStyle = avUrl ? `background-image:url('${avSafe}');` : '';
    const avContent = avUrl ? '' : initial;
    const avClass = avUrl ? 'feed-comment-avatar photo-zoom' : 'feed-comment-avatar';
    const own = r.uid === me;
    const delBtn = own ? `<button class="feed-comment-delete" onclick="deleteReply('${pid}', '${cid}', '${r.rid}')" title="${t('ui.018')}">×</button>` : '';
    const likes = r.likes || {};
    const likeN = Object.keys(likes).length;
    const iLiked = !!likes[me];
    return `
      <div class="reply-item" data-rid="${r.rid}">
        <div class="${avClass}" style="${avStyle}">${avContent}</div>
        <div class="feed-comment-bubble">
          <div class="feed-comment-head">
            <span class="feed-comment-name">${escAttrSafe(r.name || t('feed.noName'))}</span>
            <span class="feed-comment-time">${relativeTime(r.ts)}</span>
            ${delBtn}
          </div>
          <div class="feed-comment-text">${escAttrSafe(r.text)}</div>
          <div class="comment-actions">
            <button class="comment-action reply-like-btn ${iLiked ? 'liked' : ''}" data-pid="${pid}" data-cid="${cid}" data-rid="${r.rid}" aria-label="Нравится" onclick="toggleReplyLike('${pid}', '${cid}', '${r.rid}', this)">
              <i class="${iLiked ? 'fa-solid' : 'fa-regular'} fa-heart"></i>
              <span class="reply-like-count">${likeN || ''}</span>
            </button>
          </div>
        </div>
      </div>
    `;
  }

  function renderCommentsList(pid) {
    const list = _feedComments[pid] || [];
    if (list.length === 0) return '<div class="feed-comment-empty">' + t('ui.256') + '</div>';
    // Most-liked first; ties broken by oldest (so without any likes, the first-poster appears on top)
    const sorted = list.slice().sort((a, b) => {
      const la = commentLikeCount(a), lb = commentLikeCount(b);
      if (lb !== la) return lb - la;
      return (a.ts || 0) - (b.ts || 0);
    });
    return sorted.map(c => renderCommentItem(pid, c)).join('');
  }

  // Tracks last-rendered structural hash per post so we can do cheap in-place patches
  // instead of full innerHTML re-renders when only likes change (preserves animations + typing).
  const _structureHashCache = {};
  function commentsStructureHash(pid) {
    const list = _feedComments[pid] || [];
    return list.map(c => {
      const replyIds = c.replies ? Object.keys(c.replies).sort().join(',') : '';
      return `${c.id}:${replyIds}`;
    }).join('|');
  }
  function patchCommentLikesInPlace(listEl, pid) {
    const me = socialUserId();
    const list = _feedComments[pid] || [];
    list.forEach(c => {
      const item = listEl.querySelector(`.feed-comment-item[data-cid="${c.id}"]`);
      if (!item) return;
      // Comment-level like
      const likes = c.likes || {};
      const iLiked = !!likes[me];
      const n = Object.keys(likes).length;
      const likeBtn = item.querySelector('.comment-like-btn');
      if (likeBtn) {
        likeBtn.classList.toggle('liked', iLiked);
        const icon = likeBtn.querySelector('i');
        if (icon) icon.className = (iLiked ? 'fa-solid' : 'fa-regular') + ' fa-heart';
        const cnt = likeBtn.querySelector('.comment-like-count');
        if (cnt) cnt.textContent = n || '';
      }
      // Reply-level likes
      repliesArray(c).forEach(r => {
        const rItem = item.querySelector(`.reply-item[data-rid="${r.rid}"]`);
        if (!rItem) return;
        const rLikes = r.likes || {};
        const riLiked = !!rLikes[me];
        const rn = Object.keys(rLikes).length;
        const rBtn = rItem.querySelector('.reply-like-btn');
        if (rBtn) {
          rBtn.classList.toggle('liked', riLiked);
          const rIcon = rBtn.querySelector('i');
          if (rIcon) rIcon.className = (riLiked ? 'fa-solid' : 'fa-regular') + ' fa-heart';
          const rCnt = rBtn.querySelector('.reply-like-count');
          if (rCnt) rCnt.textContent = rn || '';
        }
      });
    });
  }

  function refreshFeedSocial() {
    // Post-level like buttons
    document.querySelectorAll('.feed-like-btn').forEach(btn => {
      const pid = btn.dataset.postId;
      if (!pid) return;
      const likes = _feedLikes[pid] || {};
      const count = Object.keys(likes).length;
      const liked = !!likes[socialUserId()];
      btn.classList.toggle('liked', liked);
      const icon = btn.querySelector('i');
      if (icon) icon.className = (liked ? 'fa-solid' : 'fa-regular') + ' fa-heart';
      const counter = btn.querySelector('.like-count');
      if (counter) counter.textContent = count;
    });
    // Comment count chip (includes replies)
    document.querySelectorAll('.feed-comment-count').forEach(el => {
      const pid = el.dataset.postId;
      if (!pid) return;
      el.textContent = totalCommentsCount(pid);
    });
    // Preserve any in-progress reply forms before potential re-render
    const savedReplies = {};
    document.querySelectorAll('.reply-form-wrap.open').forEach(form => {
      const cid = form.dataset.cid;
      const input = form.querySelector('input');
      if (cid && input) savedReplies[cid] = { text: input.value, focused: document.activeElement === input };
    });
    // Comment lists: surgical patch when structure unchanged, full re-render otherwise
    document.querySelectorAll('.feed-comments-list').forEach(el => {
      const pid = el.dataset.postId;
      if (!pid) return;
      const curHash = commentsStructureHash(pid);
      if (curHash === _structureHashCache[pid]) {
        patchCommentLikesInPlace(el, pid);
      } else {
        _structureHashCache[pid] = curHash;
        el.innerHTML = renderCommentsList(pid);
      }
    });
    // Restore any reply forms that were open with in-progress text
    Object.entries(savedReplies).forEach(([cid, state]) => {
      const form = document.querySelector(`.reply-form-wrap[data-cid="${cid}"]`);
      if (!form) return;
      form.classList.add('open');
      const input = form.querySelector('input');
      if (input) {
        input.value = state.text;
        if (state.focused) try { input.focus({ preventScroll: true }); } catch (_) { input.focus(); }
      }
    });
  }

  async function toggleFeedLike(pid, btn) {
    if (typeof _db === 'undefined') { toast(t('ui.243')); return; }
    if (!btn) btn = document.querySelector(`.feed-like-btn[data-post-id="${pid}"]`);
    const uid = socialUserId();
    if (!_feedLikes[pid]) _feedLikes[pid] = {};
    const wasLiked = !!_feedLikes[pid][uid];
    if (wasLiked) delete _feedLikes[pid][uid];
    else _feedLikes[pid][uid] = true;
    // Play the celebratory animation on like, subtle deflate on unlike
    if (btn) {
      if (!wasLiked) playLikeAnimation(btn);
      else playUnlikeAnimation(btn);
    }
    refreshFeedSocial();
    try {
      const ref = _db.ref(`shared/feedLikes/${pid}/${uid}`);
      if (wasLiked) await ref.remove();
      else await ref.set(true);
    } catch (e) {
      console.warn('toggleFeedLike failed', e);
      // Revert optimistic state on error
      if (wasLiked) _feedLikes[pid][uid] = true;
      else delete _feedLikes[pid][uid];
      refreshFeedSocial();
      toast(t('ui.257'));
    }
  }

  function playLikeAnimation(btn) {
    // Restart animation cleanly, even on rapid double-clicks
    btn.classList.remove('just-liked', 'just-unliked');
    void btn.offsetWidth;
    btn.classList.add('just-liked');
    spawnHeartParticles(btn);
    setTimeout(() => btn.classList.remove('just-liked'), 700);
  }
  function playUnlikeAnimation(btn) {
    btn.classList.remove('just-liked', 'just-unliked');
    void btn.offsetWidth;
    btn.classList.add('just-unliked');
    setTimeout(() => btn.classList.remove('just-unliked'), 400);
  }

  function spawnHeartParticles(btn) {
    const wrap = btn.querySelector('.heart-fx');
    if (!wrap) return;
    const symbols = ['❤', '♥', '❤'];
    for (let k = 0; k < 3; k++) {
      const p = document.createElement('span');
      p.className = 'heart-particle';
      p.textContent = symbols[k];
      const dx = (k - 1) * 12 + (Math.random() - .5) * 8;
      p.style.setProperty('--dx', `${dx.toFixed(1)}px`);
      p.style.animationDelay = `${k * 60}ms`;
      wrap.appendChild(p);
      setTimeout(() => p.remove(), 1000 + k * 60);
    }
  }

  async function submitFeedComment(pid, src) {
    if (typeof _db === 'undefined') { toast(t('ui.243')); return; }
    const card = src.closest('.feed-card');
    const input = card && card.querySelector(`.feed-comment-input[data-post-id="${pid}"]`);
    const text = input ? (input.value || '').trim() : '';
    if (!text) return;
    if (text.length > 500) { toast(t('ui.258')); return; }
    if (containsProfanity(text)) { toast(t('ui.259')); return; }
    const uid = socialUserId();
    const name = socialUserName();
    // В общий узел — только URL-аватар (крошечная строка). base64 (старые/гостевые
    // фото) НЕ вкладываем: сотни комментариев с вшитыми картинками раздули узел до
    // 40+ МБ, и каждый клиент скачивал его целиком при каждом заходе (инцидент 03.07).
    const avatar = (typeof UStore !== 'undefined') ? UStore.get('avatar') : null;
    const comment = { uid, name, text, ts: Date.now() };
    if (avatar && !isDataUrl(avatar)) comment.avatar = avatar;
    if (input) input.value = '';
    try {
      await _db.ref(`shared/feedComments/${pid}`).push(comment);
    } catch (e) {
      console.warn('submitFeedComment failed', e);
      if (input) input.value = text; // restore so user doesn't lose their comment
      toast(t('ui.260'));
    }
  }

  async function deleteFeedComment(pid, cid) {
    if (typeof _db === 'undefined') return;
    const me = socialUserId();
    const list = _feedComments[pid] || [];
    const target = list.find(c => c.id === cid);
    if (!target) return;
    if (target.uid !== me) { toast(t('ui.261')); return; }
    if (!confirm(t('ui.262'))) return;
    try {
      await _db.ref(`shared/feedComments/${pid}/${cid}`).remove();
    } catch (e) {
      console.warn('deleteFeedComment failed', e);
      toast(t('ui.126'));
    }
  }

  // ── Like a comment ──
  async function toggleCommentLike(pid, cid, btn) {
    if (typeof _db === 'undefined') { toast(t('ui.243')); return; }
    const uid = socialUserId();
    const list = _feedComments[pid] || [];
    const c = list.find(x => x.id === cid);
    if (!c) return;
    if (!c.likes) c.likes = {};
    const wasLiked = !!c.likes[uid];
    if (wasLiked) delete c.likes[uid];
    else c.likes[uid] = true;
    // Subtle button animation on like
    if (btn) {
      btn.classList.toggle('liked', !wasLiked);
      const icon = btn.querySelector('i');
      if (icon) icon.className = (!wasLiked ? 'fa-solid' : 'fa-regular') + ' fa-heart';
      const cnt = btn.querySelector('.comment-like-count');
      const newN = Object.keys(c.likes).length;
      if (cnt) cnt.textContent = newN || '';
      // Restart heartBeat keyframe via class kick
      if (!wasLiked) {
        btn.classList.remove('just-pop');
        void btn.offsetWidth;
        btn.classList.add('just-pop');
        setTimeout(() => btn.classList.remove('just-pop'), 600);
      }
    }
    try {
      const ref = _db.ref(`shared/feedComments/${pid}/${cid}/likes/${uid}`);
      if (wasLiked) await ref.remove();
      else await ref.set(true);
    } catch (e) {
      console.warn('toggleCommentLike failed', e);
      if (wasLiked) c.likes[uid] = true;
      else delete c.likes[uid];
      refreshFeedSocial();
      toast(t('ui.263'));
    }
  }

  // ── Inline reply form ──
  function toggleReplyForm(pid, cid, btn) {
    const item = btn.closest('.feed-comment-item');
    if (!item) return;
    const form = item.querySelector(`.reply-form-wrap[data-cid="${cid}"]`);
    if (!form) return;
    const willOpen = !form.classList.contains('open');
    // Close other open reply forms in this thread to keep things tidy
    item.closest('.feed-comments-list')?.querySelectorAll('.reply-form-wrap.open').forEach(f => {
      if (f !== form) f.classList.remove('open');
    });
    form.classList.toggle('open', willOpen);
    if (willOpen) {
      setTimeout(() => {
        const inp = form.querySelector('input');
        if (inp) try { inp.focus({ preventScroll: true }); } catch (_) { inp.focus(); }
      }, 60);
    }
  }

  async function submitReply(pid, cid, src) {
    if (typeof _db === 'undefined') { toast(t('ui.243')); return; }
    const form = src.closest('.reply-form-wrap');
    const input = form && form.querySelector('input');
    const text = input ? (input.value || '').trim() : '';
    if (!text) return;
    if (text.length > 500) { toast(t('ui.258')); return; }
    if (containsProfanity(text)) { toast(t('ui.259')); return; }
    const uid = socialUserId();
    const name = socialUserName();
    // Только URL-аватар — base64 в общий узел не пускаем (см. submitFeedComment)
    const avatar = (typeof UStore !== 'undefined') ? UStore.get('avatar') : null;
    const reply = { uid, name, text, ts: Date.now() };
    if (avatar && !isDataUrl(avatar)) reply.avatar = avatar;
    if (input) input.value = '';
    if (form) form.classList.remove('open');
    // Auto-expand replies block on this comment so the new reply is visible after re-render
    _expandedReplies.add(cid);
    try {
      await _db.ref(`shared/feedComments/${pid}/${cid}/replies`).push(reply);
    } catch (e) {
      console.warn('submitReply failed', e);
      if (input) input.value = text;
      if (form) form.classList.add('open');
      toast(t('ui.260'));
    }
  }

  // Like a reply (same flow as comment-like, just one level deeper in the tree)
  async function toggleReplyLike(pid, cid, rid, btn) {
    if (typeof _db === 'undefined') { toast(t('ui.243')); return; }
    const uid = socialUserId();
    const list = _feedComments[pid] || [];
    const c = list.find(x => x.id === cid);
    if (!c || !c.replies || !c.replies[rid]) return;
    const r = c.replies[rid];
    if (!r.likes) r.likes = {};
    const wasLiked = !!r.likes[uid];
    if (wasLiked) delete r.likes[uid];
    else r.likes[uid] = true;
    if (btn) {
      btn.classList.toggle('liked', !wasLiked);
      const icon = btn.querySelector('i');
      if (icon) icon.className = (!wasLiked ? 'fa-solid' : 'fa-regular') + ' fa-heart';
      const cnt = btn.querySelector('.reply-like-count');
      const newN = Object.keys(r.likes).length;
      if (cnt) cnt.textContent = newN || '';
      if (!wasLiked) {
        btn.classList.remove('just-pop');
        void btn.offsetWidth;
        btn.classList.add('just-pop');
        setTimeout(() => btn.classList.remove('just-pop'), 600);
      }
    }
    try {
      const ref = _db.ref(`shared/feedComments/${pid}/${cid}/replies/${rid}/likes/${uid}`);
      if (wasLiked) await ref.remove();
      else await ref.set(true);
    } catch (e) {
      console.warn('toggleReplyLike failed', e);
      if (wasLiked) r.likes[uid] = true;
      else delete r.likes[uid];
      refreshFeedSocial();
      toast(t('ui.263'));
    }
  }

  async function deleteReply(pid, cid, rid) {
    if (typeof _db === 'undefined') return;
    const me = socialUserId();
    const list = _feedComments[pid] || [];
    const c = list.find(x => x.id === cid);
    if (!c || !c.replies) return;
    const r = c.replies[rid];
    if (!r) return;
    if (r.uid !== me) { toast(t('ui.264')); return; }
    if (!confirm(t('ui.265'))) return;
    try {
      await _db.ref(`shared/feedComments/${pid}/${cid}/replies/${rid}`).remove();
    } catch (e) {
      console.warn('deleteReply failed', e);
      toast(t('ui.126'));
    }
  }

