  // ── Тур по приложению: экскурсия с Комдори (прожектор + карточка-шаг) ──
  // Запуск: первое закрытие тарифов после регистрации (tourPending), Настройки,
  // совет мишки. Прожектор — box-shadow вокруг цели; всё локально, ноль сети.
  const TOUR_STEPS = [
    { screen: 'home',    sel: '#bear-guide-slot .bear-guide, #bear-guide-slot', tk: 'tour.s1.t', sk: 'tour.s1.s' },
    { screen: 'home',    sel: '#daily-goal-widget',                tk: 'tour.s2.t', sk: 'tour.s2.s' },
    { screen: 'lessons', sel: '#lesson-path',                      tk: 'tour.s3.t', sk: 'tour.s3.s' },
    { screen: 'lessons', sel: '.lessons-bento',                    tk: 'tour.s4.t', sk: 'tour.s4.s' },
    { screen: 'games',   sel: '#screen-games .games-grid',         tk: 'tour.s5.t', sk: 'tour.s5.s' },
    { screen: 'social',  sel: '#friends-chat-section',             tk: 'tour.s6.t', sk: 'tour.s6.s' },
    { screen: 'profile', sel: '#profile-plan-slot, #auth-section', tk: 'tour.s7.t', sk: 'tour.s7.s' },
    { final: true, tk: 'tour.fin.t', sk: 'tour.fin.s' }
  ];
  let _tourIdx = 0, _tourSteps = [], _tourTarget = null, _tourRepos = null;
  function startAppTour() {
    document.getElementById('settings-modal')?.remove();
    document.getElementById('onboard')?.remove();
    document.getElementById('register-gate')?.remove();
    try { closePlanPage(); } catch (_) {}
    Store.set('tourDone', 1); // не предлагаем повторно, даже если бросят на полпути
    // Гостю показываем только открытые ему экраны
    _tourSteps = TOUR_STEPS.filter(s => s.final || !(s.screen in GUEST_LOCKED_SCREENS) || !isGuestish());
    _tourIdx = 0;
    if (!document.getElementById('app-tour')) {
      const el = document.createElement('div');
      el.id = 'app-tour';
      el.innerHTML = `<div class="tour-veil"></div><div class="tour-hole" id="tour-hole" onclick="tourNext()"></div><div class="tour-card" id="tour-card"></div>`;
      document.body.appendChild(el);
      _tourRepos = () => positionTourHole();
      window.addEventListener('resize', _tourRepos);
      window.addEventListener('scroll', _tourRepos, true);
    }
    paintTourStep();
  }
  function endAppTour() {
    document.getElementById('app-tour')?.remove();
    if (_tourRepos) {
      window.removeEventListener('resize', _tourRepos);
      window.removeEventListener('scroll', _tourRepos, true);
      _tourRepos = null;
    }
    _tourTarget = null;
    try { renderBearGuide(); } catch (_) {} // совет мишки зависит от tourDone
  }
  function tourNext() {
    _tourIdx++;
    if (_tourIdx >= _tourSteps.length) { endAppTour(); return; }
    paintTourStep();
  }
  function tourSkip() { endAppTour(); }
  function tourFinishLesson() {
    endAppTour();
    const cur = getCurrentLesson();
    if (cur) { try { startLessonFlow(cur.id); return; } catch (_) {} }
    switchScreen('lessons');
  }
  function _tourFindTarget(sel) {
    const els = document.querySelectorAll(sel);
    for (const el of els) {
      const r = el.getBoundingClientRect();
      if (r.width > 4 && r.height > 4) return el; // скрытые экраны дают 0×0
    }
    return null;
  }
  function positionTourHole() {
    const root = document.getElementById('app-tour');
    const hole = document.getElementById('tour-hole');
    const card = document.getElementById('tour-card');
    if (!root || !hole || !card) return;
    const isFinal = !_tourTarget;
    root.classList.toggle('final', isFinal);
    card.classList.toggle('final', isFinal);
    if (isFinal) { hole.style.display = 'none'; card.classList.remove('at-top'); return; }
    const r = _tourTarget.getBoundingClientRect();
    const pad = 8;
    hole.style.display = 'block';
    hole.style.top = (r.top - pad) + 'px';
    hole.style.left = Math.max(4, r.left - pad) + 'px';
    hole.style.width = Math.min(window.innerWidth - 8, r.width + pad * 2) + 'px';
    hole.style.height = (r.height + pad * 2) + 'px';
    // цель в нижней половине экрана — карточку наверх
    card.classList.toggle('at-top', (r.top + r.height / 2) > window.innerHeight * 0.55);
  }
  function paintTourStep() {
    const st = _tourSteps[_tourIdx];
    const card = document.getElementById('tour-card');
    if (!st || !card) return;
    if (!st.final) { try { switchScreen(st.screen); } catch (_) {} }
    const dots = _tourSteps.map((_, i) => `<span class="${i <= _tourIdx ? 'on' : ''}"></span>`).join('');
    card.innerHTML = `
      <img class="tour-bear" src="assets/bear1.png" alt="" onerror="this.style.display='none'">
      <div class="tour-card-body">
        <div class="tour-dots">${dots}</div>
        <div class="tour-title">${t(st.tk)}</div>
        <div class="tour-sub">${t(st.sk)}</div>
        <div class="tour-btns">
          <button class="btn btn-ghost" onclick="tourSkip()">${st.final ? t('gate.later') : t('tour.skip')}</button>
          ${st.final
            ? `<button class="btn btn-primary" onclick="tourFinishLesson()">${t('tour.startLesson')}</button>`
            : `<button class="btn btn-primary" onclick="tourNext()">${t('tour.next')}</button>`}
        </div>
      </div>`;
    if (st.final) { _tourTarget = null; positionTourHole(); return; }
    // дать экрану отрисоваться, затем навести прожектор
    requestAnimationFrame(() => requestAnimationFrame(() => {
      if (!document.getElementById('app-tour')) return;
      _tourTarget = _tourFindTarget(st.sel);
      if (!_tourTarget) { tourNext(); return; } // цели нет — тихо пропускаем шаг
      try { _tourTarget.scrollIntoView({ block: 'center' }); } catch (_) {}
      positionTourHole();
    }));
  }

  // ── Intro splash ──
  function dismissIntro() {
    const i = document.getElementById('intro');
    if (!i || i.classList.contains('dismissing')) return;
    i.classList.add('dismissing');
    setTimeout(() => i.remove(), 700);
    // Знакомство здесь не запускаем: новичок после заставки видит экран входа
    // (boot-роутинг), знакомство открывает первое нажатие «Регистрация» (showAuthTab),
    // мишка-гид или Настройки.
  }
  (function petals() {
    const layer = document.getElementById('intro-petals');
    if (!layer) return;
    const symbols = ['🌸','🌸','🌸','🌺','✿'];
    function spawn(initial) {
      if (!document.getElementById('intro')) return;
      const p = document.createElement('div');
      p.className = 'petal';
      const dur = 5 + Math.random() * 4;
      const size = 12 + Math.random() * 12;
      p.style.cssText = `left:${Math.random()*100}%; font-size:${size}px; animation-duration:${dur}s; animation-delay:${initial?-Math.random()*dur:0}s; opacity:${(0.55+Math.random()*0.4).toFixed(2)};`;
      p.textContent = symbols[Math.floor(Math.random()*symbols.length)];
      layer.appendChild(p);
      setTimeout(() => p.remove(), (dur+2)*1000);
    }
    for (let i = 0; i < 14; i++) spawn(true);
    const tid = setInterval(() => {
      if (!document.getElementById('intro')) { clearInterval(tid); return; }
      spawn();
    }, 380);
  })();
  setTimeout(() => { if (document.getElementById('intro')) dismissIntro(); }, 6000);

  // ── Ambient sakura (always-on, gentle) ──
  (function ambientPetals() {
    const layer = document.getElementById('ambient-petals');
    if (!layer) return;
    const symbols = ['🌸','🌸','🌸','🌺','✿'];
    function spawn() {
      if (document.hidden) return; // don't churn DOM while the tab is in the background
      const p = document.createElement('div');
      p.className = 'petal';
      const dur = 8 + Math.random() * 6;
      const size = 11 + Math.random() * 11;
      p.style.cssText = `left:${Math.random()*100}%; font-size:${size}px; animation-duration:${dur}s; opacity:${(0.45 + Math.random()*0.4).toFixed(2)};`;
      p.textContent = symbols[Math.floor(Math.random()*symbols.length)];
      layer.appendChild(p);
      setTimeout(() => p.remove(), (dur+2)*1000);
    }
    for (let i = 0; i < 6; i++) {
      const p = document.createElement('div');
      p.className = 'petal';
      const dur = 8 + Math.random() * 6;
      p.style.cssText = `left:${Math.random()*100}%; font-size:${11+Math.random()*11}px; animation-duration:${dur}s; animation-delay:${(-Math.random()*dur).toFixed(2)}s; opacity:${(0.45+Math.random()*0.4).toFixed(2)};`;
      p.textContent = symbols[Math.floor(Math.random()*symbols.length)];
      layer.appendChild(p);
    }
    setInterval(spawn, 1400);
  })();

  // ── Escape key closes the topmost overlay (modal → game → chat → lesson) ──
  document.addEventListener('keydown', e => {
    if (e.key !== 'Escape') return;
    const modals = document.querySelectorAll('.modal-bg');
    if (modals.length) { modals[modals.length - 1].remove(); return; }
    if (document.getElementById('writing-practice-page')) { closeWritingPractice(); return; }
    if (document.getElementById('user-profile-page')) { closeUserProfile(); return; }
    const gamePages = document.querySelectorAll('.game-page');
    if (gamePages.length) { closeGameModal(gamePages[gamePages.length - 1].id); return; }
    const complete = document.getElementById('lesson-complete-page');
    if (complete) { complete.remove(); return; }
    if (document.getElementById('chat-page')) { closeChat(); return; }
    if (document.getElementById('lesson-modal')) { closeLessonFlow(); return; }
  });

  // ── Init ──
  buildHeroSegments();
  buildWaveform();
  buildStreakCal();
  initHangulLab();
  renderCultureBanner();
  renderCustomVideos();
  renderCustomLessons();
  renderCustomFeedPosts();
  tagInteractive(); // keyboard-enable the initial home screen's clickable cards
  // Restore logged-in user (must come BEFORE loadUserData so namespace is correct)
  const savedUser = Store.get('user');
  if (savedUser && savedUser.name) {
    // Restore in-place without recursion
    Store.set('user', savedUser);
    const un = document.getElementById('user-name');
    const pn = document.getElementById('profile-name');
    if (un) un.textContent = savedUser.name;
    if (pn) pn.textContent = savedUser.name;
    const auth = document.getElementById('auth-section');
    const content = document.getElementById('profile-content');
    if (auth) auth.style.display = 'none';
    if (content) content.style.display = 'block';
    const email = document.getElementById('profile-email');
    if (email) email.textContent = savedUser.email || (savedUser.guest ? t('profile.guestMode') : t('profile.noEmail'));
    const adminBadge = document.getElementById('profile-admin-badge');
    if (adminBadge) adminBadge.style.display = savedUser.isAdmin ? 'inline-flex' : 'none';
    const sonbaeBadge2 = document.getElementById('profile-sonbae-badge');
    if (sonbaeBadge2) sonbaeBadge2.style.display = stats.sonbaeAwarded ? 'inline-flex' : 'none';
    setProfileAdminMode(!!savedUser.isAdmin);
  } else {
    // Гость, назвавший имя в знакомстве, — здороваемся по имени
    const obProf = Store.get('onboardProfile');
    if (obProf && obProf.name) {
      const un = document.getElementById('user-name');
      if (un) un.textContent = obProf.name;
    }
    // Самый первый вход (ни аккаунта, ни гостя): показываем экран входа —
    // оттуда «Регистрация» (→ знакомство с Мади) или «Продолжить как гость».
    try { switchScreen('profile'); } catch (_) {}
  }
  // Init Firebase sync first so UStore writes propagate to cloud
  initFirebaseSync();
  // Subscribe to feed-wide likes & comments (shared across users)
  attachFeedListeners();
  // Subscribe to the admins list (so login can match against the cloud copy)
  attachAdminsListener();
  // Now load per-user state (from current user's namespace, or guest if no login)
  loadUserData();
  // Subscribe to cloud updates for this user
  attachUserListeners();
  attachFriendsListeners();
  // Supabase OAuth (Kakao): подхватить сессию после возврата с провайдера
  try { initSupabaseSession(); } catch (_) {}
  // У Мади: собрать/освежить тонкий справочник usersPublic и увезти base64-медиа
  // (профили, лента) в Storage — после запуска приложения, чтобы не тормозить старт.
  setTimeout(async () => {
    try { await adminMigrateDirectory(); } catch (_) {}
    try { await adminMigrateFeedMedia(); } catch (_) {}
  }, 8000);
  // Achievement system
  recordDayEntered();
  startSessionTimer();
  checkAchievements(true, true); // silent + no XP re-credit — reconcile unlocks at startup without toast spam
  // If avatar exists in storage, mark hasAvatar achievement
  try { if (UStore.get('avatar') && !stats.hasAvatar) recordAvatarSet(); } catch (_) {}

  // ── Push notifications: try silent setup on every load (only registers if permission already granted) ──
  initPushNotifications();

  // ── Пользовательские настройки: применить при старте (лепестки/анимации) ──
  try { applySettings(); } catch (_) {}

  // ── Локализация интерфейса: применить выбранный язык к статичной разметке ──
  try { applyStaticI18n(); } catch (_) {}

  // ── PWA: always register the service worker (app-shell cache + install) ──
  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.register('/firebase-messaging-sw.js').catch(() => {});
  }
  // ── Presence heartbeat: bump users/{uid}/lastSeen while the tab is visible ──
  function bumpLastSeen() {
    if (typeof _db === 'undefined') return;
    const u = Store.get('user');
    if (!u || u.guest) return;
    const uid = firebaseUserId();
    if (!uid || uid === 'guest') return;
    try { _db.ref(`users/${uid}/lastSeen`).set(Date.now()); } catch (_) {}
    // Дублируем в тонкий справочник: оттуда статус «в сети» читают списки чатов
    try { _db.ref(`usersPublic/${uid}/lastSeen`).set(Date.now()); } catch (_) {}
  }
  bumpLastSeen();
  setInterval(() => { if (!document.hidden) bumpLastSeen(); }, 45000);
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) flushUserFieldPushes(); // leaving → save any pending changes now
    else bumpLastSeen();
  });
  // pagehide covers actual tab close / navigation away (more reliable than beforeunload on mobile).
  window.addEventListener('pagehide', flushUserFieldPushes);
  // Connection state: reassure the user and flush any queued writes on reconnect.
  window.addEventListener('offline', () => toast(t('net.offline'), 'var(--berry)'));
  window.addEventListener('online',  () => { toast(t('net.online'), 'var(--sage)'); flushUserFieldPushes(); });

  // ── Firebase Auth: keep local session in sync with auth state ──
  _auth.onAuthStateChanged(fbUser => {
    const local = Store.get('user');
    // Админ: локальный сеанс не трогаем, но с правил interim-2 чтения БД требуют
    // auth — без Firebase-сессии админке нужен перелогин (создаст/обновит сессию).
    if (local && local.isAdmin) {
      if (!fbUser && !window._authReloginHinted) {
        window._authReloginHinted = true;
        setTimeout(() => { try { toast(t('auth.sessionLost'), 'var(--berry)'); } catch (_) {} }, 2500);
      }
      return;
    }
    // Skip auth sync for guests — they don't use Firebase Auth
    if (local && local.guest) return;
    if (fbUser) {
      // Firebase confirms a session
      const fbName = fbUser.displayName || (fbUser.email || '').split('@')[0];
      if (!local || local.email !== fbUser.email) {
        setActiveUser({ name: fbName, email: fbUser.email, uid: fbUser.uid });
      } else if (!local.uid) {
        local.uid = fbUser.uid;
        Store.set('user', local);
      }
    } else {
      // Нет Firebase-сессии. Kakao-сессией управляет Supabase (fbUser всегда null) —
      // её здесь не трогаем, иначе Kakao-вход разлогинивается при каждой перезагрузке.
      // ВАЖНО: iOS Safari и вебвью (Instagram/Telegram) чистят indexedDB с сессией
      // Firebase агрессивнее, чем localStorage. Раньше мы тут мгновенно сбрасывали
      // профиль в гостя — у учениц «пропадал» весь XP до повторного входа (данные
      // целы, но экран показывал гостя). Синхронизация работает по ключу user_<email>
      // и auth-сессии не требует, поэтому профиль НЕ сбрасываем — оставляем ученицу
      // в аккаунте и один раз мягко просим войти заново (для сброса пароля и будущих
      // строгих правил БД сессия всё же нужна).
      if (local && !local.isAdmin && !local.guest && local.provider !== 'kakao') {
        if (!window._authReloginHinted) {
          window._authReloginHinted = true;
          setTimeout(() => { try { toast(t('auth.sessionLost'), 'var(--berry)'); } catch (_) {} }, 2500);
        }
      }
    }
  });
